            | Native::NodeZlibCreateGunzip
            | Native::NodeZlibCreateDeflate
            | Native::NodeZlibCreateInflate
            | Native::NodeZlibCreateUnzip
            | Native::NodeZlibCreateBrotliDecompress
            | Native::NodeZlibCreateDecompress
