/// Convert an owned host result at the Node Adapter boundary.
fn node_host_value(value: AsyncHostValue) -> Result<Value, ExecutionError> {
    Ok(match value {
        AsyncHostValue::Undefined => Value::Undefined,
        AsyncHostValue::Bytes(bytes) => {
            let length = bytes.len();
            Value::TypedArray(Rc::new(TypedArrayData {
                kind: TypedKind::Uint8,
                buffer: Rc::new(BufferData {
                    bytes: Bytes::new(false, bytes),
                    max_byte_length: None,
                    shared: false,
                    detached: std::cell::Cell::new(false),
                    immutable: false,
                    properties: RefCell::new(ObjectData::default()),
                }),
                offset: 0,
                length: Some(length),
                properties: RefCell::new(ObjectData::default()),
            }))
        }
        AsyncHostValue::FileStat(stat) => {
            let mut object = ObjectData::default();
            object.set("size", Value::Number(stat.size as f64));
            object.set_non_enumerable("@@kiln:node:is-file", Value::Boolean(stat.is_file));
            object.set_non_enumerable(
                "@@kiln:node:is-directory",
                Value::Boolean(stat.is_directory),
            );
            object.set(
                "isFile",
                Value::Native(Native::NodeStatIsFile, RealmId::PRIMARY),
            );
            object.set(
                "isDirectory",
                Value::Native(Native::NodeStatIsDirectory, RealmId::PRIMARY),
            );
            Value::Object(Rc::new(RefCell::new(object)))
        }
        AsyncHostValue::Resource(resource) => {
            return Err(ExecutionError::Host {
                instruction: 0,
                message: format!(
                    "persistent Node resource {} has no JavaScript representation yet",
                    resource.id.get()
                ),
            });
        }
        AsyncHostValue::AcceptedTcpStream(accepted) => {
            return Err(ExecutionError::Host {
                instruction: 0,
                message: format!(
                    "accepted Node resource {} has no JavaScript representation yet",
                    accepted.resource.id.get()
                ),
            });
        }
        AsyncHostValue::ProcessOutput(output) => {
            let mut object = ObjectData::default();
            object.set(
                "stdout",
                node_host_value(AsyncHostValue::Bytes(output.stdout))?,
            );
            object.set(
                "stderr",
                node_host_value(AsyncHostValue::Bytes(output.stderr))?,
            );
            object.set(
                "exitCode",
                output
                    .exit_code
                    .map_or(Value::Null, |code| Value::Number(code as f64)),
            );
            object.set(
                "signal",
                output
                    .signal
                    .map_or(Value::Null, |signal| Value::Number(signal as f64)),
            );
            Value::Object(Rc::new(RefCell::new(object)))
        }
        AsyncHostValue::ResourceState(state) => {
            return Err(ExecutionError::Host {
                instruction: 0,
                message: format!(
                    "Node resource state for {} must be consumed by its typed adapter",
                    state.info.id.get()
                ),
            });
        }
    })
}

/// `{ value, done }`, the shape every `next` returns.
fn iteration_result(value: Value, done: bool) -> Value {
    let mut result = ObjectData::default();
    result.set("value", value);
    result.set("done", Value::Boolean(done));
    Value::Object(Rc::new(RefCell::new(result)))
}

/// The trace recorded on an error object when it was constructed, if it is one.
fn captured_trace(thrown: &Value) -> Vec<String> {
    let Value::Object(object) = thrown else {
        return Vec::new();
    };
    match object.borrow().get_own(ERROR_TRACE) {
        Some(Value::Array(frames)) => frames
            .borrow()
            .iter()
            .map(Value::to_display_string)
            .collect(),
        _ => Vec::new(),
    }
}

/// How an uncaught value is described. An error renders through its `toString`; anything else
/// through its ordinary string form, because JavaScript lets you throw any value.
fn describe_thrown(value: &Value) -> String {
    if has_error_to_string(value) {
        error_to_string(value)
    } else {
        value.to_display_string()
    }
}

/// Whether a value inherits `Error.prototype.toString`.
fn has_error_to_string(value: &Value) -> bool {
    match value {
        Value::Object(object) => matches!(
            object.borrow().get("toString"),
            Some(Value::Native(Native::ErrorToString, _))
        ),
        _ => false,
    }
}

/// `Error.prototype.toString`: `name`, then `: message` when the message is non-empty.
fn error_to_string(value: &Value) -> String {
    let Value::Object(object) = value else {
        return "Error".to_owned();
    };
    let object = object.borrow();
    let name = match object.get("name") {
        Some(Value::Undefined) | None => "Error".to_owned(),
        Some(other) => other.to_display_string(),
    };
    let message = match object.get("message") {
        Some(Value::Undefined) | None => String::new(),
        Some(other) => other.to_display_string(),
    };
    if message.is_empty() {
        name
    } else {
        format!("{name}: {message}")
    }
}

/// The name read from a constructor value in an object's prototype chain.
fn constructor_name(value: &Value) -> Option<String> {
    match value {
        Value::Function(closure) => match closure.properties.borrow().get_own("name") {
            Some(Value::String(name)) => Some(name.to_lossy_string()),
            _ => None,
        },
        Value::Native(Native::Error(kind), _) => Some(kind.name().to_owned()),
        _ => None,
    }
}

/// `value instanceof constructor`.
///
/// Walks the value's prototype chain looking for the constructor's `prototype` *by identity*.
/// Comparing anything else -- shape, name -- would call two unrelated classes the same one.
///
/// A right-hand side that is not a function is a TypeError in JavaScript. There is nothing to
/// throw with yet, so it answers false; that is wrong, and it is the direction that produces a
/// visibly wrong answer rather than a silently corrupt one.
#[cfg(test)]
fn instance_of(value: &Value, constructor: &Value, error_prototype: Option<&Value>) -> bool {
    let prototype = match constructor {
        Value::Function(closure) => match closure.prototype.borrow().clone() {
            Some(prototype) => prototype,
            // A constructor never used with `new` and never read has no prototype object yet,
            // so nothing can descend from it.
            None => return false,
        },
        // A native constructor's prototype is the realm's, not one per closure.
        Value::Native(Native::Error(_), _) => match error_prototype {
            Some(prototype) => prototype.clone(),
            None => return false,
        },
        // These have no prototype object to walk -- each is its own value kind -- so the test is
        // what the chain would have answered.
        Value::Native(Native::PromiseConstructor, _) => {
            return matches!(value, Value::Promise(_));
        }
        Value::Native(Native::DateConstructor, _) => return matches!(value, Value::Date(_)),
        // An `Intl` value is an instance of its own service and of nothing else: a `Collator`
        // is not an `Intl.NumberFormat` even though both are `Value::Intl`.
        Value::Native(Native::Intl(intl::Op::Constructor(service)), _) => {
            return matches!(value, Value::Intl(built) if built.service() == *service);
        }
        Value::Native(Native::RegExpConstructor, _) => return matches!(value, Value::RegExp(_)),
        Value::Native(Native::ArrayConstructor, _) => return matches!(value, Value::Array(_)),
        // A view is an instance of the constructor that names its element type, and of nothing
        // else: `new Uint8Array(1) instanceof Int8Array` is false.
        Value::Native(Native::TypedArrayConstructor(kind), _) => {
            return matches!(value, Value::TypedArray(view) if view.kind == *kind);
        }
        // The two buffer types are told apart by their flag and by nothing else: a shared
        // buffer is not an `ArrayBuffer`, which is what makes `ArrayBuffer.isView` and every
        // brand check in the specification able to refuse it.
        Value::Native(Native::ArrayBufferConstructor, _) => {
            return matches!(value, Value::ArrayBuffer(buffer) if !buffer.shared);
        }
        Value::Native(Native::SharedArrayBufferConstructor, _) => {
            return matches!(value, Value::ArrayBuffer(buffer) if buffer.shared);
        }
        Value::Native(Native::DataViewConstructor, _) => {
            return matches!(value, Value::DataView(_));
        }
        // Every iterator this realm makes inherits `%IteratorPrototype%`, and `Iterator` is what
        // that prototype belongs to. The marker is the same one method lookup uses, so a value
        // cannot answer `map` and then deny being an iterator. A guard rather than an arm: a
        // value that carries no marker still gets the ordinary chain walk below, which is what
        // answers for an iterator a program wrote by extending `Iterator` itself.
        Value::Native(Native::IteratorConstructor, _)
            if match value {
                Value::Generator(_) => true,
                Value::Object(object) => {
                    let object = object.borrow();
                    object.get_own("@@iterated").is_some()
                        || object.get_own(HELPER_SOURCE).is_some()
                }
                _ => false,
            } =>
        {
            return true;
        }
        // A Set or Map is an object carrying reserved state, so the test is for that state
        // rather than for a prototype the realm does not yet have as an object.
        Value::Native(kind @ (Native::SetConstructor | Native::MapConstructor), _) => {
            let Value::Object(object) = value else {
                return false;
            };
            let object = object.borrow();
            return object.get_own("@@entries").is_some()
                && object.get_own("@@map").is_some() == matches!(kind, Native::MapConstructor);
        }
        // Any other built-in that has a `prototype`: the chain is walked against it, which is
        // what makes `Object instanceof Object` true -- `Object` is a function, so its chain
        // reaches `Function.prototype` and then `Object.prototype`, which is what it is being
        // compared against. A plain-object check asks exactly that.
        Value::Native(native, _) => match native.property("prototype") {
            Some(table) => table,
            None => return false,
        },
        _ => return false,
    };

    // Bounded like every other prototype walk: the chain belongs to the program, and running out
    // of Rust stack -- or looping -- is not a way to answer a question.
    let mut current = prototype_of(value);
    for _ in 0..MAX_PROTOTYPE_DEPTH {
        if matches!(current, Value::Null) {
            return false;
        }
        if strict_equal(&current, &prototype) {
            return true;
        }
        current = prototype_of(&current);
    }
    false
}

/// A value's `[[Prototype]]`, or `Value::Null` at the end of the chain.
///
/// One function so `Object.getPrototypeOf` and `instanceof` cannot disagree about the shape of
/// the chain -- which is the sort of disagreement that makes `x instanceof C` false for an `x`
/// the program just built.
/// The realm a value belongs to: `GetFunctionRealm` for a callable, the marker's own realm for
/// an intrinsic, and the primary realm for everything else.
///
/// Only the two `Copy` markers and a closure carry a realm of their own. Every other value
/// expresses the realm it was made in through its `[[Prototype]]`, which is what the
/// specification says the difference *is*: an array built in realm 1 links to realm 1's
/// `Array.prototype` and is otherwise an ordinary array.
fn value_realm(value: &Value) -> RealmId {
    match value {
        Value::Native(_, realm) | Value::Callback(_, realm) => *realm,
        Value::Function(closure) => closure.realm,
        // A bound function and a proxy both answer for what they wrap, which is what
        // `GetFunctionRealm` says: neither has a realm of its own to report.
        Value::Bound(bound) => value_realm(&bound.target),
        // A wrapped function does *not*, and this is the line that keeps the boundary honest.
        // It has a realm of its own -- the caller's -- and answering with its target's would
        // send every `TypeError` it raises back into the realm the caller must not see, and
        // hand it that realm's `Error.prototype` to inspect.
        Value::Wrapped(wrapped) => wrapped.realm,
        Value::Proxy(proxy) => value_realm(&proxy.target),
        _ => RealmId::PRIMARY,
    }
}

/// Rewrite an intrinsic minted by a table so that it names `realm`'s copy of that built-in.
///
/// The property tables are pure and realm-blind by design -- `Native::property` cannot be handed
/// a receiver -- so they mint every intrinsic in the primary realm and the caller retags what
/// comes back from the receiver it asked. Anything that is not a marker is returned untouched,
/// because it is not an intrinsic: a value a program *stored* on a built-in keeps whatever realm
/// it already had.
fn in_realm(value: Value, realm: RealmId) -> Value {
    if realm == RealmId::PRIMARY {
        return value;
    }
    match value {
        Value::Native(native, RealmId::PRIMARY) => Value::Native(native, realm),
        Value::Callback(method, RealmId::PRIMARY) => Value::Callback(method, realm),
        other => other,
    }
}

fn prototype_of(value: &Value) -> Value {
    let realm = value_realm(value);
    // A subclassed value keeps its prototype with its other non-element properties, which is what
    // makes `new (class extends Array {})() instanceof that class` true -- and, through the same
    // store, what makes it true of a view, a buffer, a regexp and a bound function as well.
    let recorded = prototype_slot(value).and_then(|slot| slot.borrow().prototype().cloned());
    if let Some(link) = recorded {
        return link;
    }
    match value {
        // `Object.prototype` is the end of every chain; the other tables inherit from it.
        Value::Native(Native::PrototypeOf(PrototypeTable::Object), _) => Value::Null,
        // The one two-level chain among the tables: `Int8Array.prototype` inherits from
        // `%TypedArray%.prototype`, which is where the shared methods live and is why
        // `Int8Array.prototype.map` finds one at all.
        Value::Native(Native::PrototypeOf(PrototypeTable::TypedArrayFor(_)), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::TypedArray), realm)
        }
        // The five built-in iterator prototypes and the two generator ones all sit on
        // `%IteratorPrototype%`, which is where the helpers live and what `instanceof Iterator`
        // walks to. Falling to `Object.prototype` with the arm below broke exactly that:
        // `Iterator.from(x)` must hand back `x` when it is already an iterator, and stopped.
        Value::Native(
            Native::AsyncGeneratorFunctionConstructor | Native::GeneratorFunctionConstructor,
            _,
        ) => Value::Native(Native::FunctionConstructor, realm),
        Value::Native(
            Native::AsyncGeneratorFunctionPrototype | Native::GeneratorFunctionPrototype,
            _,
        ) => Value::Native(Native::PrototypeOf(PrototypeTable::Function), realm),
        Value::Native(Native::PrototypeOf(PrototypeTable::AsyncGenerator), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::AsyncIterator), realm)
        }
        Value::Native(Native::PrototypeOf(PrototypeTable::AsyncIterator), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm)
        }
        Value::Native(
            Native::PrototypeOf(
                PrototypeTable::IteratorFor(_)
                | PrototypeTable::Generator,
            ),
            _,
        ) => Value::Native(Native::PrototypeOf(PrototypeTable::Iterator), realm),
        Value::Native(Native::PrototypeOf(_), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm)
        }
        // Each `Intl` instance links to its own service's prototype, and each of those to
        // `Object.prototype`. Without the first link `Object.getPrototypeOf(new Intl.Collator())`
        // is null and every method on it is found only because the value kind answers directly --
        // which is a chain a program can see is missing.
        Value::Intl(built) => {
            Value::Native(Native::Intl(intl::Op::Prototype(built.service())), realm)
        }
        Value::Native(Native::Intl(intl::Op::Prototype(_) | intl::Op::Namespace), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm)
        }
        // Each of the eight `Temporal` types links to its own prototype, for exactly the reason
        // an `Intl` formatter links to its service's. Without it the chain a `Temporal` value
        // reports is empty, and `d instanceof Temporal.PlainDate` is false for a `d` the program
        // built one line earlier -- a wrong answer rather than a missing one, because
        // `d.constructor === Temporal.PlainDate` was already true and the brand tag already read
        // `[object Temporal.PlainDate]`. The methods were found regardless because the value kind
        // answers them itself, which is why the missing link stayed invisible until something
        // walked the chain.
        Value::Temporal(built) => Value::Native(
            Native::Temporal(temporal::Op::Prototype(built.kind())),
            realm,
        ),
        // And each of those eight prototypes is an ordinary object inheriting `Object.prototype`.
        // It is not a callable, so it must not take the arm below and claim `Function.prototype`:
        // `Object.getPrototypeOf(Temporal.PlainDate.prototype)` is what a program checks, and
        // `Temporal.PlainDate.prototype instanceof Function` must be false.
        Value::Native(Native::Temporal(temporal::Op::Prototype(_)), _) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm)
        }
        // The nine view constructors inherit from `%TypedArray%` rather than straight from
        // `Function.prototype`, which is the only way a program can name the abstract
        // constructor: `Object.getPrototypeOf(Int8Array)` is what every use of it starts from.
        Value::Native(Native::TypedArrayConstructor(_), _) => {
            Value::Native(Native::TypedArrayIntrinsic, realm)
        }
        // NativeError constructors inherit static properties from Error, just as the built-in
        // constructors do in ECMAScript. This is also what makes `TypeError.isError` resolve as an
        // inherited method rather than an accidental own property.
        Value::Native(Native::Error(kind), _) if *kind != ErrorKind::Error => {
            Value::Native(Native::Error(ErrorKind::Error), realm)
        }
        // `Math`, `JSON`, `Reflect` and `Atomics` are ordinary objects, not functions: none of
        // them is callable, and `Object.getPrototypeOf(Math)` is `Object.prototype`. Spelled as
        // natives here, they were taking the callable arm below and claiming `Function.prototype`
        // -- which made `Math instanceof Function` true and put `call` and `apply` on a value
        // that has no call behaviour to bind.
        Value::Native(native, _) if namespace_name(native).is_some() => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm)
        }
        // Every callable inherits `Function.prototype`, and every ordinary object
        // `Object.prototype`. A primitive has no chain of its own to walk. The two the promise
        // machinery makes are callables too -- a program is handed `resolve` and `reject` and can
        // ask what they inherit from, and answering null said they were not functions at all.
        Value::Function(closure) => {
            if let Some(table) = generator_prototype_table(closure) {
                match table {
                    PrototypeTable::AsyncGenerator => {
                        Value::Native(Native::AsyncGeneratorFunctionPrototype, realm)
                    }
                    PrototypeTable::Generator => {
                        Value::Native(Native::GeneratorFunctionPrototype, realm)
                    }
                    _ => Value::Native(Native::PrototypeOf(PrototypeTable::Function), realm),
                }
            } else {
                Value::Native(Native::PrototypeOf(PrototypeTable::Function), realm)
            }
        }
        Value::Native(_, _)
        | Value::Bound(_)
        // A wrapped function's `realm` is its own -- the caller's -- so this reads
        // `Function.prototype` *of the realm that made the wrapper*, which is precisely what
        // `WrappedFunctionCreate` sets and what a program checks with `getPrototypeOf`.
        | Value::Wrapped(_)
        | Value::Callback(_, _)
        | Value::Settler(..)
        | Value::Capability(_) | Value::Element(_) => {
            Value::Native(Native::PrototypeOf(PrototypeTable::Function), realm)
        }
        Value::Array(_) => Value::Native(Native::PrototypeOf(PrototypeTable::Array), realm),
        // A date is a value kind rather than an object here, and without this link
        // `Date.prototype.isPrototypeOf(new Date())` is false -- a chain a program can see is
        // missing, and the one every `instanceof Date` walks.
        Value::Date(_) => Value::Native(Native::PrototypeOf(PrototypeTable::Date), realm),
        Value::Promise(_) => Value::Native(Native::PrototypeOf(PrototypeTable::Promise), realm),
        // A generator inherits from its *function's* `prototype`, exactly as an instance does --
        // and that object now points at `%GeneratorPrototype%`. This answered null, so every walk
        // of a generator's chain ended before it reached a method.
        Value::Generator(state) => prototype_object(&state.borrow().closure),
        // A regexp is a value kind here rather than an object, and without this link
        // `/x/ instanceof RegExp` is false and `RegExp.prototype.isPrototypeOf(/x/)` denies it --
        // a chain a program can see is missing, and the one every brand check walks.
        Value::RegExp(_) => Value::Native(Native::PrototypeOf(PrototypeTable::RegExp), realm),
        Value::Object(_) => Value::Native(Native::PrototypeOf(PrototypeTable::Object), realm),
        Value::ArrayBuffer(buffer) => Value::Native(
            Native::PrototypeOf(if buffer.shared {
                PrototypeTable::SharedArrayBuffer
            } else {
                PrototypeTable::ArrayBuffer
            }),
            realm,
        ),
        Value::DataView(_) => Value::Native(Native::PrototypeOf(PrototypeTable::DataView), realm),
        Value::TypedArray(view) => Value::Native(
            Native::PrototypeOf(PrototypeTable::TypedArrayFor(view.kind)),
            realm,
        ),
        _ => Value::Null,
    }
}

/// Whether `Type(value)` is Object, in the specification's sense.
///
/// The reflection statics all begin by asking it: `Object.isFrozen`, `Object.isSealed` and
/// `Object.isExtensible` each answer for a primitive by definition and have to *look* for an
/// object. Spelled once rather than as a `_` arm in each, because the two that had one disagreed
/// -- `Object.isFrozen(Object)` was `true` while `Object.isSealed(Object)` was `false`, which no
/// object can be at once.
fn is_object_type(value: &Value) -> bool {
    !matches!(
        value,
        Value::Undefined
            | Value::Null
            | Value::Boolean(_)
            | Value::Number(_)
            | Value::String(_)
            | Value::BigInt(_)
            | Value::Symbol(_)
            | Value::Cell(_)
    )
}

/// `key in target`.
fn has_property_checked(
    intrinsics: &Intrinsics,
    target: &Value,
    key: &Value,
) -> Result<bool, ExecutionError> {
    let units = key.property_key_units_checked()?;
    Ok(has_property_key(
        intrinsics,
        target,
        PropertyKeyRef::Units(&units),
    ))
}

#[cfg(test)]
fn has_property(intrinsics: &Intrinsics, target: &Value, key: &Value) -> bool {
    has_property_checked(intrinsics, target, key).expect("test property-key conversion")
}

fn has_property_key(intrinsics: &Intrinsics, target: &Value, key: PropertyKeyRef<'_>) -> bool {
    if let Value::Array(items) = target
        && let Some(index) = array_index_key(key)
    {
        if array_exotic_element(items, index).is_some()
            || items
                .borrow()
                .get(index)
                .is_some_and(|value| !matches!(value, Value::Native(Native::Hole, _)))
        {
            return true;
        }
        return array_inherited_index_key(intrinsics, items, key).is_some();
    }
    if let Value::TypedArray(view) = target
        && let Some(index) = canonical_numeric_index_key(key)
    {
        return valid_integer_index(view, index).is_some();
    }
    if let Value::String(text) = target
        && (key.matches_ascii("length")
            || array_index_key(key).is_some_and(|index| index < text.unit_len()))
    {
        return true;
    }
    let Some(name) = key.known_ascii() else {
        return match target {
            Value::Object(object) => object.borrow().lookup_key(key).is_some(),
            Value::Function(closure) => closure.properties.borrow().lookup_key(key).is_some(),
            Value::Array(items) => items.properties.borrow().lookup_key(key).is_some(),
            Value::Bound(bound) => bound.properties.borrow().lookup_key(key).is_some(),
            Value::Native(_, _) | Value::Callback(_, _) => {
                matches!(intrinsics.overridden_key(target, key), Overridden::Held(..))
            }
            other => exotic_properties(other)
                .is_some_and(|store| store.borrow().lookup_key(key).is_some()),
        };
    };
    has_property_ascii(intrinsics, target, name.as_ref())
}

fn has_property_ascii(intrinsics: &Intrinsics, target: &Value, name: &str) -> bool {
    // `1 in [1, , 3]` is false and `1 in [1, undefined, 3]` is true: the one place the difference
    // between a hole and an undefined element is directly observable.
    if let Value::Array(items) = target
        && let Some(index) = array_index_key(PropertyKeyRef::Utf8(name))
    {
        if array_exotic_element(items, index).is_some() {
            return true;
        }
        if items
            .borrow()
            .get(index)
            .is_some_and(|value| !matches!(value, Value::Native(Native::Hole, _)))
        {
            return true;
        }
        // A hole is the absence of an own property, so the question carries on up the chain.
        return array_inherited_index(intrinsics, items, name).is_some();
    }
    // Every element key is the view's own answer, whether or not it reaches a slot: `"1.5" in
    // sample` is false because no view has such an element, not because the store is empty.
    if let Value::TypedArray(view) = target
        && let Some(index) = canonical_numeric_index(name)
    {
        return valid_integer_index(view, index).is_some();
    }
    // Every intrinsic kind answers `constructor` with the built-in that makes it, so `in` has to
    // agree with the read rather than only with the property store.
    if name == "constructor"
        && (intrinsic_constructor(target).is_some() || matches!(target, Value::Object(_)))
    {
        return true;
    }
    match target {
        // The chain ends at `Object.prototype`, whose methods every object has -- so
        // `"toString" in x` is true, and so is the `"hasOwnProperty" in x` that half the
        // feature-detects in the wild are written as. Answering from the own store alone made
        // both false, which is a wrong answer that reads like a deliberate one.
        Value::Object(object) => {
            object.borrow().lookup(&name).is_some()
                || string_exotic(target, &name).is_some()
                // The chain may end at a built-in's method table -- a wrapper's does, and so
                // does a class that extends one -- which `lookup` cannot walk into. `in` has to
                // agree with the read that does. `own_attributes` rather than the table's own
                // `property`, because a program may have *added* a name to `String.prototype`
                // and the table alone answers only for what it was built with: `new String()`
                // read `String.prototype.zz` correctly and denied it to `in`.
                || object
                    .borrow()
                    .prototype_table()
                    .is_some_and(|(table, realm)| {
                        own_attributes(
                            intrinsics,
                            &Value::Native(
                                Native::PrototypeOf(table),
                                realm.unwrap_or(RealmId::PRIMARY),
                            ),
                            &name,
                        )
                        .is_some()
                    })
                || !matches!(inherited_object_property(intrinsics, &name, value_realm(target)), Value::Undefined)
                // A property the program *defined* on `Object.prototype` that reads as
                // undefined is still there: an accessor given only a setter answers `undefined`
                // to a read and `true` to `in`, and asking the read whether it found anything
                // cannot tell those apart. Every generic array walk consults `HasProperty`, so
                // the difference decides whether an index is visited at all. Only the realm's
                // store is consulted, not the table beneath it: a module namespace has no
                // prototype at all, and the table would hand one `__proto__` and `toString`.
                || matches!(
                    intrinsics.overridden(
                        &Value::Native(Native::PrototypeOf(PrototypeTable::Object), RealmId::PRIMARY),
                        &name,
                    ),
                    Overridden::Held(..)
                )
        }
        Value::Array(items) => {
            if let Some(index) = array_index_key(PropertyKeyRef::Utf8(name)) {
                return index < items.borrow().len();
            }
            // An array carries a property store beside its elements -- `arr.value = 1` goes
            // there -- and it has to be consulted first, or `in` disagrees with the read that
            // finds it. Methods and `length` live on the prototype in a real engine; here the
            // property lookup answers for both, so `in` has to agree with that too.
            items.properties.borrow().lookup(&name).is_some()
                || name == "length"
                || !matches!(array_property(&name), Value::Undefined)
                // A name the program put on `Array.prototype` is on the chain too, and only the
                // realm's store knows about it. Without this step `Array.prototype.value = 1`
                // read through every array and answered `false` to `"value" in arr` -- which is
                // the question `ToPropertyDescriptor` asks of an array used as a descriptor.
                || own_attributes(
                    intrinsics,
                    &Value::Native(Native::PrototypeOf(PrototypeTable::Array), RealmId::PRIMARY),
                    &name,
                )
                .is_some()
                || !matches!(
                    inherited_object_property(intrinsics, &name, value_realm(target)),
                    Value::Undefined
                )
        }
        // Every element key was answered above, so what is left is a named one: the store
        // beside the view first, so `in` agrees with the read that finds it, and then the chain.
        Value::TypedArray(view) => {
            view.properties.borrow().lookup(&name).is_some()
                || matches!(
                    name,
                    "length" | "byteLength" | "byteOffset" | "BYTES_PER_ELEMENT" | "buffer"
                )
                // The same two links the read walks, so `in` and the read cannot disagree about
                // a name a program put on either view prototype.
                || own_attributes(
                    intrinsics,
                    &Value::Native(Native::PrototypeOf(PrototypeTable::TypedArrayFor(view.kind)), RealmId::PRIMARY),
                    &name,
                )
                .is_some()
                || !matches!(typed_array_method(&name), Value::Undefined)
                || own_attributes(
                    intrinsics,
                    &Value::Native(Native::PrototypeOf(PrototypeTable::TypedArray), RealmId::PRIMARY),
                    &name,
                )
                .is_some()
                || !matches!(
                    inherited_object_property(intrinsics, &name, value_realm(target)),
                    Value::Undefined
                )
        }
        // A buffer, a view and a regexp answer from their store and then from the prototype
        // their kind links to, which is where every accessor and method they publish lives.
        // Answering `false` for all of them made `"byteLength" in buffer` deny a property the
        // read right beside it produces.
        other if exotic_properties(other).is_some() => {
            exotic_properties(target).is_some_and(|store| store.borrow().lookup(&name).is_some())
                || exotic_reserved_name(target, &name)
                || own_attributes(intrinsics, &prototype_of(target), &name).is_some()
                || !matches!(
                    inherited_object_property(intrinsics, &name, value_realm(target)),
                    Value::Undefined
                )
        }
        // Mirrors the read: the realm's store first, then the table, then the `name` and
        // `length` every callable owns. A property a program deleted is absent here too, or
        // `delete` and the `in` after it would disagree.
        Value::Native(native, _) => {
            let own = match intrinsics.overridden(target, &name) {
                Overridden::Held(..) => true,
                Overridden::Absent => false,
                Overridden::Untouched => {
                    // `intrinsic_owns` rather than `property`, which is what a *read* finds and
                    // is a different question. A prototype table's `property` carries its last
                    // step up to `Object.prototype` and answers `Some(Undefined)` for a name it
                    // does not have at all, so asking it made `in` true for every string on
                    // every built-in prototype in the realm -- `"nope" in Array.prototype` among
                    // them, which is worse than useless to the feature-detects that ask it. The
                    // ownership test is the one `hasOwnProperty` and `getOwnPropertyNames`
                    // already agree on; the step up to `Object.prototype` is taken below, so
                    // `"hasOwnProperty" in Array.prototype` stays true.
                    intrinsic_owns(*native, &name).is_some()
                        || identity_property(target, &name).is_some()
                        || (matches!(native, Native::Error(kind) if *kind != ErrorKind::Error)
                            && name == "isError"
                            && !matches!(
                                intrinsics.overridden(
                                    &Value::Native(
                                        Native::Error(ErrorKind::Error),
                                        RealmId::PRIMARY
                                    ),
                                    &name,
                                ),
                                Overridden::Absent
                            ))
                }
            };
            // `Math` and `JSON` are ordinary objects that inherit from `Object.prototype`, and so
            // is every constructor and method table but that one. Answering from the built-in's
            // own names alone denied them `hasOwnProperty`, and denied `Math` a property the
            // program had put on `Object.prototype` and could read straight off it.
            own || (!matches!(native, Native::PrototypeOf(PrototypeTable::Object))
                && !matches!(
                    inherited_object_property(intrinsics, &name, value_realm(target)),
                    Value::Undefined
                ))
        }
        // Mirrors the read: a function answers from its own store, then from `name`, `length`
        // and `prototype`, then from the methods every callable inherits. `in` has to agree with
        // what a read would produce, or a feature-detect and the call after it disagree.
        Value::Function(closure) => {
            closure.properties.borrow().lookup(&name).is_some()
                || matches!(name, "name" | "length")
                || (name == "prototype" && has_prototype_property(closure))
                || !matches!(
                    function_property(intrinsics, &name, value_realm(target)),
                    Value::Undefined
                )
        }
        _ => false,
    }
}

#[derive(Clone, Debug)]
pub struct CollectionKey(pub Value);

impl PartialEq for CollectionKey {
    fn eq(&self, other: &Self) -> bool {
        same_value_zero(&self.0, &other.0)
    }
}

impl Eq for CollectionKey {}

impl std::hash::Hash for CollectionKey {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        std::mem::discriminant(&self.0).hash(state);
        match &self.0 {
            Value::Undefined | Value::Null => {}
            Value::Boolean(b) => b.hash(state),
            Value::Number(n) => {
                if n.is_nan() {
                    0x7ff8_0000_0000_0000_u64.hash(state);
                } else if *n == 0.0 {
                    0.0_f64.to_bits().hash(state);
                } else {
                    n.to_bits().hash(state);
                }
            }
            Value::String(s) => s.hash(state),
            Value::BigInt(b) => b.hash(state),
            Value::Symbol(Symbol::WellKnown(wk)) => {
                std::mem::discriminant(wk).hash(state);
            }
            Value::Symbol(Symbol::Unique(u)) => {
                (Rc::as_ptr(u) as usize).hash(state);
            }
            Value::Native(nat, realm) => {
                std::mem::discriminant(nat).hash(state);
                realm.hash(state);
            }
            Value::Callback(cb, realm) => {
                std::mem::discriminant(cb).hash(state);
                realm.hash(state);
            }
            Value::Settler(p, one) => {
                (Rc::as_ptr(p) as usize).hash(state);
                one.hash(state);
            }
            Value::Cell(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Generator(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Promise(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::RegExp(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Date(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Temporal(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Intl(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Capability(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Element(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Array(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::TypedArray(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::ArrayBuffer(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::DataView(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Proxy(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Bound(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Wrapped(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::CommonJsRequire(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::CommonJsResolve(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Object(a) => (Rc::as_ptr(a) as usize).hash(state),
            Value::Function(a) => (Rc::as_ptr(a) as usize).hash(state),
        }
    }
}

/// Where a collection's backing entries hold this key, or `None`.
#[allow(clippy::mutable_key_type)]
fn find_collection_entry(entries: &Rc<ArrayData>, key: &Value, is_map: bool) -> Option<usize> {
    if entries.borrow().len() < 16 {
        return find_entry(&entries.borrow(), key, is_map);
    }
    let mut index_opt = entries.collection_index.borrow_mut();
    let index_map = index_opt.get_or_insert_with(|| {
        let mut map = std::collections::HashMap::new();
        for (idx, entry) in entries.borrow().iter().enumerate() {
            match entry {
                Value::Native(Native::Tombstone, _) => {}
                Value::Array(pair) if is_map => {
                    if let Some(k) = pair.borrow().first() {
                        map.entry(CollectionKey(k.clone())).or_insert(idx);
                    }
                }
                other if !is_map => {
                    map.entry(CollectionKey(other.clone())).or_insert(idx);
                }
                _ => {}
            }
        }
        map
    });
    index_map.get(&CollectionKey(key.clone())).copied()
}

#[allow(clippy::mutable_key_type)]
fn collection_entry_inserted(entries: &Rc<ArrayData>, key: &Value, index: usize) {
    if let Some(index_map) = entries.collection_index.borrow_mut().as_mut() {
        index_map.insert(CollectionKey(key.clone()), index);
    }
}

#[allow(clippy::mutable_key_type)]
fn collection_entry_deleted(entries: &Rc<ArrayData>, key: &Value) {
    if let Some(index_map) = entries.collection_index.borrow_mut().as_mut() {
        index_map.remove(&CollectionKey(key.clone()));
    }
}

#[allow(clippy::mutable_key_type)]
fn collection_cleared(entries: &Rc<ArrayData>) {
    if let Some(index_map) = entries.collection_index.borrow_mut().as_mut() {
        index_map.clear();
    }
}

/// The properties an array exposes, shared by reads and by `in` so the two cannot disagree.
/// The index of `key` among live entries, or `None`.
fn find_entry(entries: &[Value], key: &Value, is_map: bool) -> Option<usize> {
    entries.iter().position(|entry| match entry {
        Value::Native(Native::Tombstone, _) => false,
        Value::Array(pair) if is_map => pair
            .borrow()
            .first()
            .is_some_and(|existing| same_value_zero(existing, key)),
        other => !is_map && same_value_zero(other, key),
    })
}

/// Where a collection keeps its count.
///
/// Reserved rather than spelled `size`, because a plain property of that name *is* an own
/// property: `Object.getOwnPropertyNames(new Map())` answered `["size"]`, which is a property
/// no Map has. The count is reported by the accessor on `Map.prototype`, where the
/// specification puts it.
const COLLECTION_SIZE: &str = "@@size";

/// Adjust a collection's stored size.
///
/// Stored rather than derived so a read is a plain slot lookup; the two cannot drift because
/// only `add` and `delete` change either.
fn set_size(receiver: &Value, size: f64) {
    if let Value::Object(object) = receiver {
        object
            .borrow_mut()
            .set(COLLECTION_SIZE, Value::Number(size));
    }
}

fn bump_size(receiver: &Value, delta: f64) {
    if let Value::Object(object) = receiver {
        let current = object
            .borrow()
            .get_own(COLLECTION_SIZE)
            .map_or(0.0, Value::as_number);
        object
            .borrow_mut()
            .set(COLLECTION_SIZE, Value::Number(current + delta));
    }
}

/// The methods a string exposes.
///
/// Strings are primitives here rather than objects with a prototype, so their methods are looked
/// up directly. When `String.prototype` becomes a real object -- which subclassing and
/// monkey-patching both need -- this table is what moves onto it.
fn string_property(name: &str) -> Value {
    match name {
        // A string carries `@@iterator` and no `values` beside it, unlike an array: node answers
        // `undefined` for `"abc".values`, and `String.prototype` has no such own name. The
        // iterator itself is unchanged -- it is the arm below, reaching the same function.
        key if key == WellKnown::Iterator.property_key() => {
            Value::Native(Native::StringValues, RealmId::PRIMARY)
        }
        "toUpperCase" => Value::Native(Native::StringToUpperCase, RealmId::PRIMARY),
        "toLowerCase" => Value::Native(Native::StringToLowerCase, RealmId::PRIMARY),
        "includes" => Value::Native(Native::StringIncludes, RealmId::PRIMARY),
        "indexOf" => Value::Native(Native::StringIndexOf, RealmId::PRIMARY),
        "slice" => Value::Native(Native::StringSlice, RealmId::PRIMARY),
        "substring" => Value::Native(Native::StringSubstring, RealmId::PRIMARY),
        // Deprecated in the specification and still everywhere in the wild.
        "substr" => Value::Native(Native::StringSubstr, RealmId::PRIMARY),
        "split" => Value::Native(Native::StringSplit, RealmId::PRIMARY),
        "trim" => Value::Native(Native::StringTrim, RealmId::PRIMARY),
        // Annex B's aliases, and the *same* functions rather than copies:
        // `String.prototype.trimLeft === String.prototype.trimStart` is true.
        "trimLeft" => Value::Native(Native::StringTrimStart, RealmId::PRIMARY),
        "trimRight" => Value::Native(Native::StringTrimEnd, RealmId::PRIMARY),
        html if HtmlWrapper::named(html).is_some() => Value::Native(
            Native::StringHtml(
                HtmlWrapper::named(html).unwrap_or_else(|| unreachable!("the guard just found it")),
            ),
            RealmId::PRIMARY,
        ),
        "startsWith" => Value::Native(Native::StringStartsWith, RealmId::PRIMARY),
        "endsWith" => Value::Native(Native::StringEndsWith, RealmId::PRIMARY),
        "repeat" => Value::Native(Native::StringRepeat, RealmId::PRIMARY),
        "at" => Value::Native(Native::StringAt, RealmId::PRIMARY),
        "codePointAt" => Value::Native(Native::StringCodePointAt, RealmId::PRIMARY),
        // No locale data, so this is the ordinary code-unit order -- which is what a program
        // sorting ASCII gets from either.
        // ECMA-402 replaces this one outright: it is `Intl.Collator` built from the second and
        // third arguments, which is why a locale it rejects is rejected here too.
        "localeCompare" => Value::Native(
            Native::Intl(intl::Op::Adapter(intl::Adapter::StringLocaleCompare)),
            RealmId::PRIMARY,
        ),
        "toLocaleUpperCase" => Value::Native(
            Native::Intl(intl::Op::Adapter(intl::Adapter::StringToLocaleUpperCase)),
            RealmId::PRIMARY,
        ),
        // ECMA-402 gives these two their own definitions -- they validate the locale list and
        // may take a locale-specific mapping -- so they are separate functions rather than
        // aliases of `toLowerCase` and `toUpperCase`.
        "toLocaleLowerCase" => Value::Native(
            Native::Intl(intl::Op::Adapter(intl::Adapter::StringToLocaleLowerCase)),
            RealmId::PRIMARY,
        ),
        "normalize" => Value::Native(Native::StringNormalize, RealmId::PRIMARY),
        "charAt" => Value::Native(Native::StringCharAt, RealmId::PRIMARY),
        "charCodeAt" => Value::Native(Native::StringCharCodeAt, RealmId::PRIMARY),
        "padStart" => Value::Native(Native::StringPadStart, RealmId::PRIMARY),
        "padEnd" => Value::Native(Native::StringPadEnd, RealmId::PRIMARY),
        "replace" => Value::Native(Native::StringReplace, RealmId::PRIMARY),
        "replaceAll" => Value::Native(Native::StringReplaceAll, RealmId::PRIMARY),
        "lastIndexOf" => Value::Native(Native::StringLastIndexOf, RealmId::PRIMARY),
        "trimStart" => Value::Native(Native::StringTrimStart, RealmId::PRIMARY),
        "trimEnd" => Value::Native(Native::StringTrimEnd, RealmId::PRIMARY),
        "concat" => Value::Native(Native::StringConcat, RealmId::PRIMARY),
        // A string's `toString` and `valueOf` both hand back the string itself. They are rarely
        // written by hand and constantly reached by library code that calls `toString` on
        // something it has already coerced -- but they are still two functions with two names,
        // and `String.prototype.toLocaleString` is neither: it is inherited from
        // `Object.prototype`, so publishing one here made it an own property that is not one.
        "toString" => Value::Native(Native::StringToStringMethod, RealmId::PRIMARY),
        "valueOf" => Value::Native(Native::PrimitiveValueOf, RealmId::PRIMARY),
        "match" => Value::Native(Native::StringMatch, RealmId::PRIMARY),
        "matchAll" => Value::Native(Native::StringMatchAll, RealmId::PRIMARY),
        "search" => Value::Native(Native::StringSearch, RealmId::PRIMARY),
        _ => Value::Undefined,
    }
}

/// The methods a Set or Map instance exposes, shared by property reads and `in`.
/// The methods a Set or Map instance exposes, shared by property reads and `in`.
///
/// A weak collection exposes only the four that take a key: it has no size and cannot be walked,
/// because with no way to observe collection there would be nothing to stop a program depending
/// on entries a real engine would already have dropped.
fn collection_property(is_map: bool, weak: bool, name: &str) -> Value {
    // `clear` is in this list because a weak collection cannot have one: it would have to
    // enumerate the entries to drop them, which is the very thing a weak collection refuses to
    // let a program observe. It was answered anyway, so `WeakMap.prototype.clear` existed here
    // and nowhere else, and `hasOwnProperty` said so while `getOwnPropertyNames` did not.
    if weak && matches!(name, "values" | "keys" | "entries" | "forEach" | "clear") {
        return Value::Undefined;
    }
    if weak && name == WellKnown::Iterator.property_key() {
        return Value::Undefined;
    }
    match (is_map, name) {
        (false, "add") if weak => Value::Native(Native::WeakSetAdd, RealmId::PRIMARY),
        (false, "has") if weak => Value::Native(Native::WeakSetHas, RealmId::PRIMARY),
        (false, "delete") if weak => Value::Native(Native::WeakSetDelete, RealmId::PRIMARY),
        (true, "set") if weak => Value::Native(Native::WeakMapSet, RealmId::PRIMARY),
        (true, "get") if weak => Value::Native(Native::WeakMapGet, RealmId::PRIMARY),
        (true, "has") if weak => Value::Native(Native::WeakMapHas, RealmId::PRIMARY),
        (true, "delete") if weak => Value::Native(Native::WeakMapDelete, RealmId::PRIMARY),
        (false, "add") => Value::Native(Native::SetAdd, RealmId::PRIMARY),
        (false, "has") => Value::Native(Native::SetHas, RealmId::PRIMARY),
        (false, "delete") => Value::Native(Native::SetDelete, RealmId::PRIMARY),
        // The seven operations, on `Set` alone: a Map has keys and values and no answer to what
        // its union with something would contain.
        (false, name) if !weak && SetOperation::named(name).is_some() => Value::Native(
            Native::SetOperation(
                SetOperation::named(name)
                    .unwrap_or_else(|| unreachable!("the guard just found it")),
            ),
            RealmId::PRIMARY,
        ),
        (true, "getOrInsert") => Value::Native(
            Native::CollectionGetOrInsert {
                weak,
                computed: false,
            },
            RealmId::PRIMARY,
        ),
        (true, "getOrInsertComputed") => Value::Native(
            Native::CollectionGetOrInsert {
                weak,
                computed: true,
            },
            RealmId::PRIMARY,
        ),
        (true, "set") => Value::Native(Native::MapSet, RealmId::PRIMARY),
        (true, "get") => Value::Native(Native::MapGet, RealmId::PRIMARY),
        (true, "has") => Value::Native(Native::MapHas, RealmId::PRIMARY),
        (true, "delete") => Value::Native(Native::MapDelete, RealmId::PRIMARY),
        // A Map stores `[key, value]` pairs, so `keys` and `values` project out of them where
        // `entries` hands the pair over whole. A Set stores bare values, and its `entries` pairs
        // each one with itself -- which is the specification's way of giving the two collections
        // one iteration protocol.
        (_, "clear") => Value::Native(Native::CollectionClear(is_map), RealmId::PRIMARY),
        (_, "forEach") => Value::Native(Native::CollectionForEach(is_map), RealmId::PRIMARY),
        (_, "values") => Value::Native(Native::CollectionValues(is_map), RealmId::PRIMARY),
        // A Set's keys *are* its values, and the specification says so by giving the two names
        // one function: `Set.prototype.keys === Set.prototype.values` is true, and two markers
        // would make it false.
        (false, "keys") => Value::Native(Native::CollectionValues(false), RealmId::PRIMARY),
        (_, "keys") => Value::Native(Native::CollectionKeys(is_map), RealmId::PRIMARY),
        (_, "entries") => Value::Native(Native::CollectionEntries(is_map), RealmId::PRIMARY),
        // The default iteration of a Map is its entries and of a Set is its values.
        (is_map, key) if key == WellKnown::Iterator.property_key() => Value::Native(
            if is_map {
                Native::CollectionEntries(true)
            } else {
                Native::CollectionValues(false)
            },
            RealmId::PRIMARY,
        ),
        // The tag `Object.prototype.toString` reads: it is what makes a `Map` print as
        // `[object Map]` rather than the bare `[object Object]` every object would give.
        (_, key) if key == WellKnown::ToStringTag.property_key() => Value::String(
            match (is_map, weak) {
                (true, false) => "Map",
                (false, false) => "Set",
                (true, true) => "WeakMap",
                (false, true) => "WeakSet",
            }
            .to_owned()
            .into(),
        ),
        _ => Value::Undefined,
    }
}

/// `JSON.rawJSON(text)`: an object carrying JSON text the serialiser will emit unchanged.
///
/// Only a *primitive* text is accepted. An object or an array would have to be re-serialised
/// with the indentation and the replacer the enclosing `stringify` was given, and pasting it in
/// whole would ignore both -- so the specification refuses the case rather than producing a
/// document whose shape depends on where the raw value happened to sit.
fn build_raw_json(text: &StringUnits) -> Result<Value, ExecutionError> {
    // Not `trim`: surrounding whitespace is refused rather than removed, because the text is
    // going into a document verbatim and a leading newline would be there too.
    if text.is_empty()
        || text.unit_at(0).is_some_and(is_json_whitespace)
        || text
            .unit_at(text.unit_len().saturating_sub(1))
            .is_some_and(is_json_whitespace)
    {
        return Err(ExecutionError::InvalidJson);
    }
    let parsed = parse_json_text(text)?;
    if !matches!(
        parsed,
        Value::Null | Value::Boolean(_) | Value::Number(_) | Value::String(_)
    ) {
        return Err(ExecutionError::InvalidJson);
    }
    let mut object = ObjectData::default();
    object.set(RAW_JSON_TEXT, Value::String(text.clone()));
    object.set_non_enumerable(RAW_JSON_MARK, Value::Boolean(true));
    // A null prototype, so the object cannot answer to `toJSON`, `toString` or anything else a
    // program might have put on `Object.prototype` -- it is a carrier, not a participant.
    object.set_prototype(Value::Null);
    Ok(Value::Object(Rc::new(RefCell::new(object))))
}

/// What a `WeakRef` inherits from `WeakRef.prototype`.
/// What a `DisposableStack` inherits from `DisposableStack.prototype`.
///
/// `dispose` and `[Symbol.dispose]` answer with the *same* value, which is what the
/// specification says they are -- a program that stores one and compares it with the other has
/// to find them equal, and that is the whole of how `using` reaches a stack.
/// Where an error records the stack it was made on.
///
/// Reserved, so it never enumerates -- and it is also the only mark that separates a real error
/// from an object shaped like one, which is what `Error.isError` answers from.
const ERROR_TRACE: &str = "@@trace";
const CALL_SITE_NAME: &str = "@@call-site-name";

/// The reserved slots a `DisposableStack` carries.
const DISPOSE_ENTRIES: &str = "@@disposeEntries";
const DISPOSE_DONE: &str = "@@disposeDone";

/// The same pair for an `AsyncDisposableStack`, under names of its own.
///
/// Separate names rather than a shared pair with a flag, because the brand check *is* the
/// distinction: `DisposableStack.prototype.use.call(asyncStack)` is a `TypeError`, and looking
/// for a slot the other kind does not have is the whole of how that is decided.
const ASYNC_DISPOSE_ENTRIES: &str = "@@asyncDisposeEntries";
const ASYNC_DISPOSE_DONE: &str = "@@asyncDisposeDone";

/// Which of the two stacks an operation belongs to.
///
/// The pair is one object driven two ways. The slots, the brand check and the recorded
/// `[method, receiver, arguments]` triple are the same shape for both; what differs is the name
/// the disposer is looked up under, and whether what it returns is awaited before the next one
/// runs. Everything the two share is written once and told which it is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Disposal {
    Sync,
    Async,
}

impl Disposal {
    const fn entries_key(self) -> &'static str {
        match self {
            Self::Sync => DISPOSE_ENTRIES,
            Self::Async => ASYNC_DISPOSE_ENTRIES,
        }
    }

    const fn done_key(self) -> &'static str {
        match self {
            Self::Sync => DISPOSE_DONE,
            Self::Async => ASYNC_DISPOSE_DONE,
        }
    }

    const fn type_name(self) -> &'static str {
        match self {
            Self::Sync => "DisposableStack",
            Self::Async => "AsyncDisposableStack",
        }
    }

    /// The name a value has to carry a disposer under, as a diagnostic spells it.
    const fn hint_name(self) -> &'static str {
        match self {
            Self::Sync => "[Symbol.dispose]",
            Self::Async => "[Symbol.asyncDispose] or [Symbol.dispose]",
        }
    }
}

/// One recorded call: what to invoke, against what, with what.
fn disposal(method: Value, this_value: Value, arguments: Vec<Value>) -> Value {
    Value::Array(ArrayData::new(vec![
        method,
        this_value,
        Value::Array(ArrayData::new(arguments)),
    ]))
}

/// `new DisposableStack()` or `new AsyncDisposableStack()`: empty, and not yet disposed.
fn new_disposable_stack(flavour: Disposal) -> Value {
    let mut data = ObjectData::default();
    data.set_non_enumerable(
        flavour.entries_key(),
        Value::Array(ArrayData::new(Vec::new())),
    );
    data.set_non_enumerable(flavour.done_key(), Value::Boolean(false));
    data.set_prototype(Value::Native(
        Native::PrototypeOf(match flavour {
            Disposal::Sync => PrototypeTable::DisposableStack,
            Disposal::Async => PrototypeTable::AsyncDisposableStack,
        }),
        RealmId::PRIMARY,
    ));
    Value::Object(Rc::new(RefCell::new(data)))
}

fn disposable_stack_method(name: &str) -> Value {
    match name {
        "use" => Value::Native(Native::DisposableStackUse, RealmId::PRIMARY),
        "adopt" => Value::Native(Native::DisposableStackAdopt, RealmId::PRIMARY),
        "defer" => Value::Native(Native::DisposableStackDefer, RealmId::PRIMARY),
        "move" => Value::Native(Native::DisposableStackMove, RealmId::PRIMARY),
        "dispose" => Value::Native(Native::DisposableStackDispose, RealmId::PRIMARY),
        key if key == WellKnown::Dispose.property_key() => {
            Value::Native(Native::DisposableStackDispose, RealmId::PRIMARY)
        }
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("DisposableStack".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// What an `AsyncDisposableStack` inherits from `AsyncDisposableStack.prototype`.
///
/// `disposeAsync` and `[Symbol.asyncDispose]` answer with the same value, for the same reason
/// the synchronous pair do: the specification says the two properties hold one function, and
/// `await using` reaches a stack through the symbol.
fn async_disposable_stack_method(name: &str) -> Value {
    match name {
        "use" => Value::Native(Native::AsyncDisposableStackUse, RealmId::PRIMARY),
        "adopt" => Value::Native(Native::AsyncDisposableStackAdopt, RealmId::PRIMARY),
        "defer" => Value::Native(Native::AsyncDisposableStackDefer, RealmId::PRIMARY),
        "move" => Value::Native(Native::AsyncDisposableStackMove, RealmId::PRIMARY),
        "disposeAsync" => Value::Native(Native::AsyncDisposableStackDisposeAsync, RealmId::PRIMARY),
        key if key == WellKnown::AsyncDispose.property_key() => {
            Value::Native(Native::AsyncDisposableStackDisposeAsync, RealmId::PRIMARY)
        }
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("AsyncDisposableStack".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

fn weak_ref_method(name: &str) -> Value {
    match name {
        "deref" => Value::Native(Native::WeakRefDeref, RealmId::PRIMARY),
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("WeakRef".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// `ShadowRealm.prototype`'s two methods, which are the whole of what a shadow realm can do.
///
/// Deliberately two and no more: there is no way to reach the realm's global, no way to hand it
/// an object, and no way to get one back. Every addition here would be a new hole in the
/// membrane, so the shortness of this list is a property worth keeping.
fn shadow_realm_method(name: &str) -> Value {
    match name {
        "evaluate" => Value::Native(Native::ShadowRealmEvaluate, RealmId::PRIMARY),
        "importValue" => Value::Native(Native::ShadowRealmImportValue, RealmId::PRIMARY),
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("ShadowRealm".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// What a `FinalizationRegistry` inherits from `FinalizationRegistry.prototype`.
///
/// `cleanupSome` is absent rather than a no-op: it is a separate proposal, and a method that
/// answered "the cleanup has run" without ever being able to run one would be a claim a program
/// could build on and be wrong about.
fn finalization_registry_method(name: &str) -> Value {
    match name {
        "register" => Value::Native(Native::FinalizationRegistryRegister, RealmId::PRIMARY),
        "unregister" => Value::Native(Native::FinalizationRegistryUnregister, RealmId::PRIMARY),
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("FinalizationRegistry".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// The slot that marks a raw JSON object, and the property that carries its text.
///
/// Two, because the text is a property a program reads -- `JSON.rawJSON(1).rawJSON` is `"1"` --
/// while the mark is not: the object is required to have exactly one own property, so the thing
/// that says "this is raw JSON" has to be invisible to `Object.getOwnPropertyNames`. The
/// reserved prefix is what makes it so.
const RAW_JSON_MARK: &str = "@@raw-json";
const RAW_JSON_TEXT: &str = "rawJSON";

/// The slot a `WeakRef` keeps its target in, and the two a registry keeps its state in.
const WEAK_REF_TARGET: &str = "@@weakref-target";
const REGISTRY_CELLS: &str = "@@finreg-cells";
const REGISTRY_CALLBACK: &str = "@@finreg-callback";

/// One of the five symbol-keyed methods on `RegExp.prototype`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RegExpSymbol {
    Match,
    MatchAll,
    Replace,
    Search,
    Split,
}

impl RegExpSymbol {
    const ALL: [Self; 5] = [
        Self::Match,
        Self::MatchAll,
        Self::Replace,
        Self::Search,
        Self::Split,
    ];

    const fn symbol(self) -> WellKnown {
        match self {
            Self::Match => WellKnown::Match,
            Self::MatchAll => WellKnown::MatchAll,
            Self::Replace => WellKnown::Replace,
            Self::Search => WellKnown::Search,
            Self::Split => WellKnown::Split,
        }
    }

    /// The name a stack trace prints, which for a symbol-keyed method is the key in brackets.
    fn js_name(self) -> String {
        format!("[Symbol.{}]", self.symbol().js_name())
    }

    fn named(key: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|found| found.symbol().property_key() == key)
    }
}

/// One of Annex B's HTML wrappers on `String.prototype`.
///
/// Deprecated in the specification and still normative: they are what `"x".link(url)` produces,
/// and the escaping rule is the only interesting part -- a quote inside an attribute becomes
/// `&quot;`, or the tag it builds would not be one.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HtmlWrapper {
    Anchor,
    Big,
    Blink,
    Bold,
    Fixed,
    FontColor,
    FontSize,
    Italics,
    Link,
    Small,
    Strike,
    Sub,
    Sup,
}

impl HtmlWrapper {
    const ALL: [Self; 13] = [
        Self::Anchor,
        Self::Big,
        Self::Blink,
        Self::Bold,
        Self::Fixed,
        Self::FontColor,
        Self::FontSize,
        Self::Italics,
        Self::Link,
        Self::Small,
        Self::Strike,
        Self::Sub,
        Self::Sup,
    ];

    /// The method's name, which is not the tag it produces: `bold` makes a `<b>`.
    const fn property_key(self) -> &'static str {
        match self {
            Self::Anchor => "anchor",
            Self::Big => "big",
            Self::Blink => "blink",
            Self::Bold => "bold",
            Self::Fixed => "fixed",
            Self::FontColor => "fontcolor",
            Self::FontSize => "fontsize",
            Self::Italics => "italics",
            Self::Link => "link",
            Self::Small => "small",
            Self::Strike => "strike",
            Self::Sub => "sub",
            Self::Sup => "sup",
        }
    }

    /// The element name, and the attribute it takes -- or none, for the nine that take nothing.
    const fn tag(self) -> (&'static str, Option<&'static str>) {
        match self {
            Self::Anchor => ("a", Some("name")),
            Self::Big => ("big", None),
            Self::Blink => ("blink", None),
            Self::Bold => ("b", None),
            Self::Fixed => ("tt", None),
            Self::FontColor => ("font", Some("color")),
            Self::FontSize => ("font", Some("size")),
            Self::Italics => ("i", None),
            Self::Link => ("a", Some("href")),
            Self::Small => ("small", None),
            Self::Strike => ("strike", None),
            Self::Sub => ("sub", None),
            Self::Sup => ("sup", None),
        }
    }

    fn named(key: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|found| found.property_key() == key)
    }
}

/// `CreateHTML`: the receiver wrapped in a tag, with the attribute value quoted.
fn html_wrapper(wrapper: HtmlWrapper, text: &str, attribute: &str) -> String {
    let (tag, name) = wrapper.tag();
    match name {
        // A quote inside the value is doubled into an entity, which is the whole of the
        // specification's escaping here -- `<` and `&` are deliberately left alone.
        Some(name) => format!(
            "<{tag} {name}=\"{}\">{text}</{tag}>",
            attribute.replace('"', "&quot;")
        ),
        None => format!("<{tag}>{text}</{tag}>"),
    }
}

/// One of the four copying array methods.
///
/// Each is the counterpart of a method that mutates: `with` to an index assignment, `toReversed`
/// to `reverse`, `toSorted` to `sort`, `toSpliced` to `splice`. What they share is the shape --
/// read the receiver, build a new array, leave the receiver untouched -- which is why one marker
/// carries all four.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArrayCopy {
    With,
    ToReversed,
    ToSorted,
    ToSpliced,
}

impl ArrayCopy {
    const fn property_key(self) -> &'static str {
        match self {
            Self::With => "with",
            Self::ToReversed => "toReversed",
            Self::ToSorted => "toSorted",
            Self::ToSpliced => "toSpliced",
        }
    }
}

/// One of the seven operations `Set.prototype` gained in ES2025.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SetOperation {
    Union,
    Intersection,
    Difference,
    SymmetricDifference,
    IsSubsetOf,
    IsSupersetOf,
    IsDisjointFrom,
}

impl SetOperation {
    const ALL: [Self; 7] = [
        Self::Union,
        Self::Intersection,
        Self::Difference,
        Self::SymmetricDifference,
        Self::IsSubsetOf,
        Self::IsSupersetOf,
        Self::IsDisjointFrom,
    ];

    const fn property_key(self) -> &'static str {
        match self {
            Self::Union => "union",
            Self::Intersection => "intersection",
            Self::Difference => "difference",
            Self::SymmetricDifference => "symmetricDifference",
            Self::IsSubsetOf => "isSubsetOf",
            Self::IsSupersetOf => "isSupersetOf",
            Self::IsDisjointFrom => "isDisjointFrom",
        }
    }

    fn named(key: &str) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|found| found.property_key() == key)
    }
}

/// What one of the seven operations needs from its argument.
///
/// A *set-like*, not a Set: the specification asks only for a `size`, a `has` and a `keys`, and
/// reads all three before it does anything with them. That order is observable -- a program can
/// watch which getter runs first -- and it is what makes `new Set([1]).union(m)` work for any `m`
/// that answers those three.
struct SetLike {
    object: Value,
    size: f64,
    has: Value,
    keys: Value,
}

/// The entries of a Set receiver, or the `TypeError` a method on the wrong receiver raises.
///
/// A Map is refused as firmly as a number is: it has entries, but no answer to what its union
/// with something else would contain.
fn require_set(receiver: &Value) -> Result<Rc<ArrayData>, ExecutionError> {
    collection_state(receiver)
        .filter(|(_, is_map)| !is_map && !is_weak_collection(receiver))
        .map(|(entries, _)| entries)
        .ok_or_else(|| ExecutionError::TypeErrorMessage {
            message: "Method called on an incompatible receiver".to_owned(),
        })
}

/// `CanonicalizeKeyedCollectionKey`: `-0` is stored and reported as `+0`.
///
/// The one place a keyed collection departs from `SameValue`. Without it `new Set([-0]).has(0)`
/// and the value a program gets back out of the set disagree.
fn canonical_key(value: Value) -> Value {
    match value {
        Value::Number(number) => {
            if number == 0.0 {
                Value::Number(0.0)
            } else {
                Value::Number(number)
            }
        }
        other => other,
    }
}

/// Whether a set's backing entries already hold this value, skipping the tombstones a delete
/// leaves behind.
fn set_data_has(entries: &Rc<ArrayData>, value: &Value) -> bool {
    set_data_index(entries, value).is_some()
}

/// Where a set's backing entries hold this value, or `None`.
fn set_data_index(entries: &Rc<ArrayData>, value: &Value) -> Option<usize> {
    find_collection_entry(entries, value, false)
}

/// The live values of a set's backing entries, in insertion order.
fn set_data_values(entries: &Rc<ArrayData>) -> Vec<Value> {
    entries
        .borrow()
        .iter()
        .filter(|entry| !matches!(entry, Value::Native(Native::Tombstone, _)))
        .cloned()
        .collect()
}

/// A fresh `Set` holding exactly these values.
///
/// Built directly rather than through `add`, because the values are already deduplicated and
/// canonical by the time an operation has them -- and because `add` is a property a program can
/// replace, which must not change what `union` answers.
fn new_set(values: Vec<Value>) -> Value {
    let size = values.len() as f64;
    let mut data = ObjectData::default();
    data.set("@@entries", Value::Array(ArrayData::new(values)));
    data.set_prototype(Value::Native(
        Native::PrototypeOf(PrototypeTable::Set),
        RealmId::PRIMARY,
    ));
    data.set(COLLECTION_SIZE, Value::Number(size));
    Value::Object(Rc::new(RefCell::new(data)))
}

/// Whether this value is one of the two weak collections.
fn is_weak_collection(receiver: &Value) -> bool {
    matches!(receiver, Value::Object(object)
        if matches!(object.borrow().get_own("@@weak"), Some(&Value::Boolean(true))))
}

/// The backing entries of the collection `native` is a method of, or the `TypeError` the
/// specification raises when the receiver does not have that collection's internal slot.
///
/// Which brand a method demands is decided by the method, not by the receiver: `add`, `has` and
/// `delete` are one name apiece across four collections, and the one the property lookup handed
/// back is the one whose slot the receiver must have. Answering a benign default instead made
/// `Set.prototype.add.call(new Map(), 1)` -- and every other mistake of the same shape -- look
/// like it had worked.
fn require_collection(
    receiver: &Value,
    native: Native,
) -> Result<(Rc<ArrayData>, bool), ExecutionError> {
    let wanted = match native {
        Native::SetAdd | Native::SetHas | Native::SetDelete => Some((false, false)),
        Native::MapSet | Native::MapGet | Native::MapHas | Native::MapDelete => Some((true, false)),
        Native::WeakSetAdd | Native::WeakSetHas | Native::WeakSetDelete => Some((false, true)),
        Native::WeakMapSet | Native::WeakMapGet | Native::WeakMapHas | Native::WeakMapDelete => {
            Some((true, true))
        }
        Native::CollectionGetOrInsert { weak, .. } => Some((true, weak)),
        // `clear`, `forEach` and the three iteration methods share an implementation between
        // Map and Set, and the payload is which of the two this one is: a weak collection
        // carries none of them, and a Set is not a Map.
        Native::CollectionClear(is_map)
        | Native::CollectionForEach(is_map)
        | Native::CollectionKeys(is_map)
        | Native::CollectionValues(is_map)
        | Native::CollectionEntries(is_map) => Some((is_map, false)),
        _ => None,
    };
    let weak = is_weak_collection(receiver);
    collection_state(receiver)
        .filter(|(_, is_map)| match wanted {
            Some(brand) => brand == (*is_map, weak),
            None => !weak,
        })
        .ok_or_else(|| ExecutionError::TypeErrorMessage {
            message: "Method called on an incompatible receiver".to_owned(),
        })
}

/// The `@@iterated` field of an iterator this realm made, or the `TypeError` the specification
/// raises for a receiver that is not one.
///
/// The marker is the brand: a plain object that merely carries a `next` is not an array
/// iterator, and reporting a walk that finished before it started hid the mistake.
/// The iterator `entries()`, `keys()` and `values()` answer with.
///
/// It keeps the receiver rather than a copy of it, which is the whole point: a write between the
/// call that made the iterator and the `next()` that reaches that position has to be visible, and
/// a snapshot is a promise that it will not be. The state lives in reserved properties on the
/// iterator itself, so `next` reads the receiver as it is each step.
fn array_iterator_over(native: Native, iterated: &Value) -> Value {
    let mut iterator = ObjectData::default();
    // On `%ArrayIteratorPrototype%`, which owns `next` and the tag and itself sits on
    // `%IteratorPrototype%` -- so `map` and `take` are one link further up and
    // `[...].values().map(f)` still finds them. The iterator object now owns nothing, which is
    // what `Object.getOwnPropertyNames` on one reports.
    iterator.set_prototype(Value::Native(
        Native::PrototypeOf(PrototypeTable::IteratorFor(IteratorKind::Array)),
        RealmId::PRIMARY,
    ));
    iterator.set("@@iterated", iterated.clone());
    iterator.set("@@index", Value::Number(0.0));
    iterator.set(
        "@@part",
        Value::String(
            match native {
                Native::ArrayEntries => "entry",
                Native::ArrayKeys => "key",
                _ => "value",
            }
            .to_owned()
            .into(),
        ),
    );

    // An iterator is itself iterable, which is what lets one be passed straight to another
    // `for-of` or to `Array.from`.
    iterator.set(
        WellKnown::Iterator.property_key(),
        Value::Native(Native::IteratorSelf, RealmId::PRIMARY),
    );
    Value::Object(Rc::new(RefCell::new(iterator)))
}

fn iterator_state(receiver: &Value) -> Result<Value, ExecutionError> {
    match receiver {
        Value::Object(object) => object
            .borrow()
            .get_own("@@iterated")
            .cloned()
            .ok_or(ExecutionError::NotAnIterator),
        _ => Err(ExecutionError::NotAnIterator),
    }
}

/// The backing entries of a Set or Map, and whether it is a Map.
fn collection_state(receiver: &Value) -> Option<(Rc<ArrayData>, bool)> {
    let Value::Object(object) = receiver else {
        return None;
    };
    let object = object.borrow();
    let Some(Value::Array(entries)) = object.get_own("@@entries").cloned() else {
        return None;
    };
    let is_map = matches!(object.get_own("@@map"), Some(&Value::Boolean(true)));
    Some((entries, is_map))
}

/// SameValue, which is what `Object.is` reports and what a property definition compares a new
/// value against before deciding whether a non-configurable property is really changing.
///
/// It differs from `===` in two places: NaN equals itself, and `0` and `-0` are distinct.
/// The well-known symbol a `String.prototype` method hands its call to, if it is one of the
/// five that do.
///
/// `replace` and `replaceAll` share `@@replace`: the pair differ in how many matches they cover,
/// and that difference is settled by the regexp's own `g` flag rather than by two symbols.
const fn string_delegating_symbol(native: Native) -> Option<WellKnown> {
    match native {
        Native::StringMatch => Some(WellKnown::Match),
        Native::StringMatchAll => Some(WellKnown::MatchAll),
        Native::StringReplace | Native::StringReplaceAll => Some(WellKnown::Replace),
        Native::StringSearch => Some(WellKnown::Search),
        Native::StringSplit => Some(WellKnown::Split),
        _ => None,
    }
}

/// `ToIntegerOrInfinity`, for the built-ins reached through `call_native`.
///
/// The same rule [`Vm::to_integer_or_infinity`] applies, spelled where a free function can use
/// it: NaN -- which is what `undefined` coerces to -- is zero, and everything else truncates
/// towards zero while an infinity stays one.
fn to_integer_or_infinity(number: f64) -> f64 {
    if number.is_nan() { 0.0 } else { number.trunc() }
}

/// `ToLength`: a count, clamped into the range an index may occupy.
fn to_length(number: f64) -> usize {
    if number.is_nan() || number <= 0.0 {
        return 0;
    }
    number.trunc().min(9_007_199_254_740_991.0) as usize
}

/// `AdvanceStringIndex`: the next position a match may start at.
///
/// A whole code point at a time when the pattern is Unicode-aware, and a single code unit
/// otherwise. The difference matters exactly once -- an empty match beside a surrogate pair --
/// and getting it wrong there splits an astral character down the middle.
fn advance_string_index(units: &[u16], index: usize, unicode: bool) -> usize {
    if !unicode || index + 1 >= units.len() {
        return index + 1;
    }
    let lead = units[index];
    let trail = units[index + 1];
    if (0xD800..=0xDBFF).contains(&lead) && (0xDC00..=0xDFFF).contains(&trail) {
        index + 2
    } else {
        index + 1
    }
}

fn same_value(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(a), Value::Number(b)) => {
            if a.is_nan() && b.is_nan() {
                true
            } else {
                a == b && a.is_sign_negative() == b.is_sign_negative()
            }
        }
        _ => strict_equal(left, right),
    }
}

/// SameValueZero, which is what Set and Map use for key identity.
///
/// It differs from `===` in exactly one place: NaN is its own key, so a Set can contain one and
/// find it again. `-0` and `0` remain the same key under both.
fn same_value_zero(left: &Value, right: &Value) -> bool {
    match (left, right) {
        (Value::Number(a), Value::Number(b)) if a.is_nan() && b.is_nan() => true,
        _ => strict_equal(left, right),
    }
}

fn array_method_value(method: kiln_builtin_surface::ArrayMethod, realm: RealmId) -> Value {
    use kiln_builtin_surface::ArrayMethod;
    match method {
        ArrayMethod::At => Value::Native(Native::ArrayAt, realm),
        ArrayMethod::Concat => Value::Native(Native::ArrayConcat, realm),
        ArrayMethod::CopyWithin => Value::Native(Native::ArrayCopyWithin, realm),
        ArrayMethod::Entries => Value::Native(Native::ArrayEntries, realm),
        ArrayMethod::Every => Value::Callback(CallbackMethod::Every, realm),
        ArrayMethod::Fill => Value::Native(Native::ArrayFill, realm),
        ArrayMethod::Filter => Value::Callback(CallbackMethod::Filter, realm),
        ArrayMethod::Find => Value::Callback(CallbackMethod::Find, realm),
        ArrayMethod::FindIndex => Value::Callback(CallbackMethod::FindIndex, realm),
        ArrayMethod::FindLast => Value::Callback(CallbackMethod::FindLast, realm),
        ArrayMethod::FindLastIndex => Value::Callback(CallbackMethod::FindLastIndex, realm),
        ArrayMethod::Flat => Value::Native(Native::ArrayFlat, realm),
        ArrayMethod::FlatMap => Value::Callback(CallbackMethod::FlatMap, realm),
        ArrayMethod::ForEach => Value::Callback(CallbackMethod::ForEach, realm),
        ArrayMethod::Includes => Value::Native(Native::ArrayIncludes, realm),
        ArrayMethod::IndexOf => Value::Native(Native::ArrayIndexOf, realm),
        ArrayMethod::Join => Value::Native(Native::ArrayJoin, realm),
        ArrayMethod::Keys => Value::Native(Native::ArrayKeys, realm),
        ArrayMethod::LastIndexOf => Value::Native(Native::ArrayLastIndexOf, realm),
        ArrayMethod::Map => Value::Callback(CallbackMethod::Map, realm),
        ArrayMethod::ParallelMap => Value::Callback(CallbackMethod::ParallelMap, realm),
        ArrayMethod::Pop => Value::Native(Native::ArrayPop, realm),
        ArrayMethod::Push => Value::Native(Native::ArrayPush, realm),
        ArrayMethod::Reduce => Value::Callback(CallbackMethod::Reduce, realm),
        ArrayMethod::ReduceRight => Value::Callback(CallbackMethod::ReduceRight, realm),
        ArrayMethod::Reverse => Value::Native(Native::ArrayReverse, realm),
        ArrayMethod::Shift => Value::Native(Native::ArrayShift, realm),
        ArrayMethod::Slice => Value::Native(Native::ArraySlice, realm),
        ArrayMethod::Some => Value::Callback(CallbackMethod::Some, realm),
        ArrayMethod::Sort => Value::Callback(CallbackMethod::Sort, realm),
        ArrayMethod::Splice => Value::Native(Native::ArraySplice, realm),
        ArrayMethod::ToLocaleString => Value::Native(Native::ArrayToLocaleString, realm),
        ArrayMethod::ToReversed => Value::Native(Native::ArrayCopy(ArrayCopy::ToReversed), realm),
        ArrayMethod::ToSorted => Value::Native(Native::ArrayCopy(ArrayCopy::ToSorted), realm),
        ArrayMethod::ToSpliced => Value::Native(Native::ArrayCopy(ArrayCopy::ToSpliced), realm),
        ArrayMethod::ToString => Value::Native(Native::ArrayJoinDefault, realm),
        ArrayMethod::Unshift => Value::Native(Native::ArrayUnshift, realm),
        ArrayMethod::Values => Value::Native(Native::ArrayValues, realm),
        ArrayMethod::With => Value::Native(Native::ArrayCopy(ArrayCopy::With), realm),
    }
}

/// A built-in that takes a function argument.
///
/// Separate from `Native` because these cannot be evaluated by `call_native`: they need to
/// re-enter the interpreter, which only the VM can do.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CallbackMethod {
    /// `next` on a generator: resumes the body, which the VM must drive.
    GeneratorNext,
    /// `return` on a generator: finishes it without resuming.
    GeneratorReturn,
    /// `throw` on a generator: raises at the suspension point rather than resuming it.
    GeneratorThrow,
    /// `next` on an async generator: hands back a promise of the step.
    AsyncGeneratorNext,
    /// `return` on an async generator: unwinds it, and hands back a promise of the final step.
    AsyncGeneratorReturn,
    /// `throw` on an async generator: raises at the suspension point, promising the next step.
    AsyncGeneratorThrow,
    Map,
    /// `parallelMap`: `map` by another name on this engine. The compiled backend may run the
    /// walk on a pool (ADR 0058, application 2); the answer is the same array either way, and
    /// a name that reads `undefined` here while the other engine has a value is the failure
    /// CLAUDE.md calls the expensive one.
    ParallelMap,
    ForEach,
    Filter,
    /// `reduce`: the only one whose callback takes the accumulator, so it does not fit the
    /// `(item, index, array)` walk the rest share.
    Reduce,
    /// `sort`: its callback compares two elements rather than visiting one, so it does not fit
    /// the walk either.
    Sort,
    FindIndex,
    Find,
    Some,
    Every,
    /// `flatMap`: the forward walk, and then one level of flattening -- which is the whole of what
    /// it adds over `map`.
    FlatMap,
    /// The two that walk from the end. They visit a hole as undefined where `find` skips it: the
    /// language added them after it stopped skipping.
    FindLast,
    FindLastIndex,
    /// `reduceRight`: `reduce` from the other end, seeded with the last element that is there.
    ReduceRight,
}

fn number_method_value(method: kiln_builtin_surface::NumberMethod, realm: RealmId) -> Value {
    match method {
        kiln_builtin_surface::NumberMethod::ToString => {
            Value::Native(Native::NumberToString, realm)
        }
        kiln_builtin_surface::NumberMethod::ToFixed => Value::Native(Native::NumberToFixed, realm),
        kiln_builtin_surface::NumberMethod::ToExponential => {
            Value::Native(Native::NumberToExponential, realm)
        }
        kiln_builtin_surface::NumberMethod::ToPrecision => {
            Value::Native(Native::NumberToPrecision, realm)
        }
        kiln_builtin_surface::NumberMethod::ValueOf => Value::Native(Native::NumberValueOf, realm),
        kiln_builtin_surface::NumberMethod::ToLocaleString => Value::Native(
            Native::Intl(intl::Op::Adapter(intl::Adapter::NumberToLocaleString)),
            realm,
        ),
    }
}

/// The methods a number primitive exposes.
fn number_property(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::Number,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::NumberConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::NumberMethod(method) => {
            number_method_value(method, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

fn array_property(name: &str) -> Value {
    let Some(member) =
        kiln_builtin_surface::find_prototype_member(kiln_builtin_surface::PrototypeId::Array, name)
    else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::ArrayLength => Value::Number(0.0),
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::ArrayConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::ArrayUnscopables => Value::Null,
        kiln_builtin_surface::SemanticBinding::ArrayMethod(method) => {
            array_method_value(method, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

/// A key usable as a dense array index: a non-negative integer that fits in `usize`.
///
/// `a["0"]` and `a[0]` name the same element, so a string that round-trips through a number is
/// an index too. `a[-1]` and `a[1.5]` are ordinary string properties in JavaScript, and treating
/// them as indices would silently move data.
#[cfg(test)]
fn array_index(key: &Value) -> Option<usize> {
    let number = match key {
        Value::Number(value) => *value,
        // A string reaches an element only in the one spelling that names it. `"01"`, `"1.0"`,
        // `" 1"`, `"1e2"` and `"-0"` are ordinary named properties in JavaScript, and parsing
        // them as numbers handed back an element the program never asked for.
        Value::String(text) => return index_key_units(text),
        _ => return None,
    };
    if number < 0.0 || number.fract() != 0.0 || !number.is_finite() {
        return None;
    }
    Some(number as usize)
}

/// `array_index`, with a property key already converted exactly once.
fn array_index_key(key: PropertyKeyRef<'_>) -> Option<usize> {
    match key {
        PropertyKeyRef::Utf8(name) => canonical_index(name),
        PropertyKeyRef::Units(name) => index_key_units(name),
    }
}

/// The element a property name reaches, if it is the canonical spelling of an index.
///
/// Canonical means the name is exactly what the index stringifies back to, which is the test the
/// language uses to separate an element from a property that merely looks like one.
fn canonical_index(name: &str) -> Option<usize> {
    let index: usize = name.parse().ok()?;
    (index.to_string() == name).then_some(index)
}

/// The same array-index test over the language's UTF-16 key units. This avoids constructing a
/// lossy scalar spelling merely to order a property during insertion.
fn index_key_units(name: &StringUnits) -> Option<usize> {
    let mut value = 0usize;
    let mut digits = 0usize;
    for unit in name.units() {
        if !(b'0' as u16..=b'9' as u16).contains(&unit) {
            return None;
        }
        if digits == 0 && unit == b'0' as u16 && name.unit_len() != 1 {
            return None;
        }

        value = value
            .checked_mul(10)?
            .checked_add(usize::from(unit - b'0' as u16))?;

        digits += 1;
    }
    (digits > 0 && value <= u32::MAX as usize - 1).then_some(value)
}

/// How long a wait with no limit is allowed to last before it reports a timeout.
///
/// See [`Vm::atomics_sleep`]: with one agent there is nothing that could ever end such a wait,
/// so the choice is between a bound and hanging the process.
const ATOMICS_UNBOUNDED_WAIT_MS: f64 = 100.0;

/// `value` as the view's element type would hold it, wrapping the way a write does.
///
/// Atomic arithmetic is defined on the *stored* representation, so both operands are brought
/// into it before they meet: without this, `Atomics.and(u8, 0, 257)` would and against 257
/// rather than against the 1 the buffer would have held.
fn narrow_element(kind: TypedKind, value: &Value) -> Value {
    let mut slot = vec![0_u8; kind.width()];
    kind.encode(value, &mut slot);
    kind.decode(&slot)
}

/// What a read-modify-write leaves in the element it touched.
///
/// Both operands are narrowed first, so the bitwise operations see the two's-complement pattern
/// the buffer holds rather than the number a program wrote; the result is narrowed again by the
/// write itself, which is where an addition wraps.
fn atomics_combine(kind: TypedKind, op: AtomicsOp, old: &Value, operand: &Value) -> Value {
    let operand = narrow_element(kind, operand);
    if let (Value::BigInt(old), Value::BigInt(operand)) = (old, &operand) {
        let old = old.as_ref().clone();
        let operand = operand.as_ref().clone();
        return Value::BigInt(Rc::new(match op {
            AtomicsOp::Add => old + operand,
            AtomicsOp::Sub => old - operand,
            AtomicsOp::And => old & operand,
            AtomicsOp::Or => old | operand,
            AtomicsOp::Xor => old ^ operand,
            _ => operand,
        }));
    }
    #[expect(clippy::cast_possible_truncation)]
    let left = old.as_number() as i64;
    #[expect(clippy::cast_possible_truncation)]
    let right = operand.as_number() as i64;
    #[expect(clippy::cast_precision_loss)]
    let combined = match op {
        AtomicsOp::Add => left.wrapping_add(right),
        AtomicsOp::Sub => left.wrapping_sub(right),
        AtomicsOp::And => left & right,
        AtomicsOp::Or => left | right,
        AtomicsOp::Xor => left ^ right,
        _ => right,
    } as f64;
    Value::Number(combined)
}

/// `RegExp.escape`: a string as a pattern that matches exactly it.
///
/// More is escaped than the grammar strictly needs, and deliberately: the result has to be safe
/// to *paste*, so punctuation that a regexp gives no meaning to is escaped anyway, and every
/// whitespace character becomes a numeric escape rather than staying a space that a later reader
/// might trim. A leading letter or digit is escaped too, so that concatenating the result after
/// something else can never continue an identifier or a back-reference.
fn escape_regexp_source(text: &str) -> String {
    /// The characters the grammar itself gives meaning to, plus `/`, which ends a literal.
    const SYNTAX: &str = "^$\\.*+?()[]{}|/";
    /// Punctuation the grammar gives no meaning to, escaped so the result is safe to paste.
    const PUNCTUATORS: &str = ",-=<>#&!%:;@~\'`\"";
    let mut escaped = String::new();
    for character in text.chars() {
        // Only the *first* code point: the rule exists so the result cannot be read as the tail
        // of a name, and only the first position can be.
        if escaped.is_empty() && character.is_ascii_alphanumeric() {
            escaped.push_str(&format!("\\x{:02x}", character as u32));
            continue;
        }
        if SYNTAX.contains(character) {
            escaped.push('\\');
            escaped.push(character);
            continue;
        }
        if let Some(control) = match character {
            '\t' => Some("\\t"),
            '\n' => Some("\\n"),
            '\u{b}' => Some("\\v"),
            '\u{c}' => Some("\\f"),
            '\r' => Some("\\r"),
            _ => None,
        } {
            escaped.push_str(control);
            continue;
        }
        if !PUNCTUATORS.contains(character) && !is_pattern_whitespace(character) {
            escaped.push(character);
            continue;
        }
        let point = character as u32;
        if point <= 0xff {
            escaped.push_str(&format!("\\x{point:02x}"));
        } else {
            for unit in character.encode_utf16(&mut [0; 2]) {
                escaped.push_str(&format!("\\u{unit:04x}"));
            }
        }
    }
    escaped
}

/// Whitespace and the line terminators, which `RegExp.escape` turns into numeric escapes so that
/// a pattern carrying one cannot be silently reformatted.
fn is_pattern_whitespace(character: char) -> bool {
    matches!(
        character,
        '\t' | '\u{b}'
            | '\u{c}'
            | ' '
            | '\u{a0}'
            | '\u{feff}'
            | '\n'
            | '\r'
            | '\u{2028}'
            | '\u{2029}'
    ) || matches!(
        character,
        '\u{1680}' | '\u{2000}'..='\u{200a}' | '\u{202f}' | '\u{205f}' | '\u{3000}'
    )
}

/// `CanonicalNumericIndexString(P)`: the number a property name spells, when the name is exactly
/// what that number stringifies back to.
///
/// This is the line an integer-indexed exotic object draws between an *element* key and an
/// ordinary named one, and it is wider than "an index": `"1.5"`, `"-1"`, `"NaN"` and `"Infinity"`
/// are all element keys that reach no slot, so a typed array refuses them rather than storing
/// them, while `"01"` and `"1e2"` are ordinary names and are stored. `"-0"` is the one name the
/// specification admits by hand, because its round trip through `String` comes back as `"0"`.
fn canonical_numeric_index(name: &str) -> Option<f64> {
    if name == "-0" {
        return Some(-0.0);
    }
    let number = parse_number(name);
    (number_string(number) == name).then_some(number)
}

/// `CanonicalNumericIndexString` over exact UTF-16 units.  Numeric spellings are ASCII by
/// definition, so matching the units directly is sufficient and keeps lone-surrogate keys out of
/// the scalar conversion path.
fn canonical_numeric_index_key(key: PropertyKeyRef<'_>) -> Option<f64> {
    match key {
        PropertyKeyRef::Utf8(name) => canonical_numeric_index(name),
        PropertyKeyRef::Units(name) => {
            let name = name;
            if name.is_empty() {
                return None;
            }
            if name == "-0" {
                return Some(-0.0);
            }
            let number = parse_number_units(name);
            let printed = number_string(number);
            units_match_str(name, &printed).then_some(number)
        }
    }
}

fn units_match_str(units: &StringUnits, text: &str) -> bool {
    units.unit_len() == text.encode_utf16().count()
        && units
            .units()
            .zip(text.encode_utf16())
            .all(|(left, right)| left == right)
}

/// `IsValidIntegerIndex(O, index)`: the element this number reaches in a live view, if any.
///
/// Negative zero is refused along with the negatives it sorts with, and a view whose buffer was
/// detached or shrunk out from under it has no valid index at all.
fn valid_integer_index(view: &TypedArrayData, index: f64) -> Option<usize> {
    if view.out_of_bounds() || index.is_sign_negative() || index.fract() != 0.0 {
        return None;
    }
    #[expect(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    let at = index as usize;
    (at < view.len()).then_some(at)
}

/// `Array.prototype.join` semantics: null and undefined become empty, everything else stringifies.
/// A hole and `undefined` both render as nothing here, which is what `join` and `String()` do.
///
/// Bounded, and accumulated rather than collected, so a long array of long strings refuses at
/// the bound instead of materialising every piece and then the concatenation of all of them.
fn join(items: &[Value], separator: &str) -> Result<String, ExecutionError> {
    let mut out = String::new();
    for (index, item) in items.iter().enumerate() {
        if index > 0 {
            push_bounded(&mut out, separator)?;
        }
        match item {
            Value::Undefined | Value::Null | Value::Native(Native::Hole, _) => {}
            other => push_bounded(&mut out, &other.to_display_string())?,
        }
    }
    Ok(out)
}

fn join_units(items: &[Value], separator: &StringUnits) -> Result<StringUnits, ExecutionError> {
    let mut out = StringUnitsBuilder::new();
    for (index, item) in items.iter().enumerate() {
        if index > 0 {
            out.push_units(separator)?;
        }
        match item {
            Value::Undefined | Value::Null | Value::Native(Native::Hole, _) => {}
            other => out.push_units(&other.to_string_units_checked()?)?,
        }
    }
    Ok(out.finish())
}

/// Remove an own property, reporting whether it is gone afterwards.
///
/// Which is why deleting something that was never there is still true, and why deleting a
/// string's `length` is false: the property is real and cannot be configured away. Every store
/// answers from the property's own `configurable` flag, so `delete` and the descriptor that
/// reports the flag cannot disagree.
/// `JSON.parse`'s grammar, on text that has already been converted to a string.
///
/// Separate from either caller because there are two: the pure built-in, and the machine's
/// route for a call that carries a reviver.
fn parse_json_text(text: &StringUnits) -> Result<Value, ExecutionError> {
    kiln_json::parse_units(text, json_value_from_tape).map_err(|_| ExecutionError::InvalidJson)?
}

fn is_json_whitespace(unit: u16) -> bool {
    matches!(unit, 0x20 | 0x09 | 0x0a | 0x0d)
}

fn delete_property_checked(
    intrinsics: &Intrinsics,
    target: &Value,
    key: &Value,
) -> Result<bool, ExecutionError> {
    let units = key.property_key_units_checked()?;
    Ok(delete_property_key(
        intrinsics,
        target,
        PropertyKeyRef::Units(&units),
    ))
}

#[cfg(test)]
fn delete_property(intrinsics: &Intrinsics, target: &Value, key: &Value) -> bool {
    delete_property_checked(intrinsics, target, key).expect("test property-key conversion")
}

fn delete_property_key(intrinsics: &Intrinsics, target: &Value, key: PropertyKeyRef<'_>) -> bool {
    match target {
        Value::Object(object) => {
            // `delete` reports whether the property is gone, and a non-configurable one never
            // is. `remove` already declines to do the work; the answer has to agree with it.
            let removable = object
                .borrow()
                .get_own_attributes_key(key)
                .is_none_or(|attributes| attributes.configurable);
            if !removable {
                return false;
            }
            object.borrow_mut().remove_key(key);
            true
        }
        // A function owns properties too -- a class's statics live in a store of its own -- and
        // `delete C.of` has to reach that store rather than silently succeeding against nothing.
        Value::Function(closure) => {
            let removable = closure
                .properties
                .borrow()
                .get_own_attributes_key(key)
                .is_none_or(|attributes| attributes.configurable);
            if !removable {
                return false;
            }
            closure.properties.borrow_mut().remove_key(key);
            true
        }
        // Removing an element leaves a *hole* rather than shortening the array: the slot reads
        // as undefined and `length` is unchanged, but `1 in a` is false and a console shows
        // `<1 empty item>`. The comment said hole and the code wrote undefined, which is the
        // one place the difference between the two is directly observable.
        Value::Array(items) => {
            // `length` is non-configurable, so `delete a.length` is false and the array keeps it.
            if key.matches_ascii("length") {
                return false;
            }
            if items.properties.borrow().is_frozen() {
                return false;
            }
            let Some(index) = array_index_key(key) else {
                // Not an index, so it is an ordinary named property of the array and it lives in
                // the store beside the elements. Reporting `true` without reaching that store
                // said the property was gone while it was still there -- which every
                // descriptor test in the corpus notices, because `verifyProperty` deletes a
                // property and restores it and had been restoring one that never left.
                return remove_exotic_property_key(&items.properties, key);
            };
            // An element a program locked down will not go, and `delete` reports that
            // rather than leaving `length` describing an array that no longer matches it.
            if let Some(entry) = array_exotic_element(items, index) {
                if !entry.attributes.configurable {
                    return false;
                }
                items
                    .elements
                    .borrow_mut()
                    .retain(|other| other.index != index);
            }
            if let Some(slot) = items.borrow_mut().get_mut(index) {
                items.sparse.set(true);
                *slot = Value::Native(Native::Hole, RealmId::PRIMARY);
            }
            true
        }
        Value::TypedArray(view) => match canonical_numeric_index_key(key) {
            // An element that is really there will not go -- the specification gives an
            // integer-indexed property no way to be configured away -- and an element key that
            // reaches no slot was never there to remove, so `delete` reports it gone.
            Some(index) => valid_integer_index(view, index).is_none(),
            None => remove_exotic_property_key(&view.properties, key),
        },
        other if exotic_properties(other).is_some() => match exotic_properties(target) {
            Some(store) if !exotic_reserved_name_key(target, key) => {
                remove_exotic_property_key(store, key)
            }
            _ => true,
        },
        Value::String(text) => {
            let indexed = array_index_key(key).is_some_and(|index| index < text.unit_len());
            !(key.matches_ascii("length") || indexed)
        }
        // A built-in's own properties are tabulated rather than stored, so removing one is
        // recording the removal in the realm's store -- which is what makes the specification's
        // `configurable: true` on almost all of them mean something.
        Value::Native(_, _) | Value::Callback(_, _) => {
            match own_attributes_key(intrinsics, target, key) {
                // Never there, so it is gone: `delete Math.nonesuch` is true.
                None => true,
                Some(attributes) if attributes.configurable => {
                    intrinsics.remove_key(target, key);
                    true
                }
                Some(_) => false,
            }
        }
        // Nothing else carries own properties, so there is nothing to fail to remove.
        _ => true,
    }
}

/// Every own property of a value, in enumeration order, symbol-keyed ones included.
///
/// This is what a spread copies, and it is deliberately not the same set `Object.keys` returns:
/// spread carries symbol keys across and `Object.keys` does not. An array or a string contributes
/// its indices, which is what makes `{ ...[1, 2] }` an object with keys "0" and "1"; a primitive
/// with nothing of its own contributes nothing, and so does `null` or `undefined`.

fn own_properties_units(intrinsics: &Intrinsics, value: &Value) -> Vec<(StringUnits, Property)> {
    match value {
        // A built-in's tabulated properties are all non-enumerable, so what a spread or an
        // `Object.assign` copies off one is exactly what a program put there -- with one
        // exception, and it is the exception every bundler's output depends on. A Node builtin
        // module's exports *are* enumerable, which is what makes `{ ...require("path") }` and
        // `export * from "path"` copy anything at all.
        Value::Native(_, _) | Value::Callback(_, _) => intrinsics.enumerable_entries_units(value),
        // A function is an object, and a static a program hung on one is an own enumerable
        // property like any other -- which is the whole reason `{ ...postcss }` copies anything
        // at all when `postcss` is a function carrying its plugins. `length` and `name` are
        // stored non-enumerable and `prototype` is not in this store, so the pair that decides
        // what a spread sees is already the pair the specification marks: `{ ...f }` is what the
        // program put on `f` and nothing of the function itself.
        Value::Function(closure) => closure
            .properties
            .borrow()
            .entries()
            .map(|(key, property)| (key.clone(), property.clone()))
            .collect(),
        // A bound function keeps its own store, and `length` and `name` are not in it -- the
        // own-key walk supplies those two literally -- so what is here is exactly what a holder
        // added.
        Value::Bound(bound) => bound
            .properties
            .borrow()
            .entries()
            .map(|(key, property)| (key.clone(), property.clone()))
            .collect(),
        Value::Object(object) => string_wrapper_entries_units(value)
            .into_iter()
            .chain(
                object
                    .borrow()
                    .entries()
                    .map(|(key, property)| (key.clone(), property.clone())),
            )
            .collect(),
        // The indices first and then whatever the program hung on the array by name, which is
        // the order `OrdinaryOwnPropertyKeys` gives and the order `Object.keys` already used
        // here. Stopping at the indices made this function disagree with the own-key walk beside
        // it about the same array: `Object.keys(a)` listed `a.total` and `{ ...a }` dropped it.
        // `length` is absent from both, because it is not enumerable.
        Value::Array(items) => items
            .borrow()
            .iter()
            .enumerate()
            // A hole has no key, so it is absent from `Object.keys`, `for-in` and a spread.
            .filter(|(_, item)| !matches!(item, Value::Native(Native::Hole, _)))
            .map(|(index, item)| {
                (
                    StringUnits::from(index.to_string()),
                    Property::Value(item.clone()),
                )
            })
            .chain(
                items
                    .properties
                    .borrow()
                    .entries()
                    .map(|(key, property)| (key.clone(), property.clone()))
                    .collect::<Vec<_>>(),
            )
            .collect(),
        // The elements, and then whatever the program hung on the view: a spread copies both,
        // in the order the own-key walk lists them.
        Value::TypedArray(view) => {
            let mut entries: Vec<(StringUnits, Property)> = (0..view.len())
                .filter_map(|index| {
                    view.get(index)
                        .map(|value| (StringUnits::from(index.to_string()), Property::Value(value)))
                })
                .collect();
            entries.extend(
                view.properties
                    .borrow()
                    .entries()
                    .map(|(key, property)| (key.clone(), property.clone())),
            );
            entries
        }
        other if exotic_properties(other).is_some() => exotic_properties(value)
            .map(|store| {
                store
                    .borrow()
                    .entries()
                    .map(|(key, property)| (key.clone(), property.clone()))
                    .collect()
            })
            .unwrap_or_default(),
        Value::String(text) => text
            .units()
            .enumerate()
            .map(|(index, unit)| {
                (
                    StringUnits::from(index.to_string()),
                    Property::Value(Value::String(StringUnits::from_units(&[unit]))),
                )
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// A number written in a base other than ten.
///
/// The fraction is expanded by repeated multiplication rather than converted through a decimal
/// string, because there is no decimal spelling of `0.1` in base 3 to convert. It stops at 52
/// digits, which is where the mantissa runs out and every further digit would be invented.
fn number_in_radix(value: f64, radix: u32) -> String {
    if !value.is_finite() {
        return number_string(value);
    }
    let negative = value < 0.0;
    let magnitude = value.abs();

    let mut whole = magnitude.trunc();
    let mut digits = Vec::new();
    if whole == 0.0 {
        digits.push('0');
    }
    while whole >= 1.0 {
        let digit = (whole % f64::from(radix)) as u32;
        digits.push(char::from_digit(digit, radix).expect("a digit below the radix"));
        whole = (whole / f64::from(radix)).trunc();
    }
    digits.reverse();
    let mut text: String = digits.into_iter().collect();

    let mut fraction = magnitude.fract();
    if fraction > 0.0 {
        text.push('.');
        for _ in 0..52 {
            if fraction == 0.0 {
                break;
            }
            fraction *= f64::from(radix);
            let digit = fraction.trunc();
            text.push(char::from_digit(digit as u32, radix).expect("a digit below the radix"));
            fraction -= digit;
        }
    }

    if negative { format!("-{text}") } else { text }
}

/// Positional argument at `index` as a number, or NaN when there is none.
///
/// ToNumber refuses BigInt and Symbol with a TypeError.
fn argument_number_at(arguments: &[Value], index: usize) -> Result<f64, ExecutionError> {
    match arguments.get(index) {
        None | Some(Value::Undefined) => Ok(f64::NAN),
        Some(Value::BigInt(_)) => Err(ExecutionError::BigIntIsNotANumber),
        Some(Value::Symbol(_)) => Err(ExecutionError::SymbolIsNotANumber),
        Some(other) => Ok(other.as_number()),
    }
}

/// The first argument as a number, or NaN when there is none.
///
/// `Math.abs()` is NaN rather than 0: a missing argument is `undefined`, and `Number(undefined)`
/// is NaN.
fn argument_number(arguments: &[Value]) -> Result<f64, ExecutionError> {
    argument_number_at(arguments, 0)
}

fn is_integer(value: f64) -> bool {
    value.is_finite() && value.fract() == 0.0
}

/// `Number.prototype.toFixed`, as the specification spells it: the integer `n` for which
/// `n / 10^f - x` is closest to zero, taking the *larger* `n` on a tie.
///
/// Not `format!("{x:.*}")`, which rounds ties to even -- so it answered `"2"` for
/// `(2.5).toFixed(0)` where the language says `"3"`. Written as an integer rounding rather than as
/// a formatting flag so the C backend can be the same handful of lines: the two engines agreeing
/// about rounding matters more than either being clever about it.
///
/// The scaling is done in binary64, so a value whose scaled form needs more than 53 bits gets the
/// nearest double rather than the exact integer the specification names. Everything a program
/// actually formats -- a price, a percentage, a duration -- is far inside that.
fn number_to_fixed(value: f64, digits: u32) -> String {
    if !value.is_finite() || value.abs() >= 1e21 {
        // The specification hands both of these back to `ToString`.
        return number_string(value);
    }
    let places = digits as usize;
    // The *exact* decimal expansion, not a rounding of it. A binary64 has at most 1074 fractional
    // digits, so this is the value itself -- and it has to be, because the digit that decides the
    // rounding is one `{:.places$}` would already have consumed. That matters beyond ties:
    // `(1.45).toFixed(1)` is `"1.4"`, because 1.45 is really 1.44999..., and any scaling by a
    // power of ten rounds that up to 14.5 before the language ever gets to look at it.
    let exact = format!("{:.*}", 1074, value.abs());
    let point = exact.find('.').unwrap_or(exact.len());
    let mut kept: Vec<u8> = exact.bytes().filter(|byte| *byte != b'.').collect();
    let decided = point + places;
    // Round half *up*, which is what "if there are two such n, pick the larger n" says. Rust's own
    // formatting rounds ties to even and would answer `"2"` for `(2.5).toFixed(0)`.
    let round_up = kept.get(decided).is_some_and(|digit| *digit >= b'5');
    kept.truncate(decided);
    if round_up {
        let mut at = kept.len();
        loop {
            if at == 0 {
                kept.insert(0, b'1');
                break;
            }
            at -= 1;
            if kept[at] == b'9' {
                kept[at] = b'0';
            } else {
                kept[at] += 1;
                break;
            }
        }
    }
    let sign = if value < 0.0 { "-" } else { "" };
    let text = String::from_utf8(kept).unwrap_or_default();
    // A carry can have lengthened the integer part, so it is measured rather than assumed.
    let split = text.len() - places;
    if places == 0 {
        return format!("{sign}{text}");
    }
    format!("{sign}{}.{}", &text[..split], &text[split..])
}

/// The `n` and `e` the specification's exponential formats name, for a non-negative finite value.
///
/// `count` significant digits of the *exact* decimal expansion, rounded half up -- the
/// specification's "if there are two such sets, pick the larger n" -- and the decimal exponent of
/// the first of them. Taken from the exact expansion for the reason [`number_to_fixed`] gives:
/// scaling by a power of ten first would round the deciding digit away before the language ever
/// looked at it.
fn significant_digits(value: f64, count: usize) -> (String, i32) {
    let exact = format!("{value:.1074}");
    let point = exact.find('.').unwrap_or(exact.len());
    let digits: Vec<u8> = exact.bytes().filter(|byte| *byte != b'.').collect();
    let Some(first) = digits.iter().position(|digit| *digit != b'0') else {
        // Zero has no significant digit; the specification names its mantissa as zeros and its
        // exponent as zero.
        return ("0".repeat(count), 0);
    };
    // The digit at `first` sits in the place worth 10^(point - 1 - first).
    let exponent = point as i32 - 1 - first as i32;
    let mut kept: Vec<u8> = digits.iter().skip(first).take(count).copied().collect();
    kept.resize(count, b'0');
    if digits
        .get(first + count)
        .is_some_and(|digit| *digit >= b'5')
    {
        let mut at = kept.len();
        loop {
            if at == 0 {
                // The carry ran off the front: every digit was a nine, so the mantissa is a one
                // followed by zeros and the exponent moved up one.
                kept.insert(0, b'1');
                kept.pop();
                return (String::from_utf8(kept).unwrap_or_default(), exponent + 1);
            }
            at -= 1;
            if kept[at] == b'9' {
                kept[at] = b'0';
            } else {
                kept[at] += 1;
                break;
            }
        }
    }
    (String::from_utf8(kept).unwrap_or_default(), exponent)
}

/// One mantissa and exponent as both exponential formats write them: `1.25e+2`.
fn exponential_string(sign: &str, mantissa: &str, exponent: i32) -> String {
    let body = if mantissa.len() > 1 {
        format!("{}.{}", &mantissa[..1], &mantissa[1..])
    } else {
        mantissa.to_owned()
    };
    let marker = if exponent < 0 { '-' } else { '+' };
    format!("{sign}{body}e{marker}{}", exponent.abs())
}

/// `Number.prototype.toExponential`.
///
/// With no digit count the specification asks for the fewest digits that name the value exactly,
/// which is what Rust's own exponential formatting already produces -- the same shortest
/// round-tripping form `number_string` relies on.
fn number_to_exponential(value: f64, digits: Option<usize>) -> String {
    if !value.is_finite() {
        return number_string(value);
    }
    let sign = if value < 0.0 { "-" } else { "" };
    let magnitude = value.abs();
    let (mantissa, exponent) = match digits {
        Some(count) => significant_digits(magnitude, count + 1),
        None => {
            let rendered = format!("{magnitude:e}");
            let (mantissa, exponent) = rendered.split_once('e').unwrap_or((rendered.as_str(), "0"));
            (
                mantissa.replace('.', ""),
                exponent.parse::<i32>().unwrap_or(0),
            )
        }
    };
    exponential_string(sign, &mantissa, exponent)
}

/// `Number.prototype.toPrecision`.
///
/// The switch to the exponential form is the specification's own window, and it is what keeps
/// `(0.0000001).toPrecision(2)` from being a string of zeros with no digits in it.
fn number_to_precision(value: f64, digits: usize) -> String {
    let sign = if value < 0.0 { "-" } else { "" };
    let (mantissa, exponent) = significant_digits(value.abs(), digits);
    if exponent < -6 || exponent >= digits as i32 {
        return exponential_string(sign, &mantissa, exponent);
    }
    if exponent == digits as i32 - 1 {
        return format!("{sign}{mantissa}");
    }
    if exponent >= 0 {
        let split = exponent as usize + 1;
        return format!("{sign}{}.{}", &mantissa[..split], &mantissa[split..]);
    }
    format!("{sign}0.{}{mantissa}", "0".repeat((-exponent - 1) as usize))
}

/// `BigInt.asIntN` and `asUintN`: the low `bits` of a value, read as signed or unsigned.
///
/// `None` for a width whose result no engine would build -- the specification allows up to 2^53,
/// and materialising a modulus that wide is a petabyte rather than an answer.
fn truncate_bigint(
    value: &num_bigint::BigInt,
    bits: u64,
    signed: bool,
) -> Option<num_bigint::BigInt> {
    if bits == 0 {
        return Some(num_bigint::BigInt::from(0));
    }
    // A window wider than the value already is cannot change it. The one exception is a negative
    // value read as unsigned, which wraps however wide the window is.
    if value.bits() < bits && (signed || !matches!(value.sign(), num_bigint::Sign::Minus)) {
        return Some(value.clone());
    }
    let width = usize::try_from(bits).ok().filter(|bits| *bits <= 1 << 24)?;
    let modulus = num_bigint::BigInt::from(1) << width;
    let mut remainder = value % &modulus;
    if matches!(remainder.sign(), num_bigint::Sign::Minus) {
        remainder += &modulus;
    }
    if signed && remainder >= (&modulus >> 1_usize) {
        remainder -= &modulus;
    }
    Some(remainder)
}

/// `parseInt(text, radix?)`.
///
/// Reads as far as it can and stops, rather than rejecting: `parseInt("12px")` is 12. That
/// tolerance is the entire difference from `Number("12px")`, which is NaN.
fn parse_int(arguments: &[Value]) -> Value {
    let text = arguments
        .first()
        .map_or_else(String::new, Value::to_display_string);
    let text = text.trim();
    let radix = match arguments.get(1).map(Value::as_number) {
        Some(radix) if radix.is_finite() && radix != 0.0 => radix.trunc(),
        _ => 0.0,
    };
    // Ranged before the cast, not after: `as u32` saturates, so a negative radix became zero --
    // which reads as "no radix given" and quietly parsed `parseInt('12', -1)` as decimal where
    // the language says NaN.
    if !(radix == 0.0 || (2.0..=36.0).contains(&radix)) {
        return Value::Number(f64::NAN);
    }
    #[expect(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    let radix = radix as u32;

    let (negative, rest) = match text.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, text.strip_prefix('+').unwrap_or(text)),
    };
    // `0x` selects hexadecimal when no radix was given, and is also allowed when 16 was.
    let (radix, digits) = match rest.strip_prefix("0x").or_else(|| rest.strip_prefix("0X")) {
        Some(after) if radix == 0 || radix == 16 => (16, after),
        _ => (if radix == 0 { 10 } else { radix }, rest),
    };

    let end = digits
        .find(|character: char| !character.is_digit(radix))
        .unwrap_or(digits.len());
    if end == 0 {
        return Value::Number(f64::NAN);
    }
    // Folded as f64 rather than parsed into an integer: the result is a double either way, and a
    // long run of digits must saturate toward infinity rather than overflow.
    let magnitude = digits[..end].chars().fold(0.0f64, |total, digit| {
        total * f64::from(radix) + f64::from(digit.to_digit(radix).expect("checked by `find`"))
    });
    Value::Number(if negative { -magnitude } else { magnitude })
}

/// `parseFloat(text)`, which is `parseInt`'s tolerance applied to a decimal literal.
fn parse_float(arguments: &[Value]) -> Value {
    let text = arguments
        .first()
        .map_or_else(String::new, Value::to_display_string);
    let text = text.trim_start();
    if text.starts_with("Infinity") || text.starts_with("+Infinity") {
        return Value::Number(f64::INFINITY);
    }
    if text.starts_with("-Infinity") {
        return Value::Number(f64::NEG_INFINITY);
    }
    // A decimal literal starts with a digit or a point. Checked before the prefix search below,
    // because Rust's float parser also accepts `inf`, `infinity` and `nan` -- spellings this
    // grammar does not have, and which would otherwise have made `parseFloat('inf')` infinite.
    if !text
        .strip_prefix(['+', '-'])
        .unwrap_or(text)
        .starts_with(|character: char| character.is_ascii_digit() || character == '.')
    {
        return Value::Number(f64::NAN);
    }
    // Take the longest prefix that parses, which is what "reads as far as it can" means when the
    // grammar allows an exponent: "1e" is 1, not an error.
    let mut best = None;
    for end in (1..=text.len()).rev() {
        if !text.is_char_boundary(end) {
            continue;
        }
        if let Ok(number) = text[..end].parse::<f64>() {
            best = Some(number);
            break;
        }
    }
    Value::Number(best.unwrap_or(f64::NAN))
}

/// Resolve one end of a `slice`-style range.
///
/// A negative argument counts from the end, which is the whole reason this is not a cast: `-2`
/// means "two from the end", not "clamp to zero". Both ends are clamped into the array.
/// Where a relative index lands, or `None` for one that names nothing.
///
/// A negative index counts back from the end, which is what `with(-1, x)` uses -- and a negative
/// one that reaches past the start names no element at all, where the clamping [`relative_index`]
/// used by `slice` would answer zero. The difference is a `RangeError` rather than a wrong
/// element, so the two cannot share.
fn relative_position(relative: f64, length: usize) -> Option<usize> {
    if relative.is_nan() {
        return Some(0);
    }
    let absolute = if relative < 0.0 {
        length as f64 + relative.trunc()
    } else {
        relative.trunc()
    };
    if absolute < 0.0 || absolute > length as f64 {
        return None;
    }
    Some(absolute as usize)
}

fn relative_index(argument: Option<&Value>, length: usize, default: usize) -> usize {
    let Some(value) = argument.filter(|value| !matches!(value, Value::Undefined)) else {
        return default;
    };
    let relative = value.as_number();
    if relative.is_nan() {
        return 0;
    }
    let length = length as f64;
    let resolved = if relative < 0.0 {
        (length + relative).max(0.0)
    } else {
        relative.min(length)
    };
    resolved as usize
}

/// A reader over JSON text.
///
/// Build the `Value` graph `JSON.parse` answers with from the tape the shared reader produced.
///
/// The reader is `kiln-json`, the same crate the native provider archive links, so the two engines
/// cannot disagree about the grammar (ADR 0025). What is left here is the part only this engine
/// can do: make its own strings, arrays and objects. Iterative over an explicit stack, as the
/// reader is, so a document's nesting is bounded by its length rather than by the machine's
/// stack. Duplicate keys take the last value in the first position and `__proto__` is an
/// ordinary own property, both because `ObjectData::set` does exactly that.
fn json_value_from_tape(document: &kiln_json::Tape<'_>) -> Result<Value, ExecutionError> {
    enum Frame {
        Array {
            items: Vec<Value>,
            remaining: usize,
        },
        Object {
            data: ObjectData,
            remaining: usize,
            key: Option<StringUnits>,
        },
    }
    let mut stack: Vec<Frame> = Vec::new();
    let mut root = None;
    for node in document.nodes() {
        if root.is_some() {
            return Err(ExecutionError::InvalidJson);
        }
        let count = node.len as usize;
        let mut value = match node.tag {
            kiln_json::TAG_NULL => Value::Null,
            kiln_json::TAG_FALSE => Value::Boolean(false),
            kiln_json::TAG_TRUE => Value::Boolean(true),
            kiln_json::TAG_NUMBER => Value::Number(node.as_number().unwrap_or(0.0)),
            kiln_json::TAG_STRING => Value::String(
                document
                    .string_units(node)
                    .ok_or(ExecutionError::InvalidJson)?,
            ),
            kiln_json::TAG_ARRAY => {
                if count != 0 {
                    stack.push(Frame::Array {
                        items: Vec::with_capacity(count),
                        remaining: count,
                    });
                    continue;
                }
                Value::Array(ArrayData::new(Vec::new()))
            }
            kiln_json::TAG_OBJECT => {
                if count != 0 {
                    stack.push(Frame::Object {
                        data: ObjectData::default(),
                        remaining: count,
                        key: None,
                    });
                    continue;
                }
                Value::Object(Rc::new(RefCell::new(ObjectData::default())))
            }
            _ => return Err(ExecutionError::InvalidJson),
        };
        // Deliver the value to the container it belongs to, and every container that completes
        // with it to the one above.
        loop {
            let Some(frame) = stack.last_mut() else {
                root = Some(value);
                break;
            };
            match frame {
                Frame::Array { items, remaining } => {
                    items.push(value);
                    *remaining -= 1;
                    if *remaining != 0 {
                        break;
                    }
                }
                Frame::Object {
                    data,
                    remaining,
                    key,
                } => match key.take() {
                    None => {
                        let Value::String(name) = value else {
                            return Err(ExecutionError::InvalidJson);
                        };
                        *key = Some(name);
                        break;
                    }
                    Some(name) => {
                        data.set_units(&name, value);
                        *remaining -= 1;
                        if *remaining != 0 {
                            break;
                        }
                    }
                },
            }
            value = match stack.pop() {
                Some(Frame::Array { items, .. }) => Value::Array(ArrayData::new(items)),
                Some(Frame::Object { data, .. }) => Value::Object(Rc::new(RefCell::new(data))),
                None => return Err(ExecutionError::InvalidJson),
            };
        }
    }
    root.ok_or(ExecutionError::InvalidJson)
}

/// Render a value the way a console does.
///
/// Deliberately not `to_display_string`, which is `String(value)` and answers a different
/// question: `String({ a: 1 })` is "[object Object]" and always will be, while a console showing
/// that instead of the contents is close to useless. Nested strings are quoted and top-level ones
/// are not, for the same reason -- `console.log("hi")` prints hi, but `{ a: "hi" }` has to show
/// that `a` holds a string rather than a bare word.
///
/// Follows node's `util.inspect` closely enough for `scripts/differential.sh` to diff against it,
/// with two documented limits: output is always one line, where node wraps past about 72
/// characters, and a cycle is marked `[Circular *1]` without node's matching `<ref *1>` prefix.
pub(crate) fn inspect(value: &Value) -> String {
    match value {
        // A top-level string prints as itself; only a nested one is quoted.
        Value::String(text) => text.to_lossy_string(),
        other => inspect_nested(other, 0, &mut Vec::new()),
    }
}

/// How deep node descends before printing a placeholder instead of the contents.
const INSPECT_DEPTH: usize = 2;

fn inspect_nested(value: &Value, depth: usize, seen: &mut Vec<usize>) -> String {
    match value {
        Value::String(text) => quote_for_console(&text.to_lossy_string()),
        Value::Undefined | Value::Null | Value::Boolean(_) | Value::Number(_) => {
            // `-0` prints as itself here, where `String(-0)` is "0": the console is showing the
            // value, not converting it.
            match value {
                Value::Number(number) if *number == 0.0 && number.is_sign_negative() => {
                    "-0".to_owned()
                }
                other => other.to_display_string(),
            }
        }
        Value::Symbol(symbol) => format!("Symbol({})", symbol.description()),
        Value::Function(closure) => match &closure.name {
            Some(name) => format!("[Function: {name}]"),
            None => "[Function (anonymous)]".to_owned(),
        },
        Value::Native(native, _) => match namespace_name(native) {
            Some(name) => format!("Object [{name}] {{}}"),
            None => format!("[Function: {}]", native_js_name(native)),
        },
        Value::Callback(method, _) => {
            format!("[Function: {}]", builtin_js_name(&format!("{method:?}")))
        }
        Value::Generator(_) => "Object [Generator] {}".to_owned(),
        Value::Intl(value) => format!("{} {{}}", value.service().tag()),
        Value::Settler(..) | Value::Capability(..) | Value::Element(_) => {
            "[Function (anonymous)]".to_owned()
        }
        // Node prints the target's name with a "bound " prefix; without a name to prefix, the
        // fact that it is bound is the whole of what there is to say.
        Value::Bound(_) => "[Function: bound]".to_owned(),
        Value::Wrapped(_) => "[Function: wrapped]".to_owned(),
        Value::CommonJsRequire(_) => "[Function: require]".to_owned(),
        Value::CommonJsResolve(_) => "[Function: resolve]".to_owned(),
        // Node shows what the traps produce; this shows the target, and says so, rather than
        // running a program's code because something was printed.
        Value::Proxy(proxy) => format!("Proxy [ {} ]", inspect_nested(&proxy.target, depth, seen)),
        Value::TypedArray(view) => {
            let items = view
                .items()
                .iter()
                .map(|item| inspect_nested(item, depth + 1, seen))
                .collect::<Vec<_>>();
            let name = view.kind.name();
            if items.is_empty() {
                format!("{name}(0) []")
            } else {
                format!("{name}({}) [ {} ]", items.len(), items.join(", "))
            }
        }
        Value::ArrayBuffer(buffer) => {
            let name = if buffer.shared {
                "SharedArrayBuffer"
            } else {
                "ArrayBuffer"
            };
            format!("{name} {{ byteLength: {} }}", buffer.byte_length())
        }
        Value::DataView(view) => format!(
            "DataView {{ byteLength: {}, byteOffset: {} }}",
            view.byte_length().unwrap_or(0),
            view.offset
        ),
        Value::RegExp(regexp) => format!(
            "/{}/{}",
            regexp.source.to_lossy_string(),
            canonical_regexp_flags(&regexp.flags)
        ),
        Value::Date(date) => {
            iso_string(date.time.get()).unwrap_or_else(|| "Invalid Date".to_owned())
        }
        Value::Temporal(built) => built
            .value()
            .to_temporal_string(&kiln_temporal::Options::default())
            .unwrap_or_else(|_| format!("[object {}]", built.kind().tag())),
        // A console shows the literal's spelling, which is how it is told from a number.
        Value::BigInt(value) => format!("{value}n"),
        Value::Promise(promise) => match &promise.state.borrow().settled {
            None => "Promise { <pending> }".to_owned(),
            Some(Settled::Fulfilled(value)) => {
                format!("Promise {{ {} }}", inspect_nested(value, depth + 1, seen))
            }
            Some(Settled::Rejected(reason)) => format!(
                "Promise {{ <rejected> {} }}",
                inspect_nested(reason, depth + 1, seen)
            ),
        },
        Value::Array(items) => {
            let Some(guard) = InspectGuard::enter(seen, Rc::as_ptr(items).cast::<()>()) else {
                return "[Circular *1]".to_owned();
            };
            if depth > INSPECT_DEPTH {
                return "[Array]".to_owned();
            }
            // An array's own named properties are shown after its elements: `index` and `input`
            // on a match result are the reason this matters, and hiding them made a printed
            // match look like a plain array of strings.
            let named: Vec<String> = items
                .properties
                .borrow()
                .entries()
                .filter(|(key, _)| !symbol::is_reserved(&key.to_lossy_string()))
                .map(|(key, property)| {
                    let shown = match property {
                        Property::Value(value) => inspect_nested(value, depth + 1, guard.seen),
                        Property::Accessor { .. } => "[Getter/Setter]".to_owned(),
                    };
                    format!("{}: {}", inspect_key(&key.to_lossy_string()), shown)
                })
                .collect();
            let items = items.borrow();
            if items.is_empty() && named.is_empty() {
                return "[]".to_owned();
            }
            // A run of holes is reported as a count rather than repeated, which is what node
            // does and what makes a sparse array readable at all.
            let mut parts: Vec<String> = Vec::new();
            let mut holes = 0usize;
            for item in items.iter() {
                if matches!(item, Value::Native(Native::Hole, _)) {
                    holes += 1;
                    continue;
                }
                if holes > 0 {
                    parts.push(empty_items(holes));
                    holes = 0;
                }
                parts.push(inspect_nested(item, depth + 1, guard.seen));
            }
            if holes > 0 {
                parts.push(empty_items(holes));
            }
            parts.extend(named);
            format!("[ {} ]", parts.join(", "))
        }
        Value::Object(object) => {
            let Some(guard) = InspectGuard::enter(seen, Rc::as_ptr(object).cast::<()>()) else {
                return "[Circular *1]".to_owned();
            };
            if depth > INSPECT_DEPTH {
                return "[Object]".to_owned();
            }
            inspect_object(&object.borrow(), depth, guard.seen)
        }
        Value::Cell(_) => unreachable!("a cell is never inspected"),
    }
}

fn inspect_object(object: &ObjectData, depth: usize, seen: &mut Vec<usize>) -> String {
    // A Set or Map is an object carrying reserved state, and a console shows what it holds
    // rather than the bookkeeping that makes it work.
    if let Some(Value::Array(entries)) = object.get_own("@@entries") {
        let is_map = matches!(object.get_own("@@map"), Some(&Value::Boolean(true)));
        let live: Vec<_> = entries
            .borrow()
            .iter()
            .filter(|entry| !matches!(entry, Value::Native(Native::Tombstone, _)))
            .cloned()
            .collect();
        // A weak collection shows neither its size nor its contents. It cannot: an entry is
        // reachable only through a key the console does not hold, and printing a count would make
        // the collector's timing observable from the program. `Map(0) {}` was the wrong label
        // twice over -- it named a type the value is not, so a log line said `Map` about
        // something `x instanceof Map` is false of.
        if matches!(object.get_own("@@weak"), Some(&Value::Boolean(true))) {
            let label = if is_map { "WeakMap" } else { "WeakSet" };
            return format!("{label} {{ <items unknown> }}");
        }
        let label = if is_map { "Map" } else { "Set" };
        if live.is_empty() {
            return format!("{label}(0) {{}}");
        }
        let parts = live
            .iter()
            .map(|entry| match (is_map, entry) {
                (true, Value::Array(pair)) => {
                    let pair = pair.borrow();
                    let key = pair.first().cloned().unwrap_or(Value::Undefined);
                    let value = pair.get(1).cloned().unwrap_or(Value::Undefined);
                    format!(
                        "{} => {}",
                        inspect_nested(&key, depth + 1, seen),
                        inspect_nested(&value, depth + 1, seen)
                    )
                }
                (_, entry) => inspect_nested(entry, depth + 1, seen),
            })
            .collect::<Vec<_>>();
        return format!("{label}({}) {{ {} }}", live.len(), parts.join(", "));
    }

    let parts = object
        .entries()
        // Reserved keys are the VM's own and symbol-keyed properties; node shows the latter as
        // `[Symbol(x)]: v`, which needs a key-to-symbol map this VM does not keep.
        .filter(|(key, _)| !symbol::is_reserved(&key.to_lossy_string()))
        .map(|(key, property)| {
            let shown = match property {
                Property::Value(value) => inspect_nested(value, depth + 1, seen),
                // Node names the accessor rather than calling it: showing a value here would run
                // the program's code just because something was printed.
                Property::Accessor { get, set } => match (get.is_some(), set.is_some()) {
                    (true, true) => "[Getter/Setter]".to_owned(),
                    (true, false) => "[Getter]".to_owned(),
                    _ => "[Setter]".to_owned(),
                },
            };
            format!("{}: {}", inspect_key(&key.to_lossy_string()), shown)
        })
        .collect::<Vec<_>>();
    // Node names the class an instance came from, so a printed object says what it is. A plain
    // object's prototype is `Object.prototype`, which this realm does not have as an object, so
    // the absence of a prototype means plain here.
    let label = match constructor_label(object) {
        Some(name) => format!("{name} "),
        None => String::new(),
    };
    if parts.is_empty() {
        return format!("{label}{{}}");
    }
    format!("{label}{{ {} }}", parts.join(", "))
}

/// The name a console puts in front of an object's contents, if it has one.
///
/// Read off `constructor` on the prototype chain, which is where `x.constructor` reads it from
/// too, so the two can never disagree. `Object` is excluded: node prints a plain object bare.
fn constructor_label(object: &ObjectData) -> Option<String> {
    let constructor = object.get("constructor")?;
    let name = match &constructor {
        Value::Function(closure) => closure.name.as_deref()?.to_owned(),
        Value::Native(native, _) => format!("{native:?}"),
        _ => return None,
    };
    (!name.is_empty() && name != "Object").then_some(name)
}

/// Compile a regular expression, or `None` when the engine rejects the pattern.
fn build_regexp(pattern: &StringUnits, flags: &str) -> Option<Value> {
    let units = pattern.to_units();
    let mut codepoints = Vec::with_capacity(units.len());
    let mut index = 0;
    while index < units.len() {
        let unit = units[index];
        if (0xd800..=0xdbff).contains(&unit)
            && units
                .get(index + 1)
                .is_some_and(|next| (0xdc00..=0xdfff).contains(next))
        {
            let low = units[index + 1];
            codepoints
                .push(0x1_0000 + ((u32::from(unit) - 0xd800) << 10) + u32::from(low) - 0xdc00);
            index += 2;
        } else {
            codepoints.push(u32::from(unit));
            index += 1;
        }
    }
    let compiled = regress::Regex::from_unicode(codepoints.iter().copied(), flags).ok()?;
    Some(Value::RegExp(Rc::new(RegExpData {
        source: pattern.clone(),
        flags: flags.to_owned(),
        compiled,
        global: flags.contains('g'),
        sticky: flags.contains('y'),
        has_indices: flags.contains('d'),
        properties: RefCell::new({
            // `lastIndex` is an ordinary own data property, which is what lets
            // `Object.defineProperty(r, "lastIndex", {writable: false})` be seen by the
            // matcher: writable, not enumerated, and not configurable.
            let mut data = ObjectData::default();
            data.define_value(
                "lastIndex",
                Value::Number(0.0),
                Attributes {
                    writable: true,
                    enumerable: false,
                    configurable: false,
                },
            );
            data
        }),
    })))
}

/// Run a regular expression against a subject from a given UTF-16 offset.
///
/// Returns the match's range and its capture groups, all in UTF-16 units -- which is what the
/// language counts in, and why the subject is converted rather than matched as UTF-8.
fn regexp_search(regexp: &RegExpData, subject: &[u16], start: usize) -> Option<RegExpMatch> {
    if start > subject.len() {
        return None;
    }
    let found = regexp.compiled.find_from_utf16(subject, start).next()?;
    // A sticky pattern must match exactly at the cursor, not merely at or after it.
    if regexp.sticky && found.range().start != start {
        return None;
    }
    let groups = found.groups().collect();
    let names = found
        .named_groups()
        .map(|(name, range)| (name.to_owned(), range))
        .collect();
    Some((found.range(), groups, names))
}

/// `new Array(...)`: a length when given one number, the elements themselves otherwise.
///
/// The one-argument form is the language's oldest ambiguity -- `new Array(3)` is three holes and
/// `new Array('3')` is one string -- and it is not this compiler's to fix.
/// The largest array this representation will materialise.
///
/// `new Array(n)` is specified to produce an array of length `n` that holds no elements at all,
/// and a sparse representation would honour that for every length the specification allows, up
/// to 2^32-1. This one is a dense `Vec`, so the only way to give an array that length is to
/// allocate every slot: `new Array(4294967295)` asks for tens of gigabytes and takes the host
/// down with it -- which is exactly how a conformance sweep of `built-ins/Array` reached a
/// hundred gigabytes and wedged the machine. Refusing above a bound trades a test that cannot
/// pass for one that cannot hang the host. Lifting the bound is what a sparse representation
/// would buy, and nothing else here needs to change for it.
const MAX_DENSE_ARRAY: usize = 1 << 24;

/// The largest backing storage this implementation will allocate for one language string.
///
/// Every engine bounds a string's length -- V8 refuses above 2^29-24 units with `RangeError:
/// Invalid string length` -- and a program can observe only that some bound exists, not where it
/// is. So this one is set where the memory is, not where V8's is: 64 MiB, a quarter of
/// [`MAX_BUFFER_BYTES`], because a string that grows by concatenation holds the old bytes and
/// the new ones at once, and every intermediate on the way to the bound is a separate
/// allocation the host keeps -- a bound of V8's size peaks in the gigabytes before refusing.
/// The budget is backing storage: one byte per Latin1 unit and two bytes per UTF-16 unit.
///
/// Without a bound, `"1".repeat(1 << 20).replace(/(.+)/g, "$1".repeat(1 << 16))` -- which is a
/// real test, and one that accepts the throw as its answer -- expands toward 2^36 characters and
/// takes the process with it, reporting nothing for any other test in the same run.
const MAX_STRING_STORAGE_BYTES: usize = 1 << 26;

/// Refuse a string that would exceed [`MAX_STRING_STORAGE_BYTES`].
///
/// Checked before the bytes are written rather than after, so the refusal costs one allocation
/// of the bound rather than the allocation the program asked for.
fn bounded_string(bytes: usize) -> Result<(), ExecutionError> {
    if bytes > MAX_STRING_STORAGE_BYTES {
        return Err(ExecutionError::StringTooLong { bytes });
    }
    Ok(())
}

/// Append to a string under [`MAX_STRING_STORAGE_BYTES`], refusing rather than growing past it.
/// Append one character, refusing past [`MAX_STRING_STORAGE_BYTES`].
///
/// A replacement template is expanded character by character, and `$1` against a megabyte-long
/// match appends a megabyte every time it appears -- so the refusal has to be checked as the
/// string grows. Checked once at the end, the allocation has already happened: this is what took
/// `staging/sm/String/replace-math.js` to 3.9 GB.
fn push_bounded_char(out: &mut String, character: char) -> Result<(), ExecutionError> {
    bounded_string(out.len().saturating_add(character.len_utf8()))?;
    out.push(character);
    Ok(())
}

fn push_bounded(out: &mut String, text: &str) -> Result<(), ExecutionError> {
    bounded_string(out.len().saturating_add(text.len()))?;
    out.push_str(text);
    Ok(())
}

/// The largest byte buffer this implementation will allocate.
///
/// `new ArrayBuffer(n)` and `new Uint8Array(n)` take their size straight from the program, and a
/// Rust allocation failure is an `abort` rather than a panic: `catch_unwind` cannot contain it,
/// so a single test asking for 7.8 petabytes killed the process and reported nothing for the
/// whole of `built-ins/ArrayBuffer`. Refusing above a bound turns that into one failing test.
const MAX_BUFFER_BYTES: f64 = (1usize << 28) as f64; // 256 MiB

/// `ToIndex`: the specification's coercion for a length or an offset.
///
/// Truncating rather than rounding, `undefined` and `NaN` reading as zero, and anything negative
/// refused outright. The refusal is the point: `new ArrayBuffer(-1)` and `rab.resize(-1)` are
/// `RangeError`s, and clamping them to zero would hand the program an empty buffer where it
/// asked for an impossible one and let the mistake travel.
fn to_index(value: Option<&Value>) -> Result<f64, ExecutionError> {
    to_index_number(value.map_or(0.0, Value::as_number))
}

/// `ToIndex` once the coercion to a number has already happened.
///
/// Split out because an argument that is an object has to be reduced by *calling* one of its
/// methods, which only the machine can do -- and the rules below have to apply to what that
/// call produced rather than to the object.
fn to_index_number(number: f64) -> Result<f64, ExecutionError> {
    let integer = if number.is_nan() { 0.0 } else { number.trunc() };
    if !(0.0..=9_007_199_254_740_991.0).contains(&integer) {
        return Err(ExecutionError::BufferLengthOutOfRange { length: number });
    }
    Ok(integer)
}

/// The element count for a buffer of `length` elements of `width` bytes, bounded.
pub(crate) fn bounded_buffer(length: f64, width: usize) -> Result<usize, ExecutionError> {
    if !length.is_finite() || length <= 0.0 {
        return Ok(0);
    }
    let bytes = length * width as f64;
    if bytes > MAX_BUFFER_BYTES {
        return Err(ExecutionError::BufferTooLarge { bytes });
    }
    Ok(length as usize)
}

/// The largest value the specification accepts as an array length.
const MAX_ARRAY_LENGTH: f64 = 4_294_967_295.0;

/// `Number.MAX_SAFE_INTEGER`: the largest index the language will name.
///
/// `ToLength` clamps to it, and the methods that grow an array-like refuse to push past it --
/// which is not the same bound as an array's own `length`, and the two are checked separately.
const MAX_SAFE_INTEGER: f64 = 9_007_199_254_740_991.0;

/// The same bound as an integer, for the walks that count in one.
const MAX_SAFE_INTEGER_AS_U64: u64 = 9_007_199_254_740_991;

/// What `sort` and `toSorted` refuse a comparator that is neither a function nor `undefined`
/// with. Written once because both check it, and before either touches its receiver.
fn comparator_refused() -> ExecutionError {
    ExecutionError::TypeErrorMessage {
        message: "The comparison function must be either a function or undefined".to_owned(),
    }
}

/// The length an array-like claims, bounded to what this representation can materialise.
///
/// These built-ins read `length` off an arbitrary object and then produce that many elements, so
/// the *object* chooses the allocation. An array-like claiming 2^32-1 reserves tens of gigabytes
/// and then loops four billion times -- a hang wearing an allocation's clothes -- and Test262
/// passes exactly such objects on purpose. A length at or below zero, or not a number at all, is
/// an empty result rather than an error: that is what the specification's ToLength gives.
fn bounded_length(length: f64) -> Result<usize, ExecutionError> {
    if !length.is_finite() || length <= 0.0 {
        return Ok(0);
    }
    if length > MAX_DENSE_ARRAY as f64 {
        return Err(ExecutionError::ArrayTooLarge {
            length: length as usize,
        });
    }
    Ok(length as usize)
}

fn construct_array(arguments: &[Value]) -> Result<Value, ExecutionError> {
    if let [Value::Number(length)] = arguments {
        let length = *length;
        // A non-integer or out-of-range length is a RangeError. Returning an empty array --
        // which this did -- is a wrong answer that a test asserting the throw reads as a pass.
        if !length.is_finite() || length < 0.0 || length.fract() != 0.0 || length > MAX_ARRAY_LENGTH
        {
            return Err(ExecutionError::InvalidArrayLength);
        }
        let length = length as usize;
        if length > MAX_DENSE_ARRAY {
            return Err(ExecutionError::ArrayTooLarge { length });
        }
        return Ok(Value::Array(ArrayData::new(vec![
            Value::Native(
                Native::Hole,
                RealmId::PRIMARY
            );
            length
        ])));
    }
    Ok(Value::Array(ArrayData::new(arguments.to_vec())))
}

/// The civil date a count of days since the epoch names.
///
/// Hinnant's algorithm, which is exact for the whole range a `f64` instant can reach and needs no
/// tables. Shifting the year to start in March is what makes the leap day the last day of the
/// year and removes every special case from the month arithmetic.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let shifted = days + 719_468;
    let era = if shifted >= 0 {
        shifted
    } else {
        shifted - 146_096
    } / 146_097;
    let day_of_era = shifted - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let shifted_month = (5 * day_of_year + 2) / 153;
    let day = (day_of_year - (153 * shifted_month + 2) / 5 + 1) as u32;
    let month = if shifted_month < 10 {
        shifted_month + 3
    } else {
        shifted_month - 9
    } as u32;
    (year + i64::from(month <= 2), month, day)
}

/// The inverse of [`civil_from_days`], for `Date.UTC` and the constructor's field form.
fn days_from_civil(year: i64, month: i64, day: i64) -> i64 {
    let year = year - i64::from(month <= 2);
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let year_of_era = year - era * 400;
    let shifted_month = if month > 2 { month - 3 } else { month + 9 };
    let day_of_year = (153 * shifted_month + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

/// Which part of an instant a reader returns.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DateField {
    Time,
    FullYear,
    Month,
    Day,
    Weekday,
    Hours,
    Minutes,
    Seconds,
    Milliseconds,
    /// Always zero: the realm has no zone but UTC, so there is nothing to offset by.
    TimezoneOffset,
}

/// One function on `Date.prototype`.
///
/// One variant per method rather than one per field read, because the specification gives each
/// its own function object. `getMonth` and `getUTCMonth` answer the same number in a realm whose
/// only zone is UTC (ADR 0015) and are still two functions, with two names and two arities that
/// a program can read; a single variant behind both names could report only one of each.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DateMethod {
    ValueOf,
    GetTime,
    GetFullYear,
    GetUtcFullYear,
    GetMonth,
    GetUtcMonth,
    GetDate,
    GetUtcDate,
    GetDay,
    GetUtcDay,
    GetHours,
    GetUtcHours,
    GetMinutes,
    GetUtcMinutes,
    GetSeconds,
    GetUtcSeconds,
    GetMilliseconds,
    GetUtcMilliseconds,
    GetTimezoneOffset,
    /// Annex B: the year less 1900, which is the shape the language shipped with.
    GetYear,
    SetTime,
    SetFullYear,
    SetUtcFullYear,
    SetMonth,
    SetUtcMonth,
    SetDate,
    SetUtcDate,
    SetHours,
    SetUtcHours,
    SetMinutes,
    SetUtcMinutes,
    SetSeconds,
    SetUtcSeconds,
    SetMilliseconds,
    SetUtcMilliseconds,
    /// Annex B, and not `setFullYear` under another name: a year in 0..99 means 19xx here, the
    /// same legacy rule the two-argument constructor keeps.
    SetYear,
    ToIsoString,
    ToJson,
    ToString,
    ToDateString,
    ToTimeString,
    ToUtcString,
    ToLocaleString,
    ToLocaleDateString,
    ToLocaleTimeString,
    /// `Date.prototype[Symbol.toPrimitive]`, the one method here published under a symbol.
    ToPrimitive,
}

impl DateMethod {
    /// The name the language spells this method.
    ///
    /// Tabulated rather than derived from the variant, which the general derivation cannot
    /// reach: the language writes `UTC`, `ISO` and `JSON` where Rust spells them `Utc`, `Iso`
    /// and `Json`, and a case distinction the input does not carry cannot be recovered.
    const fn js_name(self) -> &'static str {
        match self {
            Self::ValueOf => "valueOf",
            Self::GetTime => "getTime",
            Self::GetFullYear => "getFullYear",
            Self::GetUtcFullYear => "getUTCFullYear",
            Self::GetMonth => "getMonth",
            Self::GetUtcMonth => "getUTCMonth",
            Self::GetDate => "getDate",
            Self::GetUtcDate => "getUTCDate",
            Self::GetDay => "getDay",
            Self::GetUtcDay => "getUTCDay",
            Self::GetHours => "getHours",
            Self::GetUtcHours => "getUTCHours",
            Self::GetMinutes => "getMinutes",
            Self::GetUtcMinutes => "getUTCMinutes",
            Self::GetSeconds => "getSeconds",
            Self::GetUtcSeconds => "getUTCSeconds",
            Self::GetMilliseconds => "getMilliseconds",
            Self::GetUtcMilliseconds => "getUTCMilliseconds",
            Self::GetTimezoneOffset => "getTimezoneOffset",
            Self::GetYear => "getYear",
            Self::SetTime => "setTime",
            Self::SetFullYear => "setFullYear",
            Self::SetUtcFullYear => "setUTCFullYear",
            Self::SetMonth => "setMonth",
            Self::SetUtcMonth => "setUTCMonth",
            Self::SetDate => "setDate",
            Self::SetUtcDate => "setUTCDate",
            Self::SetHours => "setHours",
            Self::SetUtcHours => "setUTCHours",
            Self::SetMinutes => "setMinutes",
            Self::SetUtcMinutes => "setUTCMinutes",
            Self::SetSeconds => "setSeconds",
            Self::SetUtcSeconds => "setUTCSeconds",
            Self::SetMilliseconds => "setMilliseconds",
            Self::SetUtcMilliseconds => "setUTCMilliseconds",
            Self::SetYear => "setYear",
            Self::ToIsoString => "toISOString",
            Self::ToJson => "toJSON",
            Self::ToString => "toString",
            Self::ToDateString => "toDateString",
            Self::ToTimeString => "toTimeString",
            Self::ToUtcString => "toUTCString",
            Self::ToLocaleString => "toLocaleString",
            Self::ToLocaleDateString => "toLocaleDateString",
            Self::ToLocaleTimeString => "toLocaleTimeString",
            // A symbol-keyed method is named for the key it is published under, in brackets --
            // which is what a stack trace through one has to print.
            Self::ToPrimitive => "[Symbol.toPrimitive]",
        }
    }

    /// The declared parameter count.
    ///
    /// A setter declares the field it names and every finer one it will also accept, which is
    /// what makes `setHours(h, m, s, ms)` a single call rather than four -- and the count a
    /// caller reads to decide how many arguments to forward.
    const fn length(self) -> f64 {
        match self {
            Self::SetHours | Self::SetUtcHours => 4.0,
            Self::SetFullYear | Self::SetUtcFullYear | Self::SetMinutes | Self::SetUtcMinutes => {
                3.0
            }
            Self::SetMonth | Self::SetUtcMonth | Self::SetSeconds | Self::SetUtcSeconds => 2.0,
            Self::SetTime
            | Self::SetDate
            | Self::SetUtcDate
            | Self::SetMilliseconds
            | Self::SetUtcMilliseconds
            | Self::SetYear
            | Self::ToJson
            | Self::ToPrimitive => 1.0,
            _ => 0.0,
        }
    }

    /// The part of the instant a reader answers with, or `None` for anything that is not one.
    ///
    /// The local readers answer the UTC field because the realm's local zone *is* UTC -- ADR
    /// 0015 -- not because the two are being conflated.
    const fn reads(self) -> Option<DateField> {
        Some(match self {
            Self::ValueOf | Self::GetTime => DateField::Time,
            Self::GetFullYear | Self::GetUtcFullYear => DateField::FullYear,
            Self::GetMonth | Self::GetUtcMonth => DateField::Month,
            Self::GetDate | Self::GetUtcDate => DateField::Day,
            Self::GetDay | Self::GetUtcDay => DateField::Weekday,
            Self::GetHours | Self::GetUtcHours => DateField::Hours,
            Self::GetMinutes | Self::GetUtcMinutes => DateField::Minutes,
            Self::GetSeconds | Self::GetUtcSeconds => DateField::Seconds,
            Self::GetMilliseconds | Self::GetUtcMilliseconds => DateField::Milliseconds,
            Self::GetTimezoneOffset => DateField::TimezoneOffset,
            _ => return None,
        })
    }

    /// The coarsest field a writer replaces, or `None` for anything that is not one.
    const fn writes(self) -> Option<DateField> {
        Some(match self {
            Self::SetTime => DateField::Time,
            Self::SetFullYear | Self::SetUtcFullYear | Self::SetYear => DateField::FullYear,
            Self::SetMonth | Self::SetUtcMonth => DateField::Month,
            Self::SetDate | Self::SetUtcDate => DateField::Day,
            Self::SetHours | Self::SetUtcHours => DateField::Hours,
            Self::SetMinutes | Self::SetUtcMinutes => DateField::Minutes,
            Self::SetSeconds | Self::SetUtcSeconds => DateField::Seconds,
            Self::SetMilliseconds | Self::SetUtcMilliseconds => DateField::Milliseconds,
            _ => return None,
        })
    }
}

/// `TimeClip`: the instant a date is allowed to hold, or `NaN` for one it is not.
///
/// Two things happen here that look like details and are not. An instant outside +/-8.64e15
/// collapses to the single invalid date, which is why every reader only has to test for NaN;
/// and the truncation's `-0` is folded back to `+0`, which `Object.is` can see and the
/// specification requires -- a date one millisecond before the epoch's *fraction* is the epoch.
fn time_clip(time: f64) -> f64 {
    if !time.is_finite() || time.abs() > 8.64e15 {
        return f64::NAN;
    }
    time.trunc() + 0.0
}

/// The number one reader takes out of an instant.
fn date_read(field: DateField, time: f64) -> f64 {
    match field {
        DateField::Time => return time,
        // The realm has one zone and it is UTC, which this reports honestly rather than leaving
        // to be discovered. An invalid date still has no offset to report.
        DateField::TimezoneOffset => return if time.is_nan() { f64::NAN } else { 0.0 },
        _ => {}
    }
    let Some(parts) = date_parts(time) else {
        // Every reader on an invalid date is NaN, which is what makes one propagate.
        return f64::NAN;
    };
    match field {
        // `getMonth` is zero-based and `getDate` is one-based, which is the language's oldest
        // wart and is not this compiler's to fix.
        DateField::FullYear => parts.year as f64,
        DateField::Month => f64::from(parts.month) - 1.0,
        DateField::Day => f64::from(parts.day),
        DateField::Weekday => f64::from(parts.weekday),
        DateField::Hours => f64::from(parts.hour),
        DateField::Minutes => f64::from(parts.minute),
        DateField::Seconds => f64::from(parts.second),
        DateField::Milliseconds => f64::from(parts.millisecond),
        DateField::Time | DateField::TimezoneOffset => unreachable!("handled above"),
    }
}

/// The instant a writer produces, or `None` for a write the specification does not perform.
///
/// The distinction is observable and there is a test for it: a setter that finds an invalid date
/// answers NaN *without storing anything*, so a `valueOf` on one of its arguments that moved this
/// same date keeps its effect. Storing the NaN would quietly undo it.
fn date_written(method: DateMethod, field: DateField, time: f64, supplied: &[f64]) -> Option<f64> {
    if matches!(field, DateField::Time) {
        return Some(time_clip(supplied.first().copied().unwrap_or(f64::NAN)));
    }
    // The year setters are the ones that *revive* an invalid date: the specification starts them
    // from the epoch rather than propagating the NaN, which is what makes
    // `new Date(NaN).setFullYear(2000)` a real date. Every other setter leaves it invalid.
    let revives = matches!(
        method,
        DateMethod::SetFullYear | DateMethod::SetUtcFullYear | DateMethod::SetYear
    );
    let parts = date_parts(if time.is_nan() && revives { 0.0 } else { time })?;
    // The order the fields appear in, so "this one and the ones after it" is a slice.
    let mut values = [
        parts.year as f64,
        f64::from(parts.month) - 1.0,
        f64::from(parts.day),
        f64::from(parts.hour),
        f64::from(parts.minute),
        f64::from(parts.second),
        f64::from(parts.millisecond),
    ];
    let first = match field {
        DateField::FullYear => 0,
        DateField::Month => 1,
        DateField::Day => 2,
        DateField::Hours => 3,
        DateField::Minutes => 4,
        DateField::Seconds => 5,
        DateField::Milliseconds => 6,
        DateField::Time | DateField::Weekday | DateField::TimezoneOffset => return Some(time),
    };
    for (offset, value) in supplied.iter().enumerate() {
        let Some(slot) = values.get_mut(first + offset) else {
            break;
        };
        *slot = *value;
    }
    // Annex B's `setYear` keeps the two-digit rule the constructor keeps: a year in 0..99 is
    // 19xx. `setFullYear` deliberately does not, which is the whole reason both exist.
    if matches!(method, DateMethod::SetYear) && (0.0..=99.0).contains(&values[0].trunc()) {
        values[0] = values[0].trunc() + 1900.0;
    }
    Some(time_clip(parts_to_instant(values)))
}

/// A year as a date string writes it: four digits at least, and a sign for a year before 1 CE.
fn year_string(year: i64) -> String {
    if year < 0 {
        format!("-{:04}", year.unsigned_abs())
    } else {
        format!("{year:04}")
    }
}

/// `toDateString`: the weekday and calendar date, `Thu Jan 01 1970`.
fn date_only_string(time: f64) -> String {
    const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let Some(parts) = date_parts(time) else {
        return "Invalid Date".to_owned();
    };
    format!(
        "{} {} {:02} {}",
        WEEKDAYS[parts.weekday as usize],
        MONTH_NAMES[(parts.month - 1) as usize],
        parts.day,
        year_string(parts.year)
    )
}

/// `toTimeString`: the clock and the zone, which is UTC here because the realm has no other.
fn time_only_string(time: f64) -> String {
    let Some(parts) = date_parts(time) else {
        return "Invalid Date".to_owned();
    };
    format!(
        "{:02}:{:02}:{:02} GMT+0000 (Coordinated Universal Time)",
        parts.hour, parts.minute, parts.second
    )
}

/// `toUTCString`: `Thu, 01 Jan 1970 00:00:00 GMT`, the form an HTTP date is written in.
///
/// A different shape from `toString`, not a different zone: the comma, the day before the month
/// and the bare `GMT` are what a header parser expects, and getting them wrong is the sort of
/// difference that only shows up on the wire.
fn utc_string(time: f64) -> String {
    const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let Some(parts) = date_parts(time) else {
        return "Invalid Date".to_owned();
    };
    format!(
        "{}, {:02} {} {} {:02}:{:02}:{:02} GMT",
        WEEKDAYS[parts.weekday as usize],
        parts.day,
        MONTH_NAMES[(parts.month - 1) as usize],
        year_string(parts.year),
        parts.hour,
        parts.minute,
        parts.second
    )
}

/// The three-letter month names every date string shares.
const MONTH_NAMES: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

/// The parts of an instant, all in UTC -- see ADR 0015 for why the realm has no other zone.
struct DateParts {
    year: i64,
    month: u32,
    day: u32,
    weekday: u32,
    hour: u32,
    minute: u32,
    second: u32,
    millisecond: u32,
}

fn date_parts(time: f64) -> Option<DateParts> {
    if !time.is_finite() {
        return None;
    }
    let millis = time as i64;
    // Floor division, not truncation: an instant before the epoch is a negative count and must
    // round *down* to the day containing it.
    let days = millis.div_euclid(86_400_000);
    let within = millis.rem_euclid(86_400_000);
    let (year, month, day) = civil_from_days(days);
    Some(DateParts {
        year,
        month,
        day,
        // 1970-01-01 was a Thursday, which is day 4.
        weekday: (days + 4).rem_euclid(7) as u32,
        hour: (within / 3_600_000) as u32,
        minute: (within / 60_000 % 60) as u32,
        second: (within / 1000 % 60) as u32,
        millisecond: (within % 1000) as u32,
    })
}

/// The instant a set of UTC parts names, with every part allowed out of range.
///
/// Out-of-range parts roll over rather than clamping: `setMonth(12)` is January of the next year
/// and `setDate(0)` is the last day of the previous month. That falls out of normalising the
/// month into a year offset and then counting in whole units, and it is what the specification
/// says -- clamping would quietly produce a different date than the program asked for.
fn parts_to_instant(parts: [f64; 7]) -> f64 {
    if parts.iter().any(|part| !part.is_finite()) {
        return f64::NAN;
    }
    // `MakeDay` and `MakeTime` truncate every field toward zero before any arithmetic runs,
    // which is what makes `setHours(1.9)` one o'clock exactly rather than something between.
    let [year, months, day, hour, minute, second, millisecond] = parts.map(f64::trunc);
    let year = year + (months / 12.0).floor();
    let month = months.rem_euclid(12.0);
    // Beyond what a civil date can name; the calendar arithmetic below would overflow.
    if year.abs() > 400_000.0 {
        return f64::NAN;
    }
    let days = days_from_civil(year as i64, month as i64 + 1, 1) as f64 + (day - 1.0);
    // Doubles, and summed in the specification's own grouping. That reads like a detail and is
    // not: these are IEEE-754 additions, so the same terms accumulated in another order round
    // differently, and a day count large enough to matter is reachable from `Date.UTC`.
    let clock = ((hour * 3_600_000.0 + minute * 60_000.0) + second * 1000.0) + millisecond;
    days * 86_400_000.0 + clock
}

/// `toISOString`, or `None` for an instant that has no ISO spelling.
fn iso_string(time: f64) -> Option<String> {
    let parts = date_parts(time)?;
    // A year outside four digits is written with a sign and six, which is the only shape that
    // stays unambiguous.
    let year = if (0..=9999).contains(&parts.year) {
        format!("{:04}", parts.year)
    } else {
        format!(
            "{}{:06}",
            if parts.year < 0 { '-' } else { '+' },
            parts.year.abs()
        )
    };
    Some(format!(
        "{year}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
        parts.month, parts.day, parts.hour, parts.minute, parts.second, parts.millisecond
    ))
}

/// `String(date)`: the human form, which is UTC here because the realm has no other zone.
///
/// Assembled from the two halves rather than formatted again, because the language publishes
/// those halves as `toDateString` and `toTimeString` and the three must agree character for
/// character -- a program that concatenates the pair gets exactly this string.
fn date_to_string(time: f64) -> String {
    if date_parts(time).is_none() {
        return "Invalid Date".to_owned();
    }
    format!("{} {}", date_only_string(time), time_only_string(time))
}

/// The instant named by `(year, month, day, hours, minutes, seconds, milliseconds)`.
///
/// Out-of-range fields roll over rather than failing -- month 13 is January of the next year --
/// which is why the arithmetic is done in milliseconds rather than validated field by field.
fn date_from_fields(arguments: &[Value]) -> f64 {
    let field = |index: usize, default: f64| -> f64 {
        arguments.get(index).map_or(default, Value::as_number)
    };
    let year = field(0, f64::NAN);
    if !year.is_finite() {
        return f64::NAN;
    }
    // A two-digit year means 19xx, which is the one piece of legacy the constructor keeps -- and
    // the test is on the *truncated* year, so `Date.UTC(-0.999999)` is 1900 and not year zero.
    let year = if (0.0..=99.0).contains(&year.trunc()) {
        year.trunc() + 1900.0
    } else {
        year
    };
    parts_to_instant([
        year,
        field(1, 0.0),
        field(2, 1.0),
        field(3, 0.0),
        field(4, 0.0),
        field(5, 0.0),
        field(6, 0.0),
    ])
}

/// Parse the forms `Date.parse` and the string constructor accept.
///
/// Deliberately narrow: the specification also allows an implementation-defined set of other
/// formats, and guessing at one silently turns a typo into a date. The two non-ISO spellings
/// here are not guesses -- they are what this engine's own `toString` and `toUTCString` emit,
/// and the specification requires `Date.parse` to round-trip both.
fn parse_date(text: &str) -> f64 {
    let text = text.trim();
    match iso_date(text).or_else(|| legacy_date(text)) {
        Some(time) => time_clip(time),
        None => f64::NAN,
    }
}

/// The Date Time String Format: `YYYY-MM-DDTHH:mm:ss.sssZ` and every prefix of it the
/// specification allows, with the extended six-digit year and an explicit UTC offset.
fn iso_date(text: &str) -> Option<f64> {
    let bytes = text.as_bytes();
    // A fixed-width run of digits, or nothing. Written out because `parse` would accept a sign
    // or a shorter field, and both would let a malformed string name a date.
    let digits = |at: usize, count: usize| -> Option<i64> {
        let slice = text.get(at..at.checked_add(count)?)?;
        slice
            .bytes()
            .all(|byte| byte.is_ascii_digit())
            .then_some(())?;
        slice.parse().ok()
    };
    let (year, mut at) = match bytes.first() {
        Some(sign @ (b'+' | b'-')) => {
            let magnitude = digits(1, 6)?;
            // `-000000` is not a spelling of year zero: the specification refuses it outright so
            // that one year cannot be written two ways.
            if *sign == b'-' && magnitude == 0 {
                return None;
            }
            (if *sign == b'-' { -magnitude } else { magnitude }, 7)
        }
        _ => (digits(0, 4)?, 4),
    };
    let (mut month, mut day) = (1, 1);
    if bytes.get(at) == Some(&b'-') {
        month = digits(at + 1, 2)?;
        at += 3;
        if bytes.get(at) == Some(&b'-') {
            day = digits(at + 1, 2)?;
            at += 3;
        }
    }
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let date = days_from_civil(year, month, day) as f64 * 86_400_000.0;
    if at == bytes.len() {
        // A date with no time is UTC midnight, where a date *with* one is local time. The two
        // are the same instant in this realm and are still two rules -- ADR 0015.
        return Some(date);
    }
    if bytes.get(at) != Some(&b'T') {
        return None;
    }
    let hour = digits(at + 1, 2)?;
    if bytes.get(at + 3) != Some(&b':') {
        return None;
    }
    let minute = digits(at + 4, 2)?;
    at += 6;
    let (mut second, mut fraction) = (0, 0);
    if bytes.get(at) == Some(&b':') {
        second = digits(at + 1, 2)?;
        at += 3;
        if bytes.get(at) == Some(&b'.') {
            fraction = digits(at + 1, 3)?;
            at += 4;
        }
    }
    if hour > 24 || minute > 59 || second > 59 {
        return None;
    }
    // `24:00` names the midnight that ends the day, and nothing at all past it.
    if hour == 24 && (minute != 0 || second != 0 || fraction != 0) {
        return None;
    }
    let clock = (hour * 3_600_000 + minute * 60_000 + second * 1000 + fraction) as f64;
    match bytes.get(at) {
        // No offset means local time, which is UTC here.
        None => Some(date + clock),
        Some(b'Z') if at + 1 == bytes.len() => Some(date + clock),
        Some(sign @ (b'+' | b'-')) => {
            let offset_hour = digits(at + 1, 2)?;
            if bytes.get(at + 3) != Some(&b':') {
                return None;
            }
            let offset_minute = digits(at + 4, 2)?;
            if at + 6 != bytes.len() || offset_hour > 23 || offset_minute > 59 {
                return None;
            }
            let offset = (offset_hour * 3_600_000 + offset_minute * 60_000) as f64;
            // An offset says what the clock read *there*, so reaching UTC subtracts it.
            Some(if *sign == b'-' {
                date + clock + offset
            } else {
                date + clock - offset
            })
        }
        _ => None,
    }
}

/// The two human forms this engine emits: `Thu Jan 01 1970 00:00:00 GMT+0000 (...)` from
/// `toString`, and `Thu, 01 Jan 1970 00:00:00 GMT` from `toUTCString`.
///
/// Here because the specification requires `Date.parse(d.toString())` to name the same instant
/// as `d` -- a round-trip programs rely on, and one an ISO-only parser cannot make.
fn legacy_date(text: &str) -> Option<f64> {
    let mut fields = text.split_whitespace();
    let first = fields.next()?;
    // The comma after the weekday is what tells the two forms apart, and it is also what says
    // which of the next two fields is the month.
    let (month, day) = if first.ends_with(',') {
        let day = fields.next()?;
        (fields.next()?, day)
    } else {
        let month = fields.next()?;
        (month, fields.next()?)
    };
    let month = 1 + MONTH_NAMES.iter().position(|name| *name == month)? as i64;
    let day = day.parse::<i64>().ok()?;
    let year = fields.next()?.parse::<i64>().ok()?;
    if !(1..=31).contains(&day) {
        return None;
    }
    let date = days_from_civil(year, month, day) as f64 * 86_400_000.0;
    // `toDateString` stops here, and its output is a date the specification does not require to
    // round-trip -- but reading it as midnight is what every engine does and costs nothing.
    let Some(clock) = fields.next() else {
        return Some(date);
    };
    let mut clock = clock.split(':');
    let hour = clock.next()?.parse::<i64>().ok()?;
    let minute = clock.next()?.parse::<i64>().ok()?;
    let second = clock.next()?.parse::<i64>().ok()?;
    if clock.next().is_some() || hour > 23 || minute > 59 || second > 59 {
        return None;
    }
    let clock = (hour * 3_600_000 + minute * 60_000 + second * 1000) as f64;
    let zone = fields.next()?;
    let offset = match zone.strip_prefix("GMT") {
        Some("") => 0.0,
        Some(rest) => {
            let (sign, digits) = rest.split_at(1);
            if digits.len() != 4 || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
                return None;
            }
            let magnitude = (digits[..2].parse::<i64>().ok()? * 3_600_000
                + digits[2..].parse::<i64>().ok()? * 60_000) as f64;
            match sign {
                "+" => -magnitude,
                "-" => magnitude,
                _ => return None,
            }
        }
        None => return None,
    };
    Some(date + clock + offset)
}

/// Whether a value can be called.
/// Whether the iterator protocol will accept this value where it requires an object.
///
/// Asked of a receiver, of a `next` result and of whatever a `flatMap` mapper answered. Getting
/// it wrong in either direction is a silent bug: a primitive accepted as an iterator reads
/// `done` as `undefined` and then loops forever.
fn is_iterator_object(value: &Value) -> bool {
    matches!(
        value,
        Value::Object(_)
            | Value::Array(_)
            | Value::Function(_)
            | Value::Generator(_)
            | Value::Proxy(_)
            | Value::TypedArray(_)
            | Value::DataView(_)
            | Value::ArrayBuffer(_)
            | Value::Date(_)
            | Value::RegExp(_)
            | Value::Promise(_)
            | Value::Bound(_)
            | Value::Native(_, _)
            | Value::Callback(_, _)
    )
}

/// Whether reading or writing `name` on `target` reaches the restricted pair.
///
/// `caller` and `arguments` live on `%Function.prototype%` and nowhere else, so this is exactly
/// "is `target` something that inherits from it" -- which is "is it callable", asked the way the
/// arity table asks it: a namespace like `Math` is a `Native` too and is not a function.
fn is_restricted_function_property(target: &Value, name: &str) -> bool {
    matches!(name, "caller" | "arguments") && function_identity(target).is_some()
}

/// What `%ThrowTypeError%` throws, for the paths that reach the pair without calling it.
fn restricted_property_error() -> ExecutionError {
    ExecutionError::TypeErrorMessage {
        message: "'caller', 'callee', and 'arguments' properties may not be accessed on strict \
                  mode functions or the arguments objects for calls to them"
            .to_owned(),
    }
}

/// Whether argument `index` of `native` is one the specification converts with `ToString`.
///
/// Spelled out per method because it is not uniform: `concat` converts every argument, `split`
/// converts the separator but not the limit beside it, and `replace` converts the search value
/// but must leave a replacement function alone for the call that follows.
fn string_coerced_argument(native: Native, index: usize) -> bool {
    match native {
        Native::StringConcat => true,
        Native::StringSplit
        | Native::StringIndexOf
        | Native::StringLastIndexOf
        | Native::StringIncludes
        | Native::StringStartsWith
        | Native::StringEndsWith => index == 0,
        Native::StringReplace | Native::StringReplaceAll => index <= 1,
        Native::StringPadStart | Native::StringPadEnd => index == 1,
        _ => false,
    }
}

/// Callables whose receiver is ignored or whose own call object already owns the receiver.
///
/// Native and compiled functions are intentionally excluded: their receiver is observable and
/// each dispatch path must preserve its specialized fast path. This match is deliberately
/// exhaustive: adding a `Value` representation forces its call classification to be decided here.
fn forwards_to_call_value(value: &Value) -> bool {
    match value {
        Value::Settler(..)
        | Value::Capability(..)
        | Value::Element(_)
        | Value::Bound(_)
        | Value::Wrapped(_)
        | Value::CommonJsRequire(_)
        | Value::CommonJsResolve(_) => true,
        Value::Undefined
        | Value::Null
        | Value::Boolean(_)
        | Value::Number(_)
        | Value::String(_)
        | Value::Cell(_)
        | Value::Native(_, _)
        | Value::Generator(_)
        | Value::Promise(_)
        | Value::RegExp(_)
        | Value::Date(_)
        | Value::Temporal(_)
        | Value::Intl(_)
        | Value::BigInt(_)
        | Value::Array(_)
        | Value::Callback(_, _)
        | Value::TypedArray(_)
        | Value::ArrayBuffer(_)
        | Value::DataView(_)
        | Value::Proxy(_)
        | Value::Symbol(_)
        | Value::Object(_)
        | Value::Function(_) => false,
    }
}

pub(crate) fn is_callable(value: &Value) -> bool {
    match value {
        // A proxy has a `[[Call]]` method exactly when its target has one, decided when the
        // proxy is made and never after. Treating every proxy as callable meant
        // `new Proxy({}, {apply(){}})()` ran the trap where the language says the proxy is not
        // a function at all -- and `typeof` said so too. The target survives revocation, which
        // is what keeps a revoked function proxy a function.
        Value::Proxy(proxy) => is_callable(&proxy.target),
        other => {
            matches!(
                other,
                Value::Function(_) | Value::Native(_, _) | Value::Callback(_, _)
            ) || forwards_to_call_value(other)
        }
    }
}

/// One match: where it landed, and where each capture group did.
///
/// Every range is in UTF-16 units, which is what the language counts in and what the engine
/// reports when matching over UTF-16.
/// The third element is the pattern's *named* groups, in declaration order and already
/// de-duplicated by `regress`: the duplicate-named-groups proposal lets two alternatives share a
/// name, and only one of them can have participated.
type RegExpMatch = (
    std::ops::Range<usize>,
    Vec<Option<std::ops::Range<usize>>>,
    Vec<(String, Option<std::ops::Range<usize>>)>,
);

/// Where a literal needle occurs, in the shape a regexp match has, so replacement is one path.
fn literal_matches(subject: &[u16], needle: &[u16], all: bool) -> Vec<RegExpMatch> {
    let mut found = Vec::new();
    let mut at = 0;
    while at + needle.len() <= subject.len() {
        if subject[at..at + needle.len()] == *needle {
            let range = at..at + needle.len();
            // A literal needle has no groups at all, named or otherwise.
            found.push((range.clone(), vec![Some(range)], Vec::new()));
            if !all {
                break;
            }
            // An empty needle would never advance, so it steps one at a time.
            at = if needle.is_empty() {
                at + 1
            } else {
                at + needle.len()
            };
            continue;
        }
        at += 1;
    }
    found
}

/// Expand `$&`, `` $` ``, `$'`, `$1`..`$99` and `$$` in a replacement string.
/// The text one match expands to, with `$&`, `` $` ``, `$'`, `$$` and `$n` resolved.
///
/// Bounded: one `$1` costs the whole match, and a template carrying tens of thousands of them
/// against a megabyte-long match asks for a string in the tens of gigabytes -- from a single
/// call, before the caller ever sees a byte of it.
fn expand_replacement(
    template: &str,
    subject: &[u16],
    range: &std::ops::Range<usize>,
    groups: &[Option<std::ops::Range<usize>>],
    names: &[(String, Option<std::ops::Range<usize>>)],
) -> Result<String, ExecutionError> {
    let mut out = String::new();
    let characters: Vec<char> = template.chars().collect();
    let mut at = 0;
    while at < characters.len() {
        if characters[at] != '$' || at + 1 >= characters.len() {
            push_bounded_char(&mut out, characters[at])?;
            at += 1;
            continue;
        }
        match characters[at + 1] {
            '$' => {
                push_bounded_char(&mut out, '$')?;
                at += 2;
            }
            '&' => {
                push_bounded(&mut out, &utf16_slice(subject, range.clone()))?;
                at += 2;
            }
            '`' => {
                push_bounded(&mut out, &utf16_slice(subject, 0..range.start))?;
                at += 2;
            }
            '\'' => {
                push_bounded(&mut out, &utf16_slice(subject, range.end..subject.len()))?;
                at += 2;
            }
            first if first.is_ascii_digit() => {
                // Two digits are preferred when that names a group, which is why `$12` is group
                // twelve where there are twelve and group one followed by "2" where there are not.
                let two = characters
                    .get(at + 2)
                    .filter(|second| second.is_ascii_digit())
                    .and_then(|second| format!("{first}{second}").parse::<usize>().ok())
                    .filter(|index| *index > 0 && *index < groups.len());
                let (index, width) = match two {
                    Some(index) => (index, 3),
                    None => match first.to_digit(10).map(|digit| digit as usize) {
                        Some(index) if index > 0 && index < groups.len() => (index, 2),
                        // Not a group reference at all, so the text stands as written.
                        _ => {
                            push_bounded_char(&mut out, '$')?;
                            at += 1;
                            continue;
                        }
                    },
                };
                if let Some(Some(group)) = groups.get(index) {
                    push_bounded(&mut out, &utf16_slice(subject, group.clone()))?;
                }
                at += width;
            }
            // `$<name>` is a group reference only for a pattern that *has* named groups: in
            // one that does not, the specification leaves the text exactly as written, so
            // `"x".replace(/x/, "$<a>")` is the literal `$<a>` rather than an empty string.
            '<' if !names.is_empty() => {
                let Some(end) = characters[at + 2..].iter().position(|c| *c == '>') else {
                    push_bounded_char(&mut out, '$')?;
                    at += 1;
                    continue;
                };
                let name: String = characters[at + 2..at + 2 + end].iter().collect();
                // A name the pattern does not declare expands to nothing, like a group that did
                // not participate -- it is not an error, and not the literal text either.
                if let Some((_, Some(group))) = names.iter().find(|(key, _)| *key == name) {
                    push_bounded(&mut out, &utf16_slice(subject, group.clone()))?;
                }
                at += 3 + end;
            }
            _ => {
                push_bounded_char(&mut out, '$')?;
                at += 1;
            }
        }
    }
    Ok(out)
}

/// Every match of a global pattern, from the start of the subject.
///
/// An empty match advances the cursor by one, or a pattern that can match nothing -- `/a*/g` --
/// would never finish.
fn regexp_search_all(regexp: &RegExpData, subject: &[u16]) -> Vec<RegExpMatch> {
    let mut found = Vec::new();
    let mut at = 0;
    while at <= subject.len() {
        let Some((range, groups, names)) = regexp_search(regexp, subject, at) else {
            break;
        };
        at = if range.end == range.start {
            range.end + 1
        } else {
            range.end
        };
        found.push((range, groups, names));
    }
    found
}

/// A capture range as the two-element array `indices` reports it, or `undefined`.
fn indices_pair(group: Option<&std::ops::Range<usize>>) -> Value {
    match group {
        Some(range) => Value::Array(ArrayData::new(vec![
            Value::Number(range.start as f64),
            Value::Number(range.end as f64),
        ])),
        None => Value::Undefined,
    }
}

/// The object `result.groups` and `result.indices.groups` are: one key per *name*, in declaration
/// order, and no prototype.
///
/// No prototype because the specification says `OrdinaryObjectCreate(null)`, and it is visible:
/// a pattern with a group called `toString` would otherwise inherit one, and
/// `result.groups.__proto__` would answer `Object.prototype` where a program checking for a
/// group of that name expects `undefined`.
fn named_group_object(
    names: &[(String, Option<std::ops::Range<usize>>)],
    value: impl Fn(Option<&std::ops::Range<usize>>) -> Value,
) -> Value {
    let mut object = ObjectData::default();
    object.set_prototype(Value::Null);
    for (name, range) in names {
        object.set(name, value(range.as_ref()));
    }
    Value::Object(Rc::new(RefCell::new(object)))
}

/// The array `exec` and `match` produce: the whole match, then each group, with `index` and
/// `input` alongside.
fn match_result(
    subject: &[u16],
    range: &std::ops::Range<usize>,
    groups: &[Option<std::ops::Range<usize>>],
    names: &[(String, Option<std::ops::Range<usize>>)],
    has_indices: bool,
) -> Value {
    let mut items = vec![Value::String(StringUnits::from_units(
        &subject[range.clone()],
    ))];
    // The first group `regress` reports is the whole match, which is already element zero.
    for group in groups.iter().skip(1) {
        items.push(match group {
            // Sliced as units: the match text keeps lone surrogates rather than replacing
            // them on the way into the result array.
            Some(range) => Value::String(StringUnits::from_units(&subject[range.clone()])),
            // A group that did not participate is undefined rather than empty.
            None => Value::Undefined,
        });
    }
    // `index` and `input` are properties *of the array*, which is why an array needs somewhere
    // to keep a property that is not an element.
    let result = ArrayData::new(items);
    result
        .properties
        .borrow_mut()
        .set("index", Value::Number(range.start as f64));
    result.properties.borrow_mut().set(
        "input",
        Value::String(StringUnits::from_units(&subject[0..subject.len()])),
    );
    // Present and undefined rather than absent when the pattern has no named groups: a program
    // reads `m.groups?.name`, and node shows the key. With names, it is a real object -- reading
    // `m.groups.year` off `undefined` was a TypeError from ordinary, widely written code.
    let named = if names.is_empty() {
        Value::Undefined
    } else {
        named_group_object(names, |group| match group {
            Some(range) => Value::String(StringUnits::from_units(&subject[range.clone()])),
            None => Value::Undefined,
        })
    };
    result.properties.borrow_mut().set("groups", named);
    // `indices` is the `d` flag's whole observable effect: the same shape as the result itself,
    // holding `[start, end]` pairs instead of text, and carrying a `groups` of its own.
    if has_indices {
        let mut pairs = vec![indices_pair(Some(range))];
        for group in groups.iter().skip(1) {
            pairs.push(indices_pair(group.as_ref()));
        }
        let indices = ArrayData::new(pairs);
        let named = if names.is_empty() {
            Value::Undefined
        } else {
            named_group_object(names, indices_pair)
        };
        indices.properties.borrow_mut().set("groups", named);
        result
            .properties
            .borrow_mut()
            .set("indices", Value::Array(indices));
    }
    Value::Array(result)
}

/// The text of a UTF-16 range, as a JavaScript string.
fn utf16_slice(subject: &[u16], range: std::ops::Range<usize>) -> String {
    String::from_utf16_lossy(&subject[range])
}

/// Iterates code points while retaining an unpaired surrogate as its original one-unit string.
fn string_code_point_units(text: &StringUnits) -> Vec<StringUnits> {
    let units: Vec<u16> = text.units().collect();
    let mut out = Vec::with_capacity(units.len());
    let mut at = 0;
    while at < units.len() {
        let end = if (0xd800..=0xdbff).contains(&units[at])
            && units
                .get(at + 1)
                .is_some_and(|unit| (0xdc00..=0xdfff).contains(unit))
        {
            at + 2
        } else {
            at + 1
        };
        out.push(StringUnits::from_units(&units[at..end]));
        at = end;
    }
    out
}

fn value_to_string_units(value: &Value) -> Result<Vec<u16>, ExecutionError> {
    match value {
        Value::String(text) => Ok(text.units().collect()),
        other => Ok(other.to_string_units_checked()?.units().collect()),
    }
}

fn string_case_map(text: &StringUnits, upper: bool) -> StringUnits {
    let units: Vec<u16> = text.units().collect();
    if let Ok(scalar) = String::from_utf16(&units) {
        return StringUnits::from(if upper {
            scalar.to_uppercase()
        } else {
            scalar.to_lowercase()
        });
    }
    let mut out = Vec::with_capacity(units.len());
    let mut segment = String::new();
    for decoded in char::decode_utf16(units.iter().copied()) {
        match decoded {
            Ok(character) => segment.push(character),
            Err(error) => {
                let mapped = if upper {
                    segment.to_uppercase()
                } else {
                    segment.to_lowercase()
                };
                out.extend(mapped.encode_utf16());
                segment.clear();
                out.push(error.unpaired_surrogate());
            }
        }
    }
    let mapped = if upper {
        segment.to_uppercase()
    } else {
        segment.to_lowercase()
    };
    out.extend(mapped.encode_utf16());
    StringUnits::from_units(&out)
}

fn string_trim_units(text: &StringUnits, trim_start: bool, trim_end: bool) -> StringUnits {
    let units: Vec<u16> = text.units().collect();
    let mut start = 0;
    let mut end = units.len();
    if trim_start {
        let mut offset = 0;
        for decoded in char::decode_utf16(units.iter().copied()) {
            match decoded {
                Ok(character) if is_js_whitespace(character) => offset += character.len_utf16(),
                _ => break,
            }
        }
        start = offset;
    }
    if trim_end {
        let mut offset = 0;
        for decoded in char::decode_utf16(units.iter().copied()) {
            let length = match &decoded {
                Ok(character) => character.len_utf16(),
                Err(_) => 1,
            };
            match decoded {
                Ok(character) if is_js_whitespace(character) => {}
                Ok(character) => end = offset + character.len_utf16(),
                Err(_) => end = offset + 1,
            }
            offset += length;
        }
    }
    StringUnits::from_units(&units[start.min(end)..end])
}

/// The methods on `RegExp.prototype`, without the per-instance data a regexp also answers to.
///
/// A program reaches for these to call one against a receiver of its own -- `RegExp.prototype
/// .test.call(re, s)` is how a library avoids a monkey-patched `test`.
fn regexp_method(name: &str) -> Value {
    match name {
        "test" => Value::Native(Native::RegExpTest, RealmId::PRIMARY),
        "exec" => Value::Native(Native::RegExpExec, RealmId::PRIMARY),
        "toString" => Value::Native(Native::RegExpToString, RealmId::PRIMARY),
        // What the accessors answer *for the table itself*. `RegExp.prototype` has no pattern
        // and no flags, and the specification gives these two an answer anyway rather than
        // throwing: the empty flag set, and the pattern that matches the empty string.
        "source" => Value::String("(?:)".to_owned().into()),
        "flags" => Value::String(String::new().into()),
        key => match RegExpSymbol::named(key) {
            Some(method) => Value::Native(Native::RegExpSymbol(method), RealmId::PRIMARY),
            None => Value::Undefined,
        },
    }
}

/// The methods on `Date.prototype`, for the same reason.
///
/// Every name resolves to its own marker even where two of them do the same arithmetic: a realm
/// whose only zone is UTC (ADR 0015) makes `getMonth` and `getUTCMonth` answer the same number,
/// and they are still two functions a program can hold apart, rename, or delete one of.
fn date_method(name: &str) -> Value {
    let method = match name {
        "valueOf" => DateMethod::ValueOf,
        "getTime" => DateMethod::GetTime,
        "getFullYear" => DateMethod::GetFullYear,
        "getUTCFullYear" => DateMethod::GetUtcFullYear,
        "getMonth" => DateMethod::GetMonth,
        "getUTCMonth" => DateMethod::GetUtcMonth,
        "getDate" => DateMethod::GetDate,
        "getUTCDate" => DateMethod::GetUtcDate,
        "getDay" => DateMethod::GetDay,
        "getUTCDay" => DateMethod::GetUtcDay,
        "getHours" => DateMethod::GetHours,
        "getUTCHours" => DateMethod::GetUtcHours,
        "getMinutes" => DateMethod::GetMinutes,
        "getUTCMinutes" => DateMethod::GetUtcMinutes,
        "getSeconds" => DateMethod::GetSeconds,
        "getUTCSeconds" => DateMethod::GetUtcSeconds,
        "getMilliseconds" => DateMethod::GetMilliseconds,
        "getUTCMilliseconds" => DateMethod::GetUtcMilliseconds,
        "getTimezoneOffset" => DateMethod::GetTimezoneOffset,
        "getYear" => DateMethod::GetYear,
        "setTime" => DateMethod::SetTime,
        "setFullYear" => DateMethod::SetFullYear,
        "setUTCFullYear" => DateMethod::SetUtcFullYear,
        "setMonth" => DateMethod::SetMonth,
        "setUTCMonth" => DateMethod::SetUtcMonth,
        "setDate" => DateMethod::SetDate,
        "setUTCDate" => DateMethod::SetUtcDate,
        "setHours" => DateMethod::SetHours,
        "setUTCHours" => DateMethod::SetUtcHours,
        "setMinutes" => DateMethod::SetMinutes,
        "setUTCMinutes" => DateMethod::SetUtcMinutes,
        "setSeconds" => DateMethod::SetSeconds,
        "setUTCSeconds" => DateMethod::SetUtcSeconds,
        "setMilliseconds" => DateMethod::SetMilliseconds,
        "setUTCMilliseconds" => DateMethod::SetUtcMilliseconds,
        "setYear" => DateMethod::SetYear,
        "toISOString" => DateMethod::ToIsoString,
        // Not the same function as `toISOString`, and the difference is exactly the case JSON
        // cares about: an instant with no ISO spelling makes `toISOString` throw, where `toJSON`
        // answers null so the enclosing document still serialises.
        "toJSON" => DateMethod::ToJson,
        "toString" => DateMethod::ToString,
        "toDateString" => DateMethod::ToDateString,
        "toTimeString" => DateMethod::ToTimeString,
        // Annex B publishes `toUTCString` a second time under the name the language shipped
        // with, and as the *same* function object -- `Date.prototype.toGMTString ===
        // Date.prototype.toUTCString` is true, and a second marker would make it false.
        "toUTCString" | "toGMTString" => DateMethod::ToUtcString,
        // The realm has one locale and one zone, so these three answer what their non-locale
        // counterparts answer. The specification leaves the form implementation-defined; what it
        // does not leave open is that they are three separate functions, which they are here.
        // ECMA-402 replaces these three with `Intl.DateTimeFormat`, each with its own
        // required/defaults pair, so they leave the `Date` dispatch table entirely.
        "toLocaleString" => {
            return Value::Native(
                Native::Intl(intl::Op::Adapter(intl::Adapter::DateToLocaleString)),
                RealmId::PRIMARY,
            );
        }
        "toLocaleDateString" => {
            return Value::Native(
                Native::Intl(intl::Op::Adapter(intl::Adapter::DateToLocaleDateString)),
                RealmId::PRIMARY,
            );
        }
        "toLocaleTimeString" => {
            return Value::Native(
                Native::Intl(intl::Op::Adapter(intl::Adapter::DateToLocaleTimeString)),
                RealmId::PRIMARY,
            );
        }
        key if key == WellKnown::ToPrimitive.property_key() => DateMethod::ToPrimitive,
        _ => return Value::Undefined,
    };
    Value::Native(Native::Date(method), RealmId::PRIMARY)
}

/// The methods on `%TypedArray%.prototype`.
///
/// Everything a view answers to that is not per-instance data, so the table and an instance
/// cannot disagree about which method a name resolves to. Most of them are the ordinary array
/// methods -- the specification defines its own copies, but they read `length` and indices and
/// so behave identically here -- with the ones that *change* a length left out, because a view's
/// length is not something a method may change: `push` on a typed array is a TypeError, and
/// answering with the array one would silently push into a copy.
fn typed_array_method(name: &str) -> Value {
    match name {
        "set" => Value::Native(Native::TypedArraySet, RealmId::PRIMARY),
        "subarray" => Value::Native(Native::TypedArraySubarray, RealmId::PRIMARY),
        "fill" => Value::Native(Native::TypedArrayFill, RealmId::PRIMARY),
        // The one member of the table the specification says *is* the `Array.prototype`
        // function rather than a distinct one: "the initial value of the
        // %TypedArray%.prototype.toString data property is the same built-in function object as
        // the Array.prototype.toString method". Branding it would fail the identity that
        // sentence describes; the detached check it needs it already gets, because the value it
        // hands out is `ArrayJoinDefault` and that is named in the validation list below.
        "toString" => array_property("toString"),
        // `%TypedArray%.prototype[@@iterator]` is not merely *like* `values`; it is the same
        // function object, so it resolves to the same marker rather than to one of its own.
        key if key == WellKnown::Iterator.property_key() => {
            Value::Native(Native::TypedArrayGeneric("values"), RealmId::PRIMARY)
        }
        other => match typed_array_generic(other) {
            Some(method) => Value::Native(Native::TypedArrayGeneric(method), RealmId::PRIMARY),
            None => Value::Undefined,
        },
    }
}

/// The `%TypedArray%.prototype` methods that share an `Array.prototype` implementation, spelled
/// out rather than filtered out of `Array.prototype`.
///
/// Filtering was how this table used to be built -- everything an array answers to, less the
/// methods that change a length -- and it let three names through that a view does not have:
/// `concat`, `flat` and `flatMap` are `Array.prototype`'s alone, and node answers `undefined`
/// for each of them on a view. A program feature-detects on exactly that, so answering with a
/// working function was a wrong answer rather than a bonus. The C backend already listed its
/// members outright and so already agreed with node; this is the interpreter catching up.
const TYPED_ARRAY_GENERIC_METHODS: [&str; 28] = [
    "at",
    "copyWithin",
    "entries",
    "every",
    "filter",
    "find",
    "findIndex",
    "findLast",
    "findLastIndex",
    "forEach",
    "includes",
    "indexOf",
    "join",
    "keys",
    "lastIndexOf",
    "map",
    "parallelMap",
    "reduce",
    "reduceRight",
    "reverse",
    "slice",
    "some",
    "sort",
    "toLocaleString",
    "toReversed",
    "toSorted",
    "values",
    "with",
    // `toString` is answered above, as `Array.prototype.toString` itself.
];

/// The static spelling of one of those names, which is what a marker can carry.
fn typed_array_generic(name: &str) -> Option<&'static str> {
    TYPED_ARRAY_GENERIC_METHODS
        .into_iter()
        .find(|method| *method == name)
}

/// The methods on `ArrayBuffer.prototype`, for the same reason.
///
/// `byteLength`, `resizable` and `maxByteLength` are deliberately not here: each is an accessor
/// that reads a *buffer*, and the method table is not one. A program feature-detects resizable
/// buffers by reading `ArrayBuffer.prototype.resize` off this table -- Test262's own harness
/// does exactly that before it builds a single resizable-buffer test -- so the table answering
/// `undefined` for everything is what made that whole area unreachable.
fn array_buffer_method(shared: bool, name: &str) -> Value {
    match name {
        // The one method each type has that the other does not, and the reason they cannot
        // share a table: a program feature-detects a growable shared buffer by reading
        // `SharedArrayBuffer.prototype.grow`, and finding `resize` there instead would tell it
        // the buffer shrinks.
        "resize" if !shared => Value::Native(Native::ArrayBufferResize, RealmId::PRIMARY),
        "grow" if shared => Value::Native(Native::ArrayBufferGrow, RealmId::PRIMARY),
        "slice" => Value::Native(Native::ArrayBufferSlice, RealmId::PRIMARY),
        // Only the unshared type: transferring is *giving the bytes away*, which is precisely
        // what a shared buffer's other holders have no way to survive.
        "transfer" if !shared => Value::Native(
            Native::ArrayBufferTransfer {
                preserve_resizability: true,
            },
            RealmId::PRIMARY,
        ),
        "transferToFixedLength" if !shared => Value::Native(
            Native::ArrayBufferTransfer {
                preserve_resizability: false,
            },
            RealmId::PRIMARY,
        ),
        // Giving the bytes away and freezing them in one step. Only the unshared type again,
        // and for the same reason: a shared buffer's other holders cannot survive the giving.
        "transferToImmutable" if !shared => {
            Value::Native(Native::ArrayBufferTransferToImmutable, RealmId::PRIMARY)
        }
        // The copying half of the pair: the source keeps its bytes and the result cannot change.
        "sliceToImmutable" if !shared => {
            Value::Native(Native::ArrayBufferSliceToImmutable, RealmId::PRIMARY)
        }
        key if key == WellKnown::ToStringTag.property_key() => Value::String(
            if shared {
                "SharedArrayBuffer"
            } else {
                "ArrayBuffer"
            }
            .to_owned()
            .into(),
        ),
        _ => Value::Undefined,
    }
}

/// What every iterator this realm makes inherits from `%IteratorPrototype%`.
///
/// The seven lazy helpers and the eight methods that consume an iterator, plus `@@dispose`.
/// `Iterator.concat`, `Iterator.zip` and `Iterator.zipKeyed` are absent, and are not on this
/// table anyway: they are statics on the constructor rather than methods on the prototype.
fn iterator_method(name: &str) -> Value {
    match name {
        // An iterator is its own iterable, and that is `%IteratorPrototype%`'s to say -- every
        // built-in iterator used to carry an own copy, which is one more own property than any
        // of them has.
        key if key == WellKnown::Iterator.property_key() => {
            Value::Native(Native::IteratorSelf, RealmId::PRIMARY)
        }
        "map" => Value::Native(Native::IteratorLazy(HelperKind::Map), RealmId::PRIMARY),
        "filter" => Value::Native(Native::IteratorLazy(HelperKind::Filter), RealmId::PRIMARY),
        "take" => Value::Native(Native::IteratorLazy(HelperKind::Take), RealmId::PRIMARY),
        "drop" => Value::Native(Native::IteratorLazy(HelperKind::Drop), RealmId::PRIMARY),
        "flatMap" => Value::Native(Native::IteratorLazy(HelperKind::FlatMap), RealmId::PRIMARY),
        "reduce" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Reduce),
            RealmId::PRIMARY,
        ),
        "toArray" => Value::Native(
            Native::IteratorTerminal(TerminalKind::ToArray),
            RealmId::PRIMARY,
        ),
        "forEach" => Value::Native(
            Native::IteratorTerminal(TerminalKind::ForEach),
            RealmId::PRIMARY,
        ),
        "some" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Some),
            RealmId::PRIMARY,
        ),
        "every" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Every),
            RealmId::PRIMARY,
        ),
        "find" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Find),
            RealmId::PRIMARY,
        ),
        "chunks" => Value::Native(Native::IteratorLazy(HelperKind::Chunks), RealmId::PRIMARY),
        "windows" => Value::Native(Native::IteratorLazy(HelperKind::Windows), RealmId::PRIMARY),
        "includes" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Includes),
            RealmId::PRIMARY,
        ),
        "join" => Value::Native(
            Native::IteratorTerminal(TerminalKind::Join),
            RealmId::PRIMARY,
        ),
        "constructor" => Value::Native(Native::IteratorConstructor, RealmId::PRIMARY),
        // An iterator is its own iterable, which is what lets one be handed straight to a
        // `for-of` or to `Array.from`.
        key if key == WellKnown::Iterator.property_key() => {
            Value::Native(Native::IteratorSelf, RealmId::PRIMARY)
        }
        // Closing an iterator is exactly what disposing of one means, so `using it = ...` ends
        // the iteration the same way an early `break` does.
        key if key == WellKnown::Dispose.property_key() => {
            Value::Native(Native::IteratorDispose, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

/// What a `DataView` inherits from `DataView.prototype`.
///
/// The `Float16` pair is absent rather than approximated: half precision is not one of the
/// element types this engine's buffers know how to read, and a `getFloat16` that answered a
/// `Float32` decode of the same bytes would be a wrong answer no program could see coming.
fn data_view_method(name: &str) -> Value {
    match name {
        "getInt8" => Value::Native(Native::DataViewGet(TypedKind::Int8), RealmId::PRIMARY),
        "getUint8" => Value::Native(Native::DataViewGet(TypedKind::Uint8), RealmId::PRIMARY),
        "getInt16" => Value::Native(Native::DataViewGet(TypedKind::Int16), RealmId::PRIMARY),
        "getUint16" => Value::Native(Native::DataViewGet(TypedKind::Uint16), RealmId::PRIMARY),
        "getInt32" => Value::Native(Native::DataViewGet(TypedKind::Int32), RealmId::PRIMARY),
        "getUint32" => Value::Native(Native::DataViewGet(TypedKind::Uint32), RealmId::PRIMARY),
        "getFloat16" => Value::Native(Native::DataViewGet(TypedKind::Float16), RealmId::PRIMARY),
        "getFloat32" => Value::Native(Native::DataViewGet(TypedKind::Float32), RealmId::PRIMARY),
        "getFloat64" => Value::Native(Native::DataViewGet(TypedKind::Float64), RealmId::PRIMARY),
        "setInt8" => Value::Native(Native::DataViewSet(TypedKind::Int8), RealmId::PRIMARY),
        "setUint8" => Value::Native(Native::DataViewSet(TypedKind::Uint8), RealmId::PRIMARY),
        "setInt16" => Value::Native(Native::DataViewSet(TypedKind::Int16), RealmId::PRIMARY),
        "setUint16" => Value::Native(Native::DataViewSet(TypedKind::Uint16), RealmId::PRIMARY),
        "setInt32" => Value::Native(Native::DataViewSet(TypedKind::Int32), RealmId::PRIMARY),
        "setUint32" => Value::Native(Native::DataViewSet(TypedKind::Uint32), RealmId::PRIMARY),
        "setFloat16" => Value::Native(Native::DataViewSet(TypedKind::Float16), RealmId::PRIMARY),
        "setFloat32" => Value::Native(Native::DataViewSet(TypedKind::Float32), RealmId::PRIMARY),
        "setFloat64" => Value::Native(Native::DataViewSet(TypedKind::Float64), RealmId::PRIMARY),
        "getBigInt64" => Value::Native(Native::DataViewGetBig { signed: true }, RealmId::PRIMARY),
        "getBigUint64" => Value::Native(Native::DataViewGetBig { signed: false }, RealmId::PRIMARY),
        "setBigInt64" => Value::Native(Native::DataViewSetBig { signed: true }, RealmId::PRIMARY),
        "setBigUint64" => Value::Native(Native::DataViewSetBig { signed: false }, RealmId::PRIMARY),
        key if key == WellKnown::ToStringTag.property_key() => {
            Value::String("DataView".to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// What every object inherits from `Object.prototype`.
///
/// `toString` and `valueOf` are deliberately absent from the *fallback* an ordinary object gets:
/// `ToPrimitive` looks for a `toString` and would start finding this one, changing what `"" + {}`
/// and every comparison against an object produce. They are reachable through
/// `Object.prototype.toString`, which is where programs actually use them.
fn object_method_value(method: kiln_builtin_surface::ObjectMethod, realm: RealmId) -> Value {
    match method {
        kiln_builtin_surface::ObjectMethod::HasOwnProperty => {
            Value::Native(Native::ObjectHasOwnProperty, realm)
        }
        kiln_builtin_surface::ObjectMethod::IsPrototypeOf => {
            Value::Native(Native::ObjectIsPrototypeOf, realm)
        }
        kiln_builtin_surface::ObjectMethod::PropertyIsEnumerable => {
            Value::Native(Native::ObjectPropertyIsEnumerable, realm)
        }
        kiln_builtin_surface::ObjectMethod::ToString => {
            Value::Native(Native::ObjectToStringTag, realm)
        }
        kiln_builtin_surface::ObjectMethod::ToLocaleString => {
            Value::Native(Native::ObjectToLocaleString, realm)
        }
        kiln_builtin_surface::ObjectMethod::ValueOf => Value::Native(Native::ObjectValueOf, realm),
        kiln_builtin_surface::ObjectMethod::DefineGetter => Value::Native(
            Native::LegacyAccessor {
                defines: true,
                setter: false,
            },
            realm,
        ),
        kiln_builtin_surface::ObjectMethod::DefineSetter => Value::Native(
            Native::LegacyAccessor {
                defines: true,
                setter: true,
            },
            realm,
        ),
        kiln_builtin_surface::ObjectMethod::LookupGetter => Value::Native(
            Native::LegacyAccessor {
                defines: false,
                setter: false,
            },
            realm,
        ),
        kiln_builtin_surface::ObjectMethod::LookupSetter => Value::Native(
            Native::LegacyAccessor {
                defines: false,
                setter: true,
            },
            realm,
        ),
    }
}

fn object_property(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::Object,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::ObjectMethod(method) => {
            object_method_value(method, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

/// What an ordinary object inherits from `Object.prototype`.
///
/// `toString` and `valueOf` are here now that `ToPrimitive` runs on the machine and tries them in
/// the specification's order: `String({})` finds `toString` and answers "[object Object]", and
/// `{} - 1` finds `valueOf`, gets the object back, and moves on to `toString`. While the
/// reduction was a pure function these two could not be here, because it would have found them
/// and had no way to call them.
fn inherited_object_property(intrinsics: &Intrinsics, name: &str, realm: RealmId) -> Value {
    table_step(
        intrinsics,
        PrototypeTable::Object,
        name,
        tabulated_object_property(name),
        realm,
    )
}

/// The same step with the realm's store left out: what `Object.prototype` was *built* with.
///
/// Kept apart from the read above because [`Native::property`] is the table itself -- the thing
/// the store is a difference against -- and a table that consulted the difference would answer
/// with it twice.
/// What a built-in publishes as its *own* member, or `None` if it has none by that name.
///
/// Deliberately not [`Native::property`], which is the *read* path: a prototype table's last step
/// is up to `Object.prototype`, so a read of `Array.prototype.valueOf` finds one, as it must.
/// Asking that question about ownership made every built-in prototype in the realm claim all
/// eleven of `Object.prototype`'s members as its own -- which `getOwnPropertyNames` denied in the
/// same breath, so the two answers depended on which one you asked.
///
/// A member is inherited exactly when the value found *is* the one `Object.prototype` supplies.
/// Comparing the values rather than asking whether the table's generic arm answered is what keeps
/// the tables whose members are published by earlier, more specific arms -- `EventEmitter` and the
/// two stream tables -- owning what they publish.
fn intrinsic_owns(native: Native, key: &str) -> Option<Value> {
    if matches!(native, Native::PrototypeOf(PrototypeTable::Array)) {
        if key == WellKnown::Unscopables.property_key() {
            return Some(Value::Null);
        }
        if key == "length" {
            return Some(Value::Number(0.0));
        }
    }
    let found = native.property(key)?;
    if matches!(found, Value::Undefined) {
        return None;
    }
    let Native::PrototypeOf(table) = native else {
        return Some(found);
    };
    // `Object.prototype` owns its own members; it is the table every other one inherits from.
    if matches!(table, PrototypeTable::Object) {
        return Some(found);
    }
    let inherited = tabulated_object_property(key);
    if !matches!(inherited, Value::Undefined) && strict_equal(&found, &inherited) {
        return None;
    }
    // The five iterator tables and the two generator ones take their step up to
    // `%IteratorPrototype%` inside their own answer, so what it supplies reaches them the same
    // way `Object.prototype`'s does -- and is inherited for the same reason.
    if matches!(
        table,
        PrototypeTable::IteratorFor(_) | PrototypeTable::Generator | PrototypeTable::AsyncGenerator
    ) {
        let from_iterator = iterator_method(key);
        if !matches!(from_iterator, Value::Undefined) && strict_equal(&found, &from_iterator) {
            return None;
        }
    }
    Some(found)
}

fn tabulated_object_property(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::Object,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::ObjectConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::ObjectMethod(method) => {
            object_method_value(method, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

/// Carry a method-table read its last step, up to `Object.prototype`.
///
/// Every built-in table but `Object.prototype`'s own sits *above* it in the chain, so a name the
/// table does not answer is still an ordinary object method. Without this step
/// `Array.prototype.hasOwnProperty` -- and, through it, every array and every collection --
/// reads as undefined, which is the shape the plain-object check every library ships depends on.
fn inherit_from_object(table: PrototypeTable, found: Value, name: &str) -> Value {
    match found {
        Value::Undefined if !matches!(table, PrototypeTable::Object) => {
            tabulated_object_property(name)
        }
        found => found,
    }
}

/// What `Boolean.prototype` answers, and what a boolean primitive finds through it.
fn boolean_method(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::Boolean,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::BooleanConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::BooleanMethod(
            kiln_builtin_surface::BooleanMethod::ToString,
        ) => Value::Native(Native::BooleanToString, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::BooleanMethod(
            kiln_builtin_surface::BooleanMethod::ValueOf,
        ) => Value::Native(Native::BooleanValueOf, RealmId::PRIMARY),
        _ => Value::Undefined,
    }
}

/// What `BigInt.prototype` answers.
fn bigint_method(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::BigInt,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::BigIntConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::BigIntMethod(
            kiln_builtin_surface::BigIntMethod::ToString
            | kiln_builtin_surface::BigIntMethod::ToLocaleString,
        ) => Value::Native(Native::BigIntToString, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::BigIntMethod(
            kiln_builtin_surface::BigIntMethod::ValueOf,
        ) => Value::Native(Native::PrimitiveValueOf, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::StringTag(tag) => {
            Value::String(tag.to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// What `Promise.prototype` answers, and what a promise finds through it.
fn promise_method(name: &str) -> Value {
    let Some(member) = kiln_builtin_surface::find_prototype_member(
        kiln_builtin_surface::PrototypeId::Promise,
        name,
    ) else {
        return Value::Undefined;
    };
    match member.binding {
        kiln_builtin_surface::SemanticBinding::Constructor => {
            Value::Native(Native::PromiseConstructor, RealmId::PRIMARY)
        }
        kiln_builtin_surface::SemanticBinding::PromiseMethod(
            kiln_builtin_surface::PromiseMethod::Then,
        ) => Value::Native(Native::PromiseThen, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::PromiseMethod(
            kiln_builtin_surface::PromiseMethod::Catch,
        ) => Value::Native(Native::PromiseCatch, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::PromiseMethod(
            kiln_builtin_surface::PromiseMethod::Finally,
        ) => Value::Native(Native::PromiseFinally, RealmId::PRIMARY),
        kiln_builtin_surface::SemanticBinding::StringTag(tag) => {
            Value::String(tag.to_owned().into())
        }
        _ => Value::Undefined,
    }
}

/// The object `new f()` gives instances, created on first use.
///
/// Created lazily so an ordinary function never used as a constructor never allocates one, and
/// carrying `constructor` back to the function -- which is what makes `x.constructor === C` true
/// and what a console reads to print `C {}` rather than `{}`. The two point at each other, so a
/// class that is never collected keeps its prototype alive; a realm's constructors outlive the
/// program anyway.
/// Which generator table a function's `prototype` object inherits from, or `None` for an
/// ordinary function whose `prototype` is an ordinary object.
/// What `%GeneratorPrototype%` and `%AsyncGeneratorPrototype%` answer.
///
/// The three methods are the same `Callback`s a generator value already resolves by name, so a
/// program that takes one off the prototype and calls it on a generator gets the same function
/// the generator hands back itself.
fn generator_prototype_method(asynchronous: bool, name: &str) -> Value {
    match name {
        "next" if asynchronous => {
            Value::Callback(CallbackMethod::AsyncGeneratorNext, RealmId::PRIMARY)
        }
        "return" if asynchronous => {
            Value::Callback(CallbackMethod::AsyncGeneratorReturn, RealmId::PRIMARY)
        }
        "throw" if asynchronous => {
            Value::Callback(CallbackMethod::AsyncGeneratorThrow, RealmId::PRIMARY)
        }
        "next" => Value::Callback(CallbackMethod::GeneratorNext, RealmId::PRIMARY),
        "return" => Value::Callback(CallbackMethod::GeneratorReturn, RealmId::PRIMARY),
        "throw" => Value::Callback(CallbackMethod::GeneratorThrow, RealmId::PRIMARY),
        key if key == WellKnown::ToStringTag.property_key() => Value::String(
            if asynchronous {
                "AsyncGenerator"
            } else {
                "Generator"
            }
            .to_owned()
            .into(),
        ),
        _ => Value::Undefined,
    }
}

fn generator_prototype_table(closure: &Rc<Closure>) -> Option<PrototypeTable> {
    let proto = closure.program.functions.get(closure.function as usize)?;
    if proto.async_generator {
        Some(PrototypeTable::AsyncGenerator)
    } else if proto.generator {
        Some(PrototypeTable::Generator)
    } else {
        None
    }
}

fn prototype_object(closure: &Rc<Closure>) -> Value {
    let mut slot = closure.prototype.borrow_mut();
    if let Some(existing) = slot.as_ref() {
        return existing.clone();
    }
    let mut data = ObjectData::default();
    // A generator function's `prototype` is not an ordinary one: it carries no `constructor` at
    // all, and it is the object its generators inherit from -- so it points at
    // `%GeneratorPrototype%` rather than at `Object.prototype`. That is the link the chain was
    // missing.
    match generator_prototype_table(closure) {
        Some(table) => {
            data.set_prototype(Value::Native(Native::PrototypeOf(table), RealmId::PRIMARY));
        }
        // Not enumerated: the link back is the realm's, so `Object.keys(C.prototype)` is empty
        // for a class that declared nothing and `for (const k in new C())` walks the fields
        // alone.
        None => data.set_non_enumerable("constructor", Value::Function(Rc::clone(closure))),
    }
    let prototype = Value::Object(Rc::new(RefCell::new(data)));
    *slot = Some(prototype.clone());
    prototype
}

/// The elements a typed array's constructor or `set` was given.
///
/// Left as values rather than flattened to numbers: whether an element is a Number or a BigInt
/// is what decides whether writing it through the destination is a conversion or a `TypeError`,
/// so collapsing the two here would decide that question in the wrong place.
fn typed_source(value: Option<&Value>) -> Vec<Value> {
    match value {
        Some(Value::Array(items)) => dense_items(&items.borrow()),
        Some(Value::TypedArray(view)) => view.items(),
        _ => Vec::new(),
    }
}

/// Refuse a copy between views whose elements are in different numeric towers.
///
/// Checked on the pair rather than element by element, because that is where the specification
/// checks it: `ToBigInt` is never reached for a typed-array source, so the refusal has to come
/// from the kinds themselves and has to hold for an empty source too.
fn same_content_type(kind: TypedKind, source: Option<&Value>) -> Result<(), ExecutionError> {
    if let Some(Value::TypedArray(view)) = source
        && view.kind.is_big() != kind.is_big()
    {
        return Err(ExecutionError::TypedArrayContentTypeMismatch);
    }
    Ok(())
}

/// `start` and `end` from a pair of possibly-negative, possibly-absent bounds.
fn slice_bounds(arguments: &[Value], length: usize) -> (usize, usize) {
    let resolve = |value: Option<&Value>, fallback: usize| -> usize {
        match value {
            None | Some(Value::Undefined) => fallback,
            Some(value) => {
                let at = value.as_number();
                if at.is_nan() {
                    return 0;
                }
                if !at.is_finite() {
                    return if at < 0.0 { 0 } else { length };
                }
                if at < 0.0 {
                    (length as f64 + at).max(0.0) as usize
                } else {
                    (at as usize).min(length)
                }
            }
        }
    };
    let start = resolve(arguments.first(), 0);
    let end = resolve(arguments.get(1), length);
    (start, end.max(start))
}

/// `new Uint8Array(...)` in each of its four shapes.
///
/// A length allocates; an array or another view copies; an `ArrayBuffer` *shares*, which is the
/// shape that makes two views over one buffer see each other's writes.
fn construct_typed_array(kind: TypedKind, arguments: &[Value]) -> Result<Value, ExecutionError> {
    let width = kind.width();
    Ok(match arguments.first() {
        Some(Value::ArrayBuffer(buffer)) => {
            // A view onto a buffer with no bytes is not an empty view but an impossible one:
            // the specification refuses it outright rather than handing back something that
            // reports length zero and could never report anything else.
            if buffer.detached() {
                return Err(ExecutionError::BufferDetached);
            }
            let total = buffer.byte_length();
            let offset = bounded_buffer(to_index(arguments.get(1))?, 1)?;
            if offset > total || offset % width != 0 {
                return Err(ExecutionError::InvalidArrayLength);
            }
            let length = match arguments.get(2) {
                // No explicit length over a *resizable* buffer is the specification's
                // length-tracking view: it has no count of its own, so a later resize moves its
                // end rather than leaving it addressing bytes that no longer exist. Over a
                // fixed buffer the two readings coincide, and the count is recorded because
                // nothing can ever change it.
                None | Some(Value::Undefined) => {
                    let remaining = total - offset;
                    // A length-tracking view has no count to be wrong: its end follows the
                    // buffer, and `length` is the floor of what fits. The exact-multiple rule
                    // belongs to a *fixed* buffer, where a leftover byte would mean a view
                    // addressing a partial element for ever. Applying it to both made
                    // `new Int32Array(new ArrayBuffer(10, { maxByteLength: 20 }))` a RangeError
                    // where every other engine answers a view of length two -- and a resizable
                    // buffer is normally sized in bytes, so a non-multiple is the ordinary case
                    // rather than the odd one.
                    if buffer.max_byte_length.is_some() {
                        None
                    } else {
                        if remaining % width != 0 {
                            return Err(ExecutionError::InvalidArrayLength);
                        }
                        Some(remaining / width)
                    }
                }
                Some(value) => {
                    let length = bounded_buffer(to_index(Some(value))?, width)?;
                    if length > (total - offset) / width {
                        return Err(ExecutionError::InvalidArrayLength);
                    }
                    Some(length)
                }
            };
            Value::TypedArray(Rc::new(TypedArrayData {
                kind,
                buffer: Rc::clone(buffer),
                offset,
                length,
                properties: RefCell::new(ObjectData::default()),
            }))
        }
        Some(Value::Array(_) | Value::TypedArray(_)) => {
            same_content_type(kind, arguments.first())?;
            let items = typed_source(arguments.first());
            let view = TypedArrayData {
                kind,
                buffer: BufferData::fixed(bounded_buffer(items.len() as f64, width)? * width),
                offset: 0,
                length: Some(items.len()),
                properties: RefCell::new(ObjectData::default()),
            };
            for (index, item) in items.into_iter().enumerate() {
                view.set(index, &item)?;
            }
            Value::TypedArray(Rc::new(view))
        }
        other => {
            let length = bounded_buffer(to_index(other)?, width)?;
            Value::TypedArray(Rc::new(TypedArrayData {
                kind,
                buffer: BufferData::fixed(length * width),
                offset: 0,
                length: Some(length),
                properties: RefCell::new(ObjectData::default()),
            }))
        }
    })
}
/// `StringToBigInt`, which is `StringNumericLiteral` without the decimal forms.
///
/// The prefixed radices count -- `0x`, `0o`, `0b`, in either case -- and were the whole of what
/// was missing: `BigInt("0x10")` is 16, and parsing the trimmed text as decimal refused it. A
/// sign is allowed only on the decimal form, which is why `-0x10` is still a SyntaxError, and
/// the empty string is zero rather than an error, exactly as `Number("")` is.
fn string_to_big_int(text: &str) -> Option<num_bigint::BigInt> {
    let trimmed = text.trim_matches(is_js_whitespace);
    if trimmed.is_empty() {
        return Some(num_bigint::BigInt::from(0));
    }
    let radix = match trimmed.get(..2) {
        Some("0x" | "0X") => Some(16),
        Some("0o" | "0O") => Some(8),
        Some("0b" | "0B") => Some(2),
        _ => None,
    };
    match radix {
        // A prefixed literal takes no sign and no separators, so the digits are handed over
        // exactly as written and an empty tail is refused rather than read as zero.
        Some(radix) => {
            let digits = trimmed.get(2..).filter(|digits| !digits.is_empty())?;
            num_bigint::BigInt::parse_bytes(digits.as_bytes(), radix)
        }
        None => trimmed.parse::<num_bigint::BigInt>().ok(),
    }
}
/// A regexp's flags in the order `RegExp.prototype.flags` publishes them.
///
/// `dgimsuvy`, which is the order the generic getter walks its eight accessors in. The stored
/// spelling is whatever the program wrote, and the two must not disagree.
fn canonical_regexp_flags(written: &str) -> String {
    "dgimsuvy"
        .chars()
        .filter(|flag| written.contains(*flag))
        .collect()
}

/// Whether `target` carries the brand of the class evaluation that is asking.
///
/// A private name is stored under a key fixed at compile time, so two *evaluations* of one class
/// share it and the own-only rule alone cannot tell them apart: `A.probe(new B())` read B's slot
/// where the language refuses it. Each evaluation mints a brand, every instance and the
/// constructor carry it, and this compares the two.
///
/// An absent expected brand means the access was compiled outside any class -- a syntax error
/// reported elsewhere -- and is let through so the error that matters is the one already raised.
fn private_brand_matches(target: &Value, name: &str, expected: &Value) -> bool {
    if matches!(expected, Value::Undefined) {
        return true;
    }
    let Some((scope, _)) = name
        .strip_prefix(PRIVATE_KEY_PREFIX)
        .and_then(|rest| rest.split_once(':'))
    else {
        return true;
    };
    let key = format!("{PRIVATE_KEY_PREFIX}{scope}:%brand");
    match own_private_element(target, &key) {
        Some((Property::Value(held), _)) => strict_equal(&held, expected),
        _ => false,
    }
}

/// Whether `new value(...)` is something the language will run.
///
/// A different question from "is it callable", and programs ask it directly: Test262's own
/// `isConstructor` is `Reflect.construct(function () {}, [], f)`, so hundreds of tests turn on
/// this answer. An arrow, a generator and an async function are callable and have no
/// `[[Construct]]`; so is every built-in that is not a constructor.
///
/// A method shorthand is the one shape this cannot tell apart from an ordinary function: the
/// compiler does not record which it is, so `({ m() {} }).m` is reported constructable here and
/// is not. That is a gap in what the IR carries, not a judgement made here.
/// The characters `trim`, `trimStart` and `trimEnd` remove.
///
/// Rust's `char::is_whitespace` is Unicode `White_Space`, and the language's `WhiteSpace`
/// production is that set *plus* U+FEFF, which Unicode classifies as a format character rather
/// than whitespace. So `"\u{feff}a\u{feff}".trim()` kept both ends here and strips them
/// everywhere else -- a byte-order mark at the front of a file read as text is exactly how one
/// arrives, and it survived into a value the program then compared against.
fn is_js_whitespace(character: char) -> bool {
    character.is_whitespace() || character == '\u{feff}'
}

fn closure_is_constructor(closure: &Closure) -> bool {
    closure
        .program
        .functions
        .get(closure.function as usize)
        .is_some_and(|proto| {
            !proto.arrow && !proto.generator && !proto.asynchronous && !proto.is_method
        })
}

fn is_constructor(value: &Value) -> bool {
    match value {
        Value::Function(closure) => closure_is_constructor(closure),
        // A bound function is constructable exactly when what it wraps is: `new f.bind(x)()`
        // runs `f` as a constructor and ignores the bound receiver.
        Value::Bound(bound) => is_constructor(&bound.target),
        Value::Proxy(proxy) => is_constructor(&proxy.target),
        Value::Native(native, _) => native_is_constructor(*native),
        _ => false,
    }
}

/// The same question for a built-in.
fn native_is_constructor(native: Native) -> bool {
    match native {
        // `Proxy` is the one constructor with no `prototype` of its own -- a proxy inherits the
        // target's chain -- so the rule below cannot see it.
        Native::ProxyConstructor
        | Native::TextDecoderConstructor
        | Native::TextEncoderConstructor
        | Native::AbortControllerConstructor
        // `AbortSignal` is a constructor that *refuses* `new`, exactly as `Symbol` is: a signal
        // comes from a controller or from one of the statics and never from a caller, which is
        // what keeps cancellation one-directional. Reported as a constructor so the refusal is
        // "Illegal constructor" rather than "not a constructor", which is what node says and
        // what a feature check reads.
        | Native::AbortSignalConstructor
        | Native::NodeStringDecoderConstructor
        | Native::NodeAsyncResource
        // Three more the rule below cannot see, because they have no intrinsic prototype entry
        // for it to find. Each is a real constructor, and saying otherwise is visible to a
        // program: `Reflect.construct(URL, ["http://example.com"])` answered "URL is not a
        // constructor", and `new http.Server()` the same. `Iterator` is the abstract base and
        // *refuses* `new`, like `AbortSignal` above -- reported as a constructor so the refusal
        // names the right reason.
        | Native::UrlConstructor
        | Native::IteratorConstructor
        | Native::ConsoleConstructor
        | Native::NodeHttpServer
        | Native::NodeAsyncLocalStorage => true,
        Native::GeneratorFunctionPrototype | Native::AsyncGeneratorFunctionPrototype => false,
        // Each error kind's `prototype` is a per-realm object rather than a table, which the
        // marker alone cannot answer for.
        Native::Error(_) => true,
        // Everything else that constructs is exactly what owns a `prototype`: that object is
        // what its instances link to, and a built-in with nothing to link is not one. It is
        // also what separates `Symbol` -- a constructor that refuses `new` -- from `Math.max`,
        // which is not a constructor at all.
        other => intrinsic_prototype(&Value::Native(other, RealmId::PRIMARY)).is_some(),
    }
}

/// One accessor published by a built-in prototype, or by a constructor in the case of
/// `Symbol.species`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BuiltinAccessor {
    /// `ArrayBuffer.prototype`'s four, each a `TypeError` on a *shared* buffer: the two types
    /// share no accessor, and answering a shared buffer's length from the unshared getter would
    /// make the brand check the specification demands invisible.
    BufferByteLength,
    BufferMaxByteLength,
    BufferResizable,
    BufferDetached,
    BufferImmutable,
    /// `SharedArrayBuffer.prototype`'s three, the mirror image.
    SharedByteLength,
    SharedMaxByteLength,
    SharedGrowable,
    DataViewBuffer,
    DataViewByteLength,
    DataViewByteOffset,
    TypedArrayBuffer,
    TypedArrayByteLength,
    TypedArrayByteOffset,
    TypedArrayLength,
    /// `Map.prototype.size` and `Set.prototype.size`. The payload is which of the two, because
    /// each is branded: `Map.prototype`'s getter refuses a `Set`.
    CollectionSize(bool),
    /// `get [Symbol.species]`, which every one of them defines identically: it answers its own
    /// receiver, so a subclass's derived operations build the subclass.
    Species,
    /// `DisposableStack.prototype.disposed`.
    DisposableStackDisposed,
    /// `AsyncDisposableStack.prototype.disposed`.
    AsyncDisposableStackDisposed,
    /// `Symbol.prototype.description`, which is an accessor and not a slot on the instance.
    SymbolDescription,
}

impl BuiltinAccessor {
    /// The name the accessor is published under.
    fn property_key(self) -> &'static str {
        match self {
            Self::BufferByteLength
            | Self::SharedByteLength
            | Self::DataViewByteLength
            | Self::TypedArrayByteLength => "byteLength",
            Self::BufferMaxByteLength | Self::SharedMaxByteLength => "maxByteLength",
            Self::BufferResizable => "resizable",
            Self::SharedGrowable => "growable",
            Self::BufferDetached => "detached",
            Self::BufferImmutable => "immutable",
            Self::DataViewBuffer | Self::TypedArrayBuffer => "buffer",
            Self::DataViewByteOffset | Self::TypedArrayByteOffset => "byteOffset",
            Self::TypedArrayLength => "length",
            Self::SymbolDescription => "description",
            Self::CollectionSize(_) => "size",
            Self::DisposableStackDisposed | Self::AsyncDisposableStackDisposed => "disposed",
            Self::Species => WellKnown::Species.property_key(),
        }
    }
}

/// Read a branded slot without consulting ordinary own properties or prototype tables.
///
/// Callers must perform the accessor's brand check first. DataView bounds errors are checked by
/// the dispatch path; this helper retains the zero used by the non-throwing internal property
/// reader.
fn builtin_accessor_slot(accessor: BuiltinAccessor, receiver: &Value) -> Value {
    match accessor {
        BuiltinAccessor::BufferByteLength | BuiltinAccessor::SharedByteLength => match receiver {
            Value::ArrayBuffer(buffer) => Value::Number(buffer.byte_length() as f64),
            _ => unreachable!("buffer accessor passed a non-buffer receiver"),
        },
        BuiltinAccessor::BufferMaxByteLength | BuiltinAccessor::SharedMaxByteLength => {
            match receiver {
                Value::ArrayBuffer(buffer) => Value::Number(if buffer.detached() {
                    0.0
                } else {
                    buffer
                        .max_byte_length
                        .unwrap_or_else(|| buffer.byte_length()) as f64
                }),
                _ => unreachable!("buffer accessor passed a non-buffer receiver"),
            }
        }
        BuiltinAccessor::BufferResizable => match receiver {
            Value::ArrayBuffer(buffer) => Value::Boolean(buffer.max_byte_length.is_some()),
            _ => unreachable!("buffer accessor passed a non-buffer receiver"),
        },
        BuiltinAccessor::BufferDetached => match receiver {
            Value::ArrayBuffer(buffer) => Value::Boolean(buffer.detached()),
            _ => unreachable!("buffer accessor passed a non-buffer receiver"),
        },
        BuiltinAccessor::BufferImmutable => match receiver {
            Value::ArrayBuffer(buffer) => Value::Boolean(buffer.immutable),
            _ => unreachable!("buffer accessor passed a non-buffer receiver"),
        },
        BuiltinAccessor::SharedGrowable => match receiver {
            Value::ArrayBuffer(buffer) => Value::Boolean(buffer.max_byte_length.is_some()),
            _ => unreachable!("shared-buffer accessor passed a non-buffer receiver"),
        },
        BuiltinAccessor::DataViewBuffer => match receiver {
            Value::DataView(view) => Value::ArrayBuffer(Rc::clone(&view.buffer)),
            _ => unreachable!("DataView accessor passed a non-DataView receiver"),
        },
        BuiltinAccessor::DataViewByteLength => match receiver {
            Value::DataView(view) => Value::Number(view.byte_length().unwrap_or(0) as f64),
            _ => unreachable!("DataView accessor passed a non-DataView receiver"),
        },
        BuiltinAccessor::DataViewByteOffset => match receiver {
            Value::DataView(view) => Value::Number(if view.out_of_bounds() {
                0.0
            } else {
                view.offset as f64
            }),
            _ => unreachable!("DataView accessor passed a non-DataView receiver"),
        },
        BuiltinAccessor::TypedArrayBuffer => match receiver {
            Value::TypedArray(view) => Value::ArrayBuffer(Rc::clone(&view.buffer)),
            _ => unreachable!("TypedArray accessor passed a non-TypedArray receiver"),
        },
        BuiltinAccessor::TypedArrayByteLength => match receiver {
            Value::TypedArray(view) => Value::Number((view.len() * view.kind.width()) as f64),
            _ => unreachable!("TypedArray accessor passed a non-TypedArray receiver"),
        },
        BuiltinAccessor::TypedArrayByteOffset => match receiver {
            Value::TypedArray(view) => Value::Number(if view.out_of_bounds() {
                0.0
            } else {
                view.offset as f64
            }),
            _ => unreachable!("TypedArray accessor passed a non-TypedArray receiver"),
        },
        BuiltinAccessor::TypedArrayLength => match receiver {
            Value::TypedArray(view) => Value::Number(view.len() as f64),
            _ => unreachable!("TypedArray accessor passed a non-TypedArray receiver"),
        },
        BuiltinAccessor::SymbolDescription => match receiver {
            Value::Symbol(symbol) => symbol
                .description_units()
                .map_or(Value::Undefined, Value::String),

            _ => unreachable!("Symbol accessor passed a non-symbol receiver"),
        },
        BuiltinAccessor::Species
        | BuiltinAccessor::CollectionSize(_)
        | BuiltinAccessor::DisposableStackDisposed
        | BuiltinAccessor::AsyncDisposableStackDisposed => {
            unreachable!("stateful accessor handled before direct slot read")
        }
    }
}

/// Which accessor an intrinsic prototype publishes under `key`, or `None` if the name is not an
/// accessor.
///
/// One row in `intrinsic_members` carries both the name and the getter, because they used to be
/// two tables and a name present in one but absent from the other is not a compile error -- it is
/// a property that lists and describes as a data property holding `undefined`.

fn prototype_accessor(table: PrototypeTable, key: &str) -> Option<BuiltinAccessor> {
    intrinsic_members::accessor(table, key)
}

/// The accessor the *machine* has to run for a read of `key` on `target`, or `None`.
///
/// These are the accessors whose getter does real work -- a brand check and a slot -- so a read
/// of one is a call. The tables cannot answer a call, which is why a read has to ask here
/// before it falls through to them.
fn machine_accessor(target: &Value, key: &str) -> Option<BuiltinAccessor> {
    match target {
        Value::Native(Native::PrototypeOf(table), _) => prototype_accessor(*table, key),
        Value::Native(native, _) if defines_species(*native) => {
            (key == WellKnown::Species.property_key()).then_some(BuiltinAccessor::Species)
        }
        // Each concrete typed-array constructor inherits `%TypedArray%[@@species]`; unlike the
        // ordinary function case below, native constructors do not expose that inheritance via
        // a stored Function object, so answer the inherited accessor directly here.
        Value::Native(Native::TypedArrayConstructor(_), _)
            if key == WellKnown::Species.property_key() =>
        {
            Some(BuiltinAccessor::Species)
        }
        // A subclass constructor *inherits* the accessor: `class MyArray extends Array {}` puts
        // `Array` in `MyArray`'s own prototype chain, so `MyArray[Symbol.species]` is the same
        // getter answering a different receiver -- which is the whole mechanism by which
        // `myArray.map(f)` builds a `MyArray`. The chain here is the constructor's own, not its
        // instances', and it ends at a built-in that the store cannot be walked into.
        Value::Function(_) | Value::Bound(_) if key == WellKnown::Species.property_key() => {
            let mut current = prototype_of(target);
            for _ in 0..MAX_PROTOTYPE_DEPTH {
                match current {
                    Value::Native(native, _)
                        if defines_species(native)
                            || matches!(native, Native::TypedArrayConstructor(_)) =>
                    {
                        return Some(BuiltinAccessor::Species);
                    }
                    Value::Function(_) | Value::Bound(_) => current = prototype_of(&current),
                    _ => return None,
                }
            }
            None
        }
        _ => None,
    }
}

/// Whether this built-in defines `Symbol.species`, which is the eight the specification names
/// and nothing else -- a constructor that does not define one inherits whatever its own
/// prototype has, which for the nine view constructors is `%TypedArray%`'s.
const fn defines_species(native: Native) -> bool {
    matches!(
        native,
        Native::ArrayConstructor
            | Native::ArrayBufferConstructor
            | Native::SharedArrayBufferConstructor
            | Native::MapConstructor
            | Native::SetConstructor
            | Native::PromiseConstructor
            | Native::RegExpConstructor
            | Native::TypedArrayIntrinsic
    )
}

/// Whether a numeric argument still has to go through `ToNumber` to become one.
///
/// `undefined` is left alone: it is not a missing number but a *meaningful* one, and each
/// built-in says for itself what it means -- `slice(1, undefined)` runs to the end, where
/// `ToNumber(undefined)` is `NaN`. A symbol and a BigInt are converted rather than skipped,
/// because converting either is the `TypeError` the language requires and the pure table
/// answered `NaN` for both.
fn needs_number_conversion(value: &Value) -> bool {
    match value {
        Value::Undefined | Value::Number(_) => false,
        Value::Symbol(_) | Value::BigInt(_) => true,
        other => is_reflect_target(other),
    }
}

/// The argument positions a built-in reads as *text*, so `ToString` runs the program's own
/// `toString` before the built-in ever sees the value.
///
/// The same shape as [`numeric_arguments`] and for the same reason: the conversion can call back
/// into the program -- and can therefore throw, which is exactly what these are written to do --
/// and the pure table has no machine to run it with. It read every object as
/// `"[object Object]"` instead, so a `toString` that threw was silently skipped.
const fn textual_arguments(native: Native) -> &'static [usize] {
    use Native as N;
    match native {
        // `CreateHTML` converts the attribute value only when there *is* an attribute; the nine
        // wrappers that take none ignore whatever they are passed, symbols included.
        N::StringHtml(
            HtmlWrapper::Anchor
            | HtmlWrapper::FontColor
            | HtmlWrapper::FontSize
            | HtmlWrapper::Link,
        )
        | N::Escape
        | N::Unescape => &[0],
        // The search string converts before the position does: `"s".indexOf(a, b)` is
        // `ToString(a)` then `ToIntegerOrInfinity(b)`, and running the numeric pass first
        // reversed a pair of conversions a program counting its own `toString` calls can see.
        N::StringIndexOf
        | N::StringLastIndexOf
        | N::StringIncludes
        | N::StringStartsWith
        | N::StringEndsWith
        // The form is `ToString`'d before it is checked, so an object naming a form is accepted
        // and one whose `toString` throws does so here.
        | N::StringNormalize => &[0],
        _ => &[],
    }
}

/// Whether an argument still has to go through `ToString`.
///
/// An object, because the conversion is a call it may define; and a symbol, because `ToString`
/// is the step that refuses one. Every other primitive spells itself, so it is left for the
/// built-in's own `to_display_string` and nothing is re-dispatched for it.
fn needs_text_conversion(value: &Value) -> bool {
    matches!(value, Value::Symbol(_)) || is_reflect_target(value)
}

/// Whether this value reduces to a primitive by calling one of its own methods.
/// Whether reducing this value to a primitive is a *call* rather than a no-op.
///
/// The question `==` asks before it coerces at all, and deliberately not "is this an object": a
/// `Date` is a value kind here and still reduces by calling, so `date == String(date)` compares
/// two strings and is true. Answering it with an object test left that one false. The C backend
/// asks the same question under the same name, for the same reason.
fn reduces_to_primitive(value: &Value) -> bool {
    matches!(
        value,
        Value::Object(_)
            | Value::Function(_)
            | Value::Array(_)
            | Value::Date(_)
            | Value::Temporal(_)
    )
}

/// `Reflect.get` does not box primitive targets. Every other public `Value` variant represents an
/// object or callable object; `Cell` is internal and must never escape as a target.
/// Whether `target` may be given `prototype`, per `OrdinarySetPrototypeOf`'s two refusals.
///
/// An object that has been made non-extensible has declared its shape final, and its prototype
/// is part of that shape. And a chain that reaches back to the object it started from is a
/// cycle: every failed lookup on it walks forever, which is a hang rather than an error, so the
/// language refuses to build one at all. Assigning the prototype an object already has is
/// always allowed -- nothing changes, so neither refusal has anything to refuse.
///
/// Answering `bool` rather than throwing is what lets the four spellings of this operation each
/// react as the specification says: `Reflect.setPrototypeOf` reports `false`, `Object.setPrototypeOf`
/// and the `__proto__` setter throw, and `{ __proto__: x }` in a literal never gets here at all.
fn prototype_may_change(intrinsics: &Intrinsics, target: &Value, prototype: &Value) -> bool {
    if same_value(&prototype_of(target), prototype) {
        return true;
    }
    if !is_extensible_target(intrinsics, target) {
        return false;
    }
    let mut link = prototype.clone();
    // The chain being walked cannot already contain a cycle -- this is the check that keeps one
    // from being made -- so the walk terminates on its own. The step cap is there for the one
    // case that is not this operation's to reason about: a chain that reaches a value whose
    // prototype is answered by a table rather than a slot.
    for _ in 0..MAX_PROTOTYPE_DEPTH {
        if !is_reflect_target(&link) {
            return true;
        }
        if same_value(&link, target) {
            return false;
        }
        // A proxy answers `[[GetPrototypeOf]]` with a trap, and running the program's code in
        // the middle of this check is not what the specification asks for: it stops the walk at
        // the first non-ordinary object.
        if matches!(link, Value::Proxy(_)) {
            return true;
        }
        link = prototype_of(&link);
    }
    true
}

/// How far the cycle check walks before it gives up and allows the write.
/// What `Object.setPrototypeOf` and the `__proto__` setter throw when the change is refused.
fn prototype_change_refused() -> ExecutionError {
    ExecutionError::TypeErrorMessage {
        message: "Cyclic __proto__ value or non-extensible object".to_owned(),
    }
}

/// Which of a built-in's arguments name a *number*, in argument order.
///
/// Every one of these begins with `ToNumber`, and `ToNumber` of an object is the program's own
/// `Symbol.toPrimitive`, `valueOf` or `toString` -- a call, which the pure table cannot make.
/// It answered `NaN` for every object instead, so `a.slice({valueOf: () => 1})` silently sliced
/// from zero and `"ab".repeat({valueOf(){throw x}})` never threw at all.
///
/// In argument order because the order is observable: two arguments that both throw must throw
/// the leftmost first. Only positions that are numbers are listed -- `fill`'s value and
/// `indexOf`'s needle are any value at all, and converting either would be wrong.
const fn numeric_arguments(native: Native) -> &'static [usize] {
    use Native as N;
    match native {
        N::ArraySlice
        | N::ArraySplice
        | N::StringSlice
        | N::StringSubstring
        | N::StringSubstr
        | N::ArrayBufferSlice
        | N::TypedArraySubarray
        | N::ArrayCopy(ArrayCopy::ToSpliced) => &[0, 1],
        N::ArrayCopyWithin => &[0, 1, 2],
        N::ArrayFill => &[1, 2],
        N::ArrayIndexOf
        | N::ArrayLastIndexOf
        | N::ArrayIncludes
        | N::StringIndexOf
        | N::StringLastIndexOf
        | N::StringIncludes
        | N::StringStartsWith
        | N::StringEndsWith
        | N::TypedArraySet => &[1],
        // `split` reads its *limit* before its separator: `ToUint32(limit)` happens first, and a
        // limit of zero answers the empty array without the string ever being cut. Leaving the
        // limit to the pure read meant the separator converted first, which a `toString`
        // counting its calls can see.
        N::StringSplit => &[1],
        N::ArrayAt
        | N::ArrayCopy(ArrayCopy::With)
        | N::StringAt
        | N::StringCharAt
        | N::StringCharCodeAt
        | N::StringCodePointAt
        | N::StringPadStart
        | N::StringPadEnd
        | N::StringRepeat
        | N::NumberToFixed
        | N::NumberToExponential
        | N::NumberToPrecision
        | N::NumberToString
        | N::ArrayBufferResize
        | N::ArrayBufferGrow
        | N::ArrayBufferTransfer { .. }
        | N::DataViewGet(_)
        | N::DataViewSet(_)
        | N::DataViewGetBig { .. }
        // `ToIndex` of the bit count, which is a `ToNumber` first: `BigInt.asIntN(obj, x)` has
        // to call `obj.valueOf()`. The *second* argument is deliberately not here -- it is a
        // BigInt, and coercing it to a number would be the one conversion the language refuses.
        | N::BigIntAsIntN
        | N::BigIntAsUintN
        | N::DataViewSetBig { .. } => &[0],
        _ => &[],
    }
}

fn is_reflect_target(value: &Value) -> bool {
    !matches!(
        value,
        Value::Undefined
            | Value::Null
            | Value::Boolean(_)
            | Value::Number(_)
            | Value::String(_)
            | Value::BigInt(_)
            | Value::Symbol(_)
            | Value::Cell(_)
    )
}

/// What a proxy ultimately wraps, following a chain of them.
///
/// For the operations that are defined on the *shape* of a value rather than on its properties
/// -- `Array.isArray`, `instanceof` -- and which therefore have no trap to consult.
fn unwrap_proxy(value: &Value) -> &Value {
    let mut current = value;
    for _ in 0..MAX_PROTOTYPE_DEPTH {
        match current {
            Value::Proxy(proxy) => current = &proxy.target,
            other => return other,
        }
    }
    current
}

/// The built-in that constructs values of this kind, for `x.constructor`.
///
/// `None` for the kinds that answer through an ordinary prototype chain -- a plain object and a
/// compiled function both carry `constructor` as a property, and inventing one here would shadow
/// what the program put there.
fn intrinsic_constructor(value: &Value) -> Option<Value> {
    let realm = value_realm(value);
    let native = match value {
        // A `Temporal` value's constructor is the one of the eight its kind names, which is what
        // `date.constructor === Temporal.PlainDate` asks and what a library reaches for to build
        // another of the same type.
        Value::Temporal(built) => Native::Temporal(temporal::Op::Constructor(built.kind())),
        Value::Date(_) => Native::DateConstructor,
        Value::RegExp(_) => Native::RegExpConstructor,
        Value::Promise(_) => Native::PromiseConstructor,
        Value::Array(_) => Native::ArrayConstructor,
        Value::String(_) => Native::StringConstructor,
        Value::Number(_) => Native::NumberConstructor,
        Value::Boolean(_) => Native::BooleanConstructor,
        Value::BigInt(_) => Native::BigIntConstructor,
        Value::Symbol(_) => Native::SymbolConstructor,
        _ => return None,
    };
    Some(Value::Native(native, realm))
}

/// `call`, `apply`, and `bind`, which every callable has and nothing else does.
///
/// Returned unbound, like every other method here: the receiver is the function being called
/// through, and `CallMethod` supplies it.
fn function_property(intrinsics: &Intrinsics, name: &str, realm: RealmId) -> Value {
    // `Function.prototype` owns its constructor. A compiled or bound function reaches that
    // table before `Object.prototype`, so answering Object here is observably wrong even though
    // both values are constructors (`fn.constructor.name` is ecosystem feature detection).
    if name == "constructor" {
        return Value::Native(Native::FunctionConstructor, realm);
    }
    match table_step(
        intrinsics,
        PrototypeTable::Function,
        name,
        tabulated_function_property(name),
        realm,
    ) {
        // A function is an object, so it inherits `Object.prototype`'s methods too --
        // `Object.hasOwnProperty.call(x, k)` reads them off the *constructor*, which is how the
        // plain-object check every library ships is written.
        Value::Undefined => inherited_object_property(intrinsics, name, realm),
        found => found,
    }
}

/// The same three with the realm's store left out: what `Function.prototype` was *built* with.
fn tabulated_function_property(name: &str) -> Value {
    match name {
        // Not the source text, which the VM never sees -- the same reason an error carries no
        // `stack`. What it does promise is that two different functions give two different
        // strings, which is what the `isPlainObject` check every library ships depends on.
        "toString" => Value::Native(Native::FunctionToString, RealmId::PRIMARY),
        "call" => Value::Native(Native::FunctionCall, RealmId::PRIMARY),
        "apply" => Value::Native(Native::FunctionApply, RealmId::PRIMARY),
        "bind" => Value::Native(Native::FunctionBind, RealmId::PRIMARY),
        // Published here rather than in `intrinsic_prototype_method_names`, which is what an
        // earlier attempt did: that list is the *enumeration*, and a reserved key put in it leaks
        // the internal spelling of the symbol into every property listing in the realm. This one
        // is the existence-and-value path, which is where a symbol-keyed member belongs --
        // `Date.prototype[@@toPrimitive]` is published the same way.
        key if key == WellKnown::HasInstance.property_key() => {
            Value::Native(Native::FunctionHasInstance, RealmId::PRIMARY)
        }
        _ => Value::Undefined,
    }
}

/// The number a `Number.prototype` method is running on, or the `TypeError` it owes.
///
/// Not `as_number`: these three are the specification's `ThisNumberValue`, which accepts a number
/// and a Number object and *refuses* everything else rather than coercing it. Coercing was the
/// old behaviour and it made `Number.prototype.toFixed.call("1.005")` answer where it should
/// throw. A wrapper has already been opened by the time this runs.
fn branded_number(receiver: &Value) -> Result<f64, ExecutionError> {
    match receiver {
        Value::Number(value) => Ok(*value),
        other => Err(ExecutionError::TypeErrorMessage {
            message: format!(
                "Number.prototype method called on {}",
                other.to_display_string()
            ),
        }),
    }
}

/// The boolean a `Boolean.prototype` method is running on, or the `TypeError` it owes.
fn branded_boolean(receiver: &Value) -> Result<bool, ExecutionError> {
    match receiver {
        Value::Boolean(value) => Ok(*value),
        other => Err(ExecutionError::TypeErrorMessage {
            message: format!(
                "Boolean.prototype method called on {}",
                other.to_display_string()
            ),
        }),
    }
}

/// The characters a String wrapper owns, read off the box rather than through its prototype.
///
/// A String object is *exotic*: the specification gives it an own, non-configurable property per
/// character plus a `length`, which is what makes `Object.keys(new String("ab"))` `["0", "1"]`
/// and `delete new String("a")[0]` fail. Every other wrapper owns nothing.
fn string_exotic(target: &Value, key: &str) -> Option<Value> {
    string_exotic_key(target, PropertyKeyRef::Utf8(key))
}

fn string_exotic_key(target: &Value, key: PropertyKeyRef<'_>) -> Option<Value> {
    let Some(Value::String(text)) = wrapped_primitive(target) else {
        return None;
    };
    if key.matches_ascii("length") {
        return Some(Value::Number(text.encode_utf16().count() as f64));
    }
    let index = array_index_key(key)?;
    text.unit_at(index)
        .map(|unit| Value::String(StringUnits::from_units(&[unit])))
}

/// Whether this array still behaves ordinarily enough for the dense fast paths to answer for it.
///
/// An array whose `length` a program has locked is not one: `push` has to refuse rather than
/// grow it, `sort` has to refuse rather than rearrange it, and the refusal is a `TypeError` the
/// specification raises from inside the generic walk. The dense paths have no way to express
/// that, so such an array is walked the way any other object with a `length` is -- which is the
/// same algorithm, and already written.
fn array_walks_densely(items: &ArrayData) -> bool {
    items.length_writable.get()
        && !items.sparse.get()
        && items.elements.borrow().is_empty()
        && items.properties.borrow().is_extensible()
}

/// The property an array holds at `index` outside its dense storage, if any.
fn array_exotic_element(items: &ArrayData, index: usize) -> Option<ExoticElement> {
    items
        .elements
        .borrow()
        .iter()
        .find(|entry| entry.index == index)
        .cloned()
}

/// What an index reaches on an array's prototype chain, for a position the array has no element
/// at.
///
/// `Array.prototype[1] = 1` really does make `[0, , 2][1]` read as 1 and `1 in [0, , 2]` true: a
/// hole is the *absence* of an own property rather than a stored undefined, so the read carries
/// on up the chain exactly as it would for any other missing name. Answering `undefined` for one
/// made every generic walk visit a position no engine visits, and skip one every engine does.
fn array_inherited_index(
    intrinsics: &Intrinsics,
    items: &ArrayData,
    name: &str,
) -> Option<Property> {
    array_inherited_index_key(intrinsics, items, PropertyKeyRef::Utf8(name))
}

fn array_inherited_index_key(
    intrinsics: &Intrinsics,
    items: &ArrayData,
    key: PropertyKeyRef<'_>,
) -> Option<Property> {
    if let Some(found) = items.properties.borrow().lookup_key(key) {
        return Some(found);
    }
    // A chain the program moved has already been walked by `lookup`; only an array still linked
    // to `Array.prototype` reaches the realm's own store.
    if items.properties.borrow().prototype().is_some() {
        return None;
    }
    for table in [PrototypeTable::Array, PrototypeTable::Object] {
        if let Overridden::Held(property, _) = intrinsics.overridden_key(
            &Value::Native(Native::PrototypeOf(table), RealmId::PRIMARY),
            key,
        ) {
            return Some(property);
        }
    }
    None
}

/// The dense storage behind an array receiver, when the fast paths may answer for it.
fn dense_array(value: &Value) -> Option<&Rc<ArrayData>> {
    match value {
        Value::Array(items) if array_walks_densely(items) => Some(items),
        _ => None,
    }
}

/// What an array answers as an own property: an element, its `length`, or nothing.
///
/// Separate from the property store beside it because neither of those two is in the store --
/// the elements are a dense `Vec` and `length` is derived from its size -- and a prototype chain
/// that walks into an array has to see all three.
/// The first link a *read* of `target` walks to.
///
/// [`prototype_of`] is the reflective chain and answers `Null` for a primitive, which is what
/// `Object.getPrototypeOf` needs before it coerces. A read does not coerce: `"s".at` finds
/// `String.prototype.at` with no wrapper made anywhere, so the chain a read walks starts at the
/// wrapper prototype rather than at nothing. Reading the two off one function is what left
/// strings and numbers behind when every other kind could see an accessor a program had defined.
fn read_chain_start(target: &Value) -> Value {
    let realm = value_realm(target);
    let table = match target {
        Value::String(_) => PrototypeTable::String,
        Value::Number(_) => PrototypeTable::Number,
        Value::Boolean(_) => PrototypeTable::Boolean,
        Value::BigInt(_) => PrototypeTable::BigInt,
        Value::Symbol(_) => PrototypeTable::Symbol,
        _ => return prototype_of(target),
    };
    Value::Native(Native::PrototypeOf(table), realm)
}

/// An accessor a *built-in prototype* carries, for a value whose chain reaches one.
///
/// Nothing links to a built-in prototype. The tables are match arms rather than stores, and
/// `ObjectData::lookup` walks stored links and stops at the last one, so the realm's record of
/// what a program defined on `Array.prototype` is reached by name and by nothing else. A *data*
/// property defined there is still answered, because the read falls through to the table and the
/// table consults the realm's store on the way past. An accessor cannot be: it is a call, and
/// reaching it needs the `Property` itself rather than the value it would have read as.
///
/// Without this, `Object.defineProperty(Array.prototype, "x", { get })` is visible on the
/// prototype and invisible through every array -- and that asymmetry is not a curiosity. It is
/// how a redefined `constructor` read as the table's own: species construction asks an instance
/// for `.constructor`, a program that installs one installs an accessor, and the instance
/// answered `Array` while the prototype answered the override.
///
/// The walk stops at the first link that answers `name` at all -- an override holding a data
/// property, or a table publishing the name itself -- because carrying on past it would let an
/// accessor further up shadow the thing that actually answers, which is the direction a prototype
/// chain does not run in.
fn inherited_intrinsic_accessor_key(
    intrinsics: &Intrinsics,
    target: &Value,
    key: PropertyKeyRef<'_>,
) -> Option<Property> {
    // The common case by an enormous margin: no program has defined an accessor on any built-in,
    // so there is nothing up there to find and every read that misses its own store pays one
    // load to learn it. This walk is otherwise on the path of `array.map`.
    if !intrinsics.any_accessor() {
        return None;
    }
    let mut link = read_chain_start(target);
    // Table accessors are named with ASCII spellings. An unknown units key cannot name one, and
    // must remain on the exact store path rather than being converted through replacement chars.
    let Some(table_name) = key.known_ascii() else {
        return None;
    };
    let table_name = table_name.as_ref();
    // Bounded rather than trusted. `Object.setPrototypeOf` refuses to build a cycle, but this
    // walks the chain a value *kind* gives as well as the stored one, and a bounded walk cannot
    // hang whatever the two combine into. Real chains are a handful of links deep.
    for _ in 0..64 {
        let Value::Native(native, _) = link else {
            if matches!(link, Value::Null | Value::Undefined) {
                return None;
            }
            // An ordinary object on the chain has already been walked by `lookup`; carry on so
            // that a moved chain -- `array.__proto__ = {}` -- still reaches the table that
            // object's own prototype ends at.
            link = prototype_of(&link);
            continue;
        };
        match intrinsics.overridden_key(&link, key) {
            Overridden::Held(property @ Property::Accessor { .. }, _) => return Some(property),
            // A data property answers here, and the ordinary read is what finds it.
            Overridden::Held(Property::Value(_), _) => return None,
            // Deleted here, so the chain carries on past it -- which is the whole point of the
            // tombstone.
            Overridden::Absent => {}
            Overridden::Untouched => {
                if intrinsic_owns(native, &table_name).is_some()
                    || intrinsic_accessor(&link, &table_name).is_some()
                    || machine_accessor(&link, &table_name).is_some()
                {
                    return None;
                }
            }
        }
        link = prototype_of(&link);
    }
    None
}

fn array_own_property_key(items: &ArrayData, key: PropertyKeyRef<'_>) -> Option<Property> {
    if key.matches_ascii("length") {
        #[expect(clippy::cast_precision_loss)]
        let length = items.length() as f64;
        return Some(Property::Value(Value::Number(length)));
    }
    let index = array_index_key(key)?;
    items
        .borrow()
        .get(index)
        .filter(|value| !matches!(value, Value::Native(Native::Hole, _)))
        .cloned()
        .map(Property::Value)
}

/// The primitive a wrapper object boxes, or `None` for anything else.
///
/// The three wrapper *prototypes* are themselves wrappers: the specification gives
/// `Number.prototype` a `[[NumberData]]` of +0, `String.prototype` a `[[StringData]]` of "" and
/// `Boolean.prototype` a `[[BooleanData]]` of false. That is not a curiosity -- it is what makes
/// `Number.prototype.valueOf()` answer 0 instead of throwing, which a program reaches by calling
/// any of these methods without a receiver of its own.
/// The two functions a `NewPromiseCapability(C)` is waiting for.
///
/// Shared between the executor `C` is called with and the caller that will use them, because the
/// executor is *how* they arrive: the specification's own way of saying "whatever `C` does with
/// its argument, these are the functions that settle the promise it returns".
pub struct CapabilityRecord {
    resolve: RefCell<Value>,
    reject: RefCell<Value>,
}

impl std::fmt::Debug for CapabilityRecord {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("CapabilityRecord")
    }
}

impl Default for CapabilityRecord {
    fn default() -> Self {
        // Undefined until the executor is called, which is exactly the test the specification
        // makes: a constructor that never calls it leaves both undefined, and that is the
        // `TypeError` rather than a promise nothing holds the settlers for.
        Self {
            resolve: RefCell::new(Value::Undefined),
            reject: RefCell::new(Value::Undefined),
        }
    }
}

fn wrapped_primitive(value: &Value) -> Option<Value> {
    match value {
        Value::Object(object) => object.borrow().primitive().cloned(),
        Value::Native(Native::PrototypeOf(PrototypeTable::Number), _) => Some(Value::Number(0.0)),
        Value::Native(Native::PrototypeOf(PrototypeTable::String), _) => {
            Some(Value::String(String::new().into()))
        }
        Value::Native(Native::PrototypeOf(PrototypeTable::Boolean), _) => {
            Some(Value::Boolean(false))
        }
        _ => None,
    }
}

/// `ToObject(value)`: the object a value stands for, or `None` for the two that stand for none.
///
/// Every `Object` static and every `Object.prototype` method begins with this step, and skipping
/// it is visible twice over: `Object.assign(1, { a: 2 })` raised "cannot set a property on a
/// number" where the specification boxes the number and copies onto the box, and
/// `Object.prototype.hasOwnProperty.call(undefined, "x")` answered `false` where it owes a
/// `TypeError` -- an answer a feature-detect reads as "no such property".
fn to_object(value: &Value) -> Option<Value> {
    match value {
        Value::Undefined | Value::Null => None,
        Value::Boolean(_)
        | Value::Number(_)
        | Value::String(_)
        | Value::Symbol(_)
        | Value::BigInt(_) => Some(wrap_primitive(value.clone())),
        other => Some(other.clone()),
    }
}

/// The characters a String wrapper owns, as enumerable own properties.
///
/// They are held in the boxed string rather than in the store beside it, so every walk over own
/// properties has to ask for them separately. `Object.keys(Object("abc"))` was `[]` while
/// `Object.getOwnPropertyNames` of the same object listed all three, which is the two walks
/// disagreeing about one object.
fn string_wrapper_entries_units(value: &Value) -> Vec<(StringUnits, Property)> {
    let Some(Value::String(text)) = wrapped_primitive(value) else {
        return Vec::new();
    };
    text.units()
        .enumerate()
        .map(|(index, unit)| {
            (
                StringUnits::from(index.to_string()),
                Property::Value(Value::String(StringUnits::from_units(&[unit]))),
            )
        })
        .collect()
}

/// `new String("x")`, `new Number(1)`, `new Boolean(true)`, and the `Object(primitive)` that
/// builds the same thing.
///
/// The prototype is the matching wrapper table, which is what makes `new Boolean(true)` answer
/// `instanceof Boolean` and reach `Boolean.prototype.valueOf` -- the two observations that make a
/// wrapper worth having at all rather than an empty object with a value hidden inside it.
fn wrap_primitive(primitive: Value) -> Value {
    let table = match primitive {
        Value::String(_) => PrototypeTable::String,
        Value::Number(_) => PrototypeTable::Number,
        Value::Boolean(_) => PrototypeTable::Boolean,
        Value::Symbol(_) => PrototypeTable::Symbol,
        Value::BigInt(_) => PrototypeTable::BigInt,
        // Nothing else is boxable: `Object(x)` passes an object through and refuses null and
        // undefined before it reaches here.
        _ => PrototypeTable::Object,
    };
    let mut data = ObjectData::default();
    data.set_prototype(Value::Native(Native::PrototypeOf(table), RealmId::PRIMARY));
    data.primitive = Some(primitive);
    Value::Object(Rc::new(RefCell::new(data)))
}

/// The receiver a built-in sees, with a wrapper opened.
///
/// `String.prototype.charAt.call(new String("ab"), 0)` has to read the boxed string, and so does
/// every other method on a wrapper prototype -- there are fifty of them and each would otherwise
/// need the same unwrapping written out again. The generic object methods are deliberately not
/// in the set: `Object.prototype.toString` reports the *box*, which is the one thing that can
/// tell a wrapper apart from what it wraps.
fn receiver_for(native: Native, receiver: &Value) -> Option<Value> {
    let boxed = wrapped_primitive(receiver)?;
    let opens = match native {
        // `Object.prototype.valueOf` is deliberately absent: it answers with the box.
        Native::PrimitiveValueOf | Native::PrimitiveToString | Native::BigIntToString => true,
        Native::NumberToString
        | Native::NumberToFixed
        | Native::NumberToExponential
        | Native::NumberToPrecision
        | Native::NumberValueOf => true,
        Native::BooleanToString | Native::BooleanValueOf => true,
        // Every `String.prototype` method, recognised the same way `builtin_js_name` recognises
        // one: by the type its variant is spelled for. A list of forty-five names would be
        // forty-five chances to leave one out, and the ones that share the prefix without taking
        // a receiver -- `String.raw`, `String.fromCharCode` -- ignore it either way.
        other => format!("{other:?}").starts_with("String"),
    };
    opens.then_some(boxed)
}

/// `f.name` and `f.length` read off a built-in, which keeps them in no store.
fn identity_property(target: &Value, key: &str) -> Option<Value> {
    let (name, length) = intrinsic_identity(target)?;
    match key {
        "name" => Some(Value::String(name.into())),
        "length" => Some(Value::Number(length)),
        _ => None,
    }
}

/// Whether a compiled function has a `prototype` property at all.
///
/// An arrow has none: it cannot be constructed, so there is no object for instances to link to
/// and the specification gives it no slot. Listing one anyway would put a key in
/// `Object.getOwnPropertyNames` that reading it has to invent.
/// Whether this function carries the own `prototype` property that `new` would use.
///
/// Not every callable does. An arrow has never had one here; an *async* function should not
/// either, and did -- `(async function () {}).hasOwnProperty("prototype")` answered true where
/// every other engine answers false. An async generator is the exception that looks like a
/// contradiction: it keeps a `prototype`, because that object is what its generator instances
/// inherit from, not something `new` reaches.
///
/// A *method* -- shorthand, class, static, getter or setter -- has none unless it is a generator
/// (generators keep `prototype` because generator instances inherit from it).
fn has_prototype_property(closure: &Closure) -> bool {
    closure
        .program
        .functions
        .get(closure.function as usize)
        .is_some_and(|proto| {
            !proto.arrow
                && (!proto.asynchronous || proto.async_generator)
                && (!proto.is_method || proto.generator)
        })
}

/// The attributes every function's own `name` and `length` carry.
///
/// Locked against assignment and hidden from enumeration, but *configurable*: the specification
/// makes these the one pair a program is expected to redefine -- which is how a decorator
/// renames a function without replacing it.
/// `SetFunctionName(function, key, prefix)`.
///
/// The own private element under this reserved key, with the flags its slot carries.
///
/// Own-only on purpose: the presence of the name on the object *is* the brand check, so a
/// prototype walk would hand one class's private member to another class's instance.
fn own_private_element(target: &Value, key: &str) -> Option<(Property, Attributes)> {
    let read = |data: &ObjectData| {
        Some((
            data.get_own_property(key)?.clone(),
            data.get_own_attributes(key)?,
        ))
    };
    match target {
        Value::Object(object) => read(&object.borrow()),
        Value::Function(closure) => read(&closure.properties.borrow()),
        _ => None,
    }
}

/// A private name as the program spelled it, without the scope-numbered reservation it is keyed
/// under: `x` from `@@private:3:x`.
fn private_display_name(key: &str) -> &str {
    let reserved = key.strip_prefix(PRIVATE_KEY_PREFIX).unwrap_or(key);
    reserved.split_once(':').map_or(reserved, |(_, name)| name)
}

/// A method, a getter and a setter are each created anonymous and named by the definition that
/// installs them, which is also the only place a computed key is known. Nothing did it, so
/// `class C { m() {} }` left `C.prototype.m.name` empty, `{ get x() {} }` reported `""` where the
/// language says `"get x"`, and a symbol-keyed method reported nothing at all. That name is not
/// decoration: a decorator reads it, a stack trace prints it, and Test262 asserts it on almost
/// every method it defines.
fn define_function_name(
    function: &Value,
    key: &Value,
    prefix: Option<&str>,
) -> Result<(), ExecutionError> {
    let Value::Function(closure) = function else {
        return Ok(());
    };
    let name = match key {
        // A symbol names the property after its description, in brackets; one with no description
        // names it nothing, and a prefix is still applied to that nothing.
        Value::Symbol(symbol) => match symbol.description_units() {
            None => StringUnits::default(),
            Some(description) => {
                let mut builder = StringUnitsBuilder::new();
                builder.push_ascii("[")?;
                builder.push_units(&description)?;
                builder.push_ascii("]")?;
                builder.finish()
            }
        },
        other => {
            let key = other.property_key_units_checked()?;
            // A private name is spelled the way the program wrote it rather than the way the
            // store keys it: `#m`, not the scope-numbered reservation standing in for it.
            match key.to_scalar_string() {
                Ok(scalar_key) => match scalar_key.strip_prefix(PRIVATE_KEY_PREFIX) {
                    Some(reserved) => {
                        let display = reserved.split_once(':').map_or(reserved, |(_, name)| name);
                        let mut builder = StringUnitsBuilder::new();
                        builder.push_ascii("#")?;
                        builder.push_units(&StringUnits::from(display))?;
                        builder.finish()
                    }
                    None => key,
                },
                // Ordinary property keys can contain lone surrogates. They are already in the
                // canonical units representation; keep them intact rather than widening through
                // a replacement character just to inspect a private-name prefix.
                Err(_) => key,
            }
        }
    };

    let name = prefix.map_or(Ok(name.clone()), |prefix| {
        let mut builder = StringUnitsBuilder::new();
        builder.push_ascii(prefix)?;
        builder.push_ascii(" ")?;
        builder.push_units(&name)?;
        Ok(builder.finish())
    })?;
    closure
        .properties
        .borrow_mut()
        .define_value("name", Value::String(name), FUNCTION_IDENTITY);
    Ok(())
}

const FUNCTION_IDENTITY: Attributes = Attributes {
    writable: false,
    enumerable: false,
    configurable: true,
};

/// The `name` and `length` a runtime-supplied callable owns, or `None` for something that is not
/// a function at all.
///
/// `length` is the specification's declared parameter count, not this implementation's: it is
/// the number of arguments before the first optional one, so `Array.prototype.slice` is 2 and
/// `push` is 1 even though both accept any number. A program reads it to decide how many
/// arguments to forward, so guessing it wrong is worse than not answering.
fn intrinsic_identity(value: &Value) -> Option<(String, f64)> {
    match value {
        // A `%TypedArray%.prototype` method is a *distinct function* from the `Array.prototype`
        // one it shares an implementation with, but it is not a differently named or differently
        // shaped one: `%TypedArray%.prototype.map.name` is `"map"` and its `length` is 1, the
        // same two answers the array method gives. Delegating keeps them one fact rather than a
        // second tabulation that can drift from the first.
        Value::Native(Native::TypedArrayGeneric(method), _) => {
            intrinsic_identity(&array_property(method))
        }
        Value::Native(native, _) => {
            // A namespace is an object, not a function: `Math` has no call behaviour, so it has
            // no arity and no name of its own either. A Node builtin module is a namespace for
            // the same reason -- `require("path")` is an object, and node's has neither a
            // `length` nor a `name` for `Object.getOwnPropertyNames` to report.
            if namespace_name(native).is_some() || node_builtin_specifier(*native).is_some() {
                return None;
            }
            let length = native_length(*native)?;
            // `Function.prototype` is a function that takes nothing, returns undefined and is
            // *anonymous*: the derived spelling would call it `prototypeOf`, which is the name
            // of the variant rather than of anything a program can see.
            // `%ThrowTypeError%` is anonymous by definition, and the derived spelling would
            // hand a program the name of a Rust variant.
            if matches!(native, Native::PrototypeOf(_) | Native::ThrowTypeError) {
                return Some((String::new(), length));
            }
            Some((native_js_name(native), length))
        }
        // An array method the machine drives rather than a free function, or a generator's own
        // `next`. Every one of them declares exactly one argument -- the callback, or the value
        // resumed with -- so there is nothing to tabulate.
        Value::Callback(method, _) => Some((builtin_js_name(&format!("{method:?}")), 1.0)),
        // `bind` reports the arity still to be supplied and prefixes the name it wraps, which is
        // what makes a stack trace through one readable.
        Value::Bound(bound) => {
            let (name, length) = function_identity(&bound.target)?;
            Some((
                format!("bound {name}"),
                (length - bound.arguments.len() as f64).max(0.0),
            ))
        }
        // A promise's `resolve`/`reject` pair: anonymous, one argument, exactly as the
        // specification builds them.
        Value::Settler(..) => Some((String::new(), 1.0)),
        // The `GetCapabilitiesExecutor` takes the pair, so its `length` is 2. Anonymous like the
        // settlers, and for the same reason: the specification gives it no name.
        Value::Capability(_) => Some((String::new(), 2.0)),
        // A combinator's resolve or reject element function: one argument, and anonymous. The
        // specification is explicit that these are anonymous built-ins, and test262 checks the
        // descriptor rather than the value -- so this has to be an own, non-writable,
        // non-enumerable, configurable property, which is what this table produces.
        Value::Element(_) => Some((String::new(), 1.0)),
        _ => None,
    }
}

/// The `name` and `length` of any callable, compiled or built in.
fn function_identity(value: &Value) -> Option<(String, f64)> {
    match value {
        // Read from the store rather than from the closure's declared name, so that a function
        // whose `name` a program deleted reports what a read of it now reports -- the empty
        // string the specification substitutes for a target with no name of its own.
        Value::Function(closure) => {
            let properties = closure.properties.borrow();
            Some((
                match properties.get_own("name") {
                    Some(Value::String(name)) => name.to_scalar_string().unwrap_or_default(),
                    _ => String::new(),
                },
                match properties.get_own("length") {
                    Some(Value::Number(length)) => *length,
                    _ => 0.0,
                },
            ))
        }
        other => intrinsic_identity(other),
    }
}

/// The declared parameter count of one built-in, or `None` for something that is not callable.
///
/// Tabulated rather than derived: the number comes from the specification's own signature for
/// each function, and this implementation's Rust signature knows nothing about it -- every one
/// of these takes a slice. Grouped by arity so the table reads as the specification's tables do
/// rather than as two hundred separate claims.
#[expect(
    clippy::match_same_arms,
    reason = "grouped by arity, not by implementation"
)]
const fn native_length(native: Native) -> Option<f64> {
    if let Native::AtomicsOp(op) = native {
        return Some(op.arity());
    }
    if let Native::HostAgent(op) = native {
        return Some(op.arity());
    }
    use Native as N;
    Some(match native {
        // Not functions at all: internal markers that never reach a program, and the method
        // tables, which are ordinary objects. `Function.prototype` is the exception -- it *is*
        // callable, and it is the anonymous function of no arguments that returns undefined.
        N::Hole | N::Uninitialized | N::ReturnSignal | N::Tombstone => return None,
        N::PrototypeOf(PrototypeTable::Function) => 0.0,
        // `OrdinaryHasInstance(C, O)` takes the one value being tested; the constructor is the
        // receiver.
        N::FunctionHasInstance => 1.0,
        N::SymbolToPrimitive => 1.0,
        N::TypedArrayToStringTag => 0.0,
        N::PrototypeOf(_) => return None,
        N::Math | N::Json | N::Reflect | N::Performance => return None,
        N::HostCreateRealm => 0.0,
        N::HostEvalScript => 1.0,
        N::ShadowRealmConstructor => 0.0,
        N::ShadowRealmEvaluate => 1.0,
        N::ShadowRealmImportValue => 2.0,
        // `Intl`'s arities come from its own table: the namespace and the six prototypes are
        // not callable, and the constructors do not all take the same number of arguments.
        N::Intl(op) => match intl::length(op) {
            Some(length) => length,
            None => return None,
        },
        // `Temporal`'s the same way, and for one reason more: two of its types publish a
        // same-named method with different arities, so the table is keyed by the type as well as
        // by the method. Everything here fell to the `_ => 1.0` default below, which was right
        // for `from` and wrong for all fifty-four zero-argument readers and all ten that take a
        // pair.
        N::Temporal(op) => match temporal::length(op) {
            Some(length) => length,
            None => return None,
        },

        // The zero-argument built-ins: every accessor, every `toString`, and the collection
        // constructors, which take their contents through an optional argument.
        N::RegExpAccessor(_)
        | N::BuiltinAccessor(_)
        | N::ProtoGetter
        | N::ThrowTypeError
        | N::PromiseWithResolvers
        | N::MathRandom
        | N::DateNow
        | N::PerformanceNow
        | N::NumberValueOf
        | N::ObjectToLocaleString
        | N::ObjectValueOf
        | N::ObjectToStringTag
        | N::PrimitiveToString
        | N::PrimitiveValueOf
        | N::BooleanToString
        | N::BooleanValueOf
        | N::BigIntToString
        | N::RegExpToString
        | N::ErrorToString
        | N::FunctionToString
        | N::ArrayCopy(ArrayCopy::ToReversed)
        | N::ArrayJoinDefault
        | N::ArrayToLocaleString
        | N::ArrayPop
        | N::ArrayReverse
        | N::ArrayShift
        | N::ArrayEntries
        | N::ArrayKeys
        | N::ArrayValues
        | N::ArrayFlat
        | N::ArrayOf
        // The nine wrappers that take no attribute; the four that do fall to the default of 1.
        | N::StringHtml(
            HtmlWrapper::Big
                | HtmlWrapper::Blink
                | HtmlWrapper::Bold
                | HtmlWrapper::Fixed
                | HtmlWrapper::Italics
                | HtmlWrapper::Small
                | HtmlWrapper::Strike
                | HtmlWrapper::Sub
                | HtmlWrapper::Sup,
        )
        | N::StringTrim
        | N::StringTrimStart
        | N::StringTrimEnd
        | N::StringToUpperCase
        | N::StringToLowerCase
        | N::StringNormalize
        | N::StringValues
        | N::StringIteratorNext
        | N::ArrayIteratorNext
        | N::CollectionIteratorNext
        | N::CollectionKeys(_)
        | N::CollectionValues(_)
        | N::CollectionEntries(_)
        | N::CollectionClear(_)
        | N::IteratorSelf
        | N::IteratorTerminal(TerminalKind::ToArray)
        | N::IteratorWrapNext
        | N::IteratorHelperNext(_)
        | N::IteratorHelperReturn
        | N::IteratorConstructor
        | N::TypedArrayIntrinsic
        | N::TypedArrayOf(_)
        | N::SetConstructor
        | N::MapConstructor
        | N::WeakSetConstructor
        | N::WeakMapConstructor
        | N::SymbolConstructor
        | N::ArrayBufferTransfer { .. }
        | N::IteratorDispose
        | N::RegExpStringIteratorNext
        | N::IteratorConcat
        | N::IteratorConcatNext
        | N::IteratorConcatReturn
        | N::IteratorZipNext
        | N::IteratorZipReturn
        | N::WeakRefDeref
        | N::DisposableStackConstructor
        | N::DisposableStackMove
        | N::DisposableStackDispose
        | N::AsyncDisposableStackConstructor
        | N::AsyncDisposableStackMove
        | N::AsyncDisposableStackDisposeAsync
        | N::ProxyRevoke
        | N::ConsoleLog
        | N::ConsoleInfo
        | N::ConsoleDebug
        | N::ConsoleDir
        | N::ConsoleWarn
        | N::ConsoleError
        | N::ConsoleAssert
        | N::ConsoleClear
        | N::ConsoleCount
        | N::ConsoleCountReset
        | N::ConsoleGroup
        | N::ConsoleGroupEnd
        | N::ConsoleGroupCollapsed
        | N::ConsoleTable
        | N::ConsoleTime
        | N::ConsoleTimeEnd
        | N::ConsoleTimeLog
        | N::ConsoleTrace
        | N::ConsoleDirxml
        | N::ConsoleTimeStamp
        | N::ConsoleProfile
        | N::ConsoleProfileEnd => 0.0,

        // The two-argument ones. `Object.assign` is 2 because the specification counts the
        // target and one source; the rest of the sources are the rest parameter, which does not
        // count.
        N::ObjectAssign
        | N::ObjectCreate
        | N::ObjectSetPrototypeOf
        | N::ObjectDefineProperties
        | N::ObjectGetOwnPropertyDescriptor
        | N::ObjectHasOwn
        | N::ObjectIs
        | N::ReflectGet
        | N::ReflectHas
        | N::ReflectConstruct
        | N::ReflectSetPrototypeOf
        | N::ReflectGetOwnPropertyDescriptor
        | N::ReflectDeleteProperty
        | N::JsonParse
        | N::MathImul
        | N::MathAtan2
        | N::MathPow
        | N::MathHypot
        | N::MathMin
        | N::MathMax
        | N::RegExpSymbol(RegExpSymbol::Replace | RegExpSymbol::Split)
        | N::ArrayCopy(ArrayCopy::With)
        | N::ArrayCopy(ArrayCopy::ToSpliced)
        | N::DisposableStackAdopt
        | N::AsyncDisposableStackAdopt
        | N::CollectionGetOrInsert { .. }
        | N::ArraySlice
        | N::ArraySplice
        | N::ArrayCopyWithin
        | N::StringSlice
        | N::StringSplit
        | N::StringSubstring
        | N::StringSubstr
        | N::StringReplace
        | N::StringReplaceAll
        | N::ParseInt
        | N::RegExpConstructor
        | N::FunctionApply
        | N::PromiseThen
        | N::ProxyConstructor
        | N::ProxyRevocable
        | N::ArrayBufferSlice
        | N::TypedArraySubarray
        | N::DataViewSet(_)
        | N::DataViewSetBig { .. }
        | N::MapSet
        | N::ObjectGroupBy
        | N::MapGroupBy
        | N::LegacyAccessor { defines: true, .. }
        | N::BigIntAsIntN
        | N::BigIntAsUintN
        | N::FinalizationRegistryRegister
        | N::ArrayBufferSliceToImmutable
        | N::WeakMapSet => 2.0,

        // The three-argument ones.
        N::ObjectDefineProperty
        | N::ReflectDefineProperty
        | N::ReflectSet
        | N::ReflectApply
        | N::JsonStringify
        | N::TypedArrayConstructor(_) => 3.0,

        // `Date` and `Date.UTC` take year through millisecond.
        N::DateConstructor | N::DateUtc => 7.0,

        // Every method on `Date.prototype` carries its own, for the reason [`DateMethod`] gives.
        N::Date(method) => method.length(),

        // `toBase64` takes only an options bag and `toHex` takes nothing, so neither declares a
        // required argument; the four that read or fill from a string declare the string.
        // `transferToImmutable([newLength])` declares no required argument, which is how a
        // program feature-detects it apart from `transfer`.
        N::Uint8Text(ByteText::ToBase64 | ByteText::ToHex)
        | N::ArrayBufferTransferToImmutable => 0.0,

        // Everything left takes exactly one required argument.
        _ => 1.0,
    })
}

/// Which built-in the realm's property store is keyed by.
///
/// A built-in is a `Copy` marker rather than an allocation -- two reads of `Math.max` produce
/// the same value, which is what makes `Math.max === Math.max` true -- so the marker *is* the
/// identity, and comparing two of them compares the built-ins they name.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum IntrinsicKey {
    Native(Native, RealmId),
    Callback(CallbackMethod, RealmId),
}

/// The key a built-in is stored under, or `None` for a value that is not one.
///
/// `Bound` and `Settler` are deliberately absent. Each is an allocation with identity of its
/// own, so a realm-wide store keyed by one would keep every bound function a program mutated
/// alive until the run ended; they keep the read-only projection until they carry a store of
/// their own.
fn intrinsic_key(target: &Value) -> Option<IntrinsicKey> {
    match target {
        Value::Native(native, realm) => Some(IntrinsicKey::Native(*native, *realm)),
        Value::Callback(method, realm) => Some(IntrinsicKey::Callback(*method, *realm)),
        _ => None,
    }
}

/// What the realm's store says about one own property of a built-in.
enum Overridden {
    /// The store holds the property, and its slot is the whole answer.
    Held(Property, Attributes),
    /// The complete materialized store does not contain this key; absence is authoritative.
    Absent,
    /// The store says nothing about this name, so the tables answer.
    Untouched,
}

/// Retag a marker returned by a realm-blind intrinsic table before storing it.
///
/// Native and Callback values remain Copy markers, but every realm owns a distinct marker identity.
/// Ordinary stored objects/functions are left untouched because they already carry their own
/// identity and realm.
fn retag_intrinsic_property(property: Property, realm: RealmId) -> Property {
    match property {
        Property::Value(value) => Property::Value(in_realm(value, realm)),
        Property::Accessor { get, set } => Property::Accessor {
            get: get.map(|value| in_realm(value, realm)),
            set: set.map(|value| in_realm(value, realm)),
        },
    }
}

struct Intrinsics {
    /// A linear scan rather than a map: this is empty for a program that leaves the built-ins
    /// alone and holds a handful of entries for one that does not, which is well below the size
    /// where hashing every lookup pays for itself.
    entries: RefCell<Vec<(IntrinsicKey, ObjectData)>>,
    /// Whether any program has defined an *accessor* on any built-in.
    ///
    /// A guard for [`inherited_intrinsic_accessor_key`], which is asked on every read that misses a
    /// value's own store -- which is every method call on an array, a string or a map. False
    /// until a program does it and never cleared afterwards: `delete` removing the last one is
    /// rare enough that re-scanning to clear the flag would cost more than the walk it saves,
    /// and a stale `true` is only ever slower, never wrong.
    accessors: std::cell::Cell<bool>,
    /// Each realm's nine error prototypes, indexed by realm and then by kind.
    ///
    /// Here rather than on the machine because `Error.prototype` is an own property of `Error`
    /// and every path that reports own properties -- `getOwnPropertyDescriptor`,
    /// `hasOwnProperty`, `getOwnPropertyNames`, a computed read -- reaches those tables with an
    /// `&Intrinsics` and nothing else. Held on the machine, the object was reachable only from
    /// the one instruction that spells `Error.prototype` in source, so `Error["prototype"]` was
    /// `undefined` while `Error.prototype` was an object, and the descriptor every
    /// `verifyNotConfigurable(Error, "prototype")` reads did not exist.
    ///
    /// Interior mutability for the same reason the entries have it: the prototype is built on
    /// first use, and first use is now a `&self` read.
    error_prototypes: RefCell<Vec<[Option<Value>; ErrorKind::ALL.len()]>>,
    unscopables: RefCell<Vec<Option<Value>>>,
}

impl Default for Intrinsics {
    /// One realm's worth of slots, because a machine always has the primary realm.
    fn default() -> Self {
        Self {
            entries: RefCell::default(),
            accessors: std::cell::Cell::new(false),
            error_prototypes: RefCell::new(vec![[const { None }; ErrorKind::ALL.len()]]),
            unscopables: RefCell::new(vec![None]),
        }
    }
}

impl Intrinsics {
    /// `realm`'s prototype for one error kind, built on first use.
    ///
    /// Per realm rather than per execution, because `e instanceof TypeError` compares it by
    /// identity: an error thrown by realm 1's built-in is an instance of *its* `TypeError` and
    /// not of the one the primary realm hands out, and one shared object would make both
    /// answers wrong at once.
    ///
    /// A subclass's prototype chains to `Error.prototype`, so `e instanceof Error` holds for
    /// every kind and `toString` is inherited rather than copied.
    fn error_prototype(&self, kind: ErrorKind, realm: RealmId) -> Value {
        let index = realm.0 as usize;
        if let Some(prototype) = &self.error_prototypes.borrow()[index][kind.index()] {
            return prototype.clone();
        }
        let mut data = ObjectData::default();
        // None of these is enumerated: they are the realm's furniture, not something a program
        // put on the prototype, and `for (const k in e)` must not walk over them.
        data.set_non_enumerable("name", Value::String(kind.name().to_owned().into()));
        data.set_non_enumerable("message", Value::String(String::new().into()));
        // `e.constructor.name` is how a program asks which kind it caught, and this is the link
        // that answers it.
        data.set_non_enumerable("constructor", Value::Native(Native::Error(kind), realm));
        if matches!(kind, ErrorKind::Error) {
            // Marks the chain for `String(e)`. A real `toString` would be invoked through the
            // normal method path; this is the placeholder that keeps the observable behaviour
            // right until built-ins can be written in JavaScript (design.md §5).
            data.set_non_enumerable("toString", Value::Native(Native::ErrorToString, realm));
        }
        let prototype = Value::Object(Rc::new(RefCell::new(data)));
        if !matches!(kind, ErrorKind::Error) {
            // Recurses, so the borrow above has to be finished before this runs -- it is, and it
            // has to stay that way: building `TypeError.prototype` builds `Error.prototype`.
            let base = self.error_prototype(ErrorKind::Error, realm);
            if let Value::Object(object) = &prototype {
                object.borrow_mut().set_prototype(base);
            }
        }
        self.error_prototypes.borrow_mut()[index][kind.index()] = Some(prototype.clone());
        prototype
    }

    /// Make room for one more realm's error prototypes and unscopables.
    fn add_realm(&self) {
        self.error_prototypes
            .borrow_mut()
            .push([const { None }; ErrorKind::ALL.len()]);
        self.unscopables.borrow_mut().push(None);
    }

    /// Every error prototype this store holds, taken out so the caller can break their cycles.
    fn take_error_prototypes(&self) -> Vec<Value> {
        self.error_prototypes
            .borrow_mut()
            .iter_mut()
            .flat_map(|realm| realm.iter_mut().filter_map(Option::take))
            .collect()
    }

    /// Every unscopables object this store holds, taken out so the caller can break their cycles.
    fn take_unscopables(&self) -> Vec<Value> {
        self.unscopables
            .borrow_mut()
            .iter_mut()
            .filter_map(Option::take)
            .collect()
    }

    /// `Array.prototype[Symbol.unscopables]` (ECMA-262 §23.1.3.32) for `realm`, built on first use.
    fn array_unscopables(&self, realm: RealmId) -> Value {
        let index = realm.0 as usize;
        if let Some(unscopables) = self
            .unscopables
            .borrow()
            .get(index)
            .and_then(Option::as_ref)
        {
            return unscopables.clone();
        }
        let mut data = ObjectData::default();
        data.set_prototype(Value::Null);
        for name in [
            "at",
            "copyWithin",
            "entries",
            "fill",
            "find",
            "findIndex",
            "findLast",
            "findLastIndex",
            "flat",
            "flatMap",
            "includes",
            "keys",
            "toReversed",
            "toSorted",
            "toSpliced",
            "values",
        ] {
            data.set(name, Value::Boolean(true));
        }
        let unscopables = Value::Object(Rc::new(RefCell::new(data)));
        if index < self.unscopables.borrow().len() {
            self.unscopables.borrow_mut()[index] = Some(unscopables.clone());
        }
        unscopables
    }

    /// What the materialized store says about `key` on this built-in.
    fn overridden(&self, target: &Value, key: &str) -> Overridden {
        self.overridden_key(target, PropertyKeyRef::Utf8(key))
    }

    fn overridden_key(&self, target: &Value, key: PropertyKeyRef<'_>) -> Overridden {
        let Some(identity) = intrinsic_key(target) else {
            return Overridden::Untouched;
        };
        if matches!(
            target,
            Value::Native(
                Native::PrototypeOf(
                    PrototypeTable::Symbol
                        | PrototypeTable::Array
                        | PrototypeTable::Number
                        | PrototypeTable::Boolean
                        | PrototypeTable::BigInt
                        | PrototypeTable::Promise
                        | PrototypeTable::Object
                ),
                _
            )
        ) && !self.is_materialized(target)
        {
            self.materialize(target);
        }
        let entries = self.entries.borrow();
        let Some((_, slots)) = entries.iter().find(|(held, _)| *held == identity) else {
            return Overridden::Untouched;
        };
        let data = slots;
        if let Some(property) = data.get_own_property_key(key) {
            return Overridden::Held(
                property.clone(),
                data.get_own_attributes_key(key)
                    .unwrap_or(Attributes::DEFAULT),
            );
        }
        Overridden::Absent
    }

    /// The value a read finds, or `None` to carry on down the chain the read was walking.
    ///
    /// An accessor answers `None` here and is called by [`Vm::read_property`], which is the only
    /// place that can run one: this path is `&self` and a getter is ordinary code.
    fn read(&self, target: &Value, key: &str) -> Option<Value> {
        match self.overridden(target, key) {
            Overridden::Held(Property::Value(value), _) => Some(value),
            Overridden::Held(Property::Accessor { .. }, _) | Overridden::Absent => {
                Some(Value::Undefined)
            }
            Overridden::Untouched => None,
        }
    }

    /// Whether any program has defined an accessor on any built-in.
    ///
    /// See the field: the answer guards a prototype-chain walk that would otherwise run on every
    /// read that misses a value's own store.
    fn any_accessor(&self) -> bool {
        self.accessors.get()
    }

    /// Whether this built-in still accepts new properties.
    ///
    /// An unmaterialized intrinsic is extensible by default; a materialized store carries the
    /// ordinary object extensibility bit.
    fn extensible(&self, target: &Value) -> bool {
        let Some(identity) = intrinsic_key(target) else {
            return true;
        };
        self.entries
            .borrow()
            .iter()
            .find(|(held, _)| *held == identity)
            .is_none_or(|(_, data)| data.is_extensible())
    }

    /// Close a built-in against new properties, sealing what is already there if asked.
    ///
    /// The flag lives on the realm-owned ordinary store: the shared tables are immutable, and one
    /// realm closing `Math` must not close it for another.
    fn close(&self, target: &Value, sealing: bool) {
        let Some(identity) = intrinsic_key(target) else {
            return;
        };
        self.materialize(target);
        let mut entries = self.entries.borrow_mut();
        let data = Self::data(&mut entries, identity);
        if sealing {
            data.seal();
        } else {
            data.prevent_extensions();
        }
    }

    fn install_key(
        &self,
        target: &Value,
        key: PropertyKeyRef<'_>,
        property: Property,
        attributes: Attributes,
    ) {
        let Some(identity) = intrinsic_key(target) else {
            return;
        };
        if matches!(property, Property::Accessor { .. }) {
            self.accessors.set(true);
        }
        self.materialize(target);
        let mut entries = self.entries.borrow_mut();
        let data = Self::data(&mut entries, identity);
        data.install_key(key, property, attributes);
    }

    fn remove_key(&self, target: &Value, key: PropertyKeyRef<'_>) {
        let Some(identity) = intrinsic_key(target) else {
            return;
        };
        self.materialize(target);
        let mut entries = self.entries.borrow_mut();
        let data = Self::data(&mut entries, identity);
        data.remove_key(key);
    }

    /// Complete materialized own keys in ordinary ObjectData insertion order.
    fn is_materialized(&self, target: &Value) -> bool {
        intrinsic_key(target).is_some_and(|identity| {
            self.entries
                .borrow()
                .iter()
                .any(|(key, _)| *key == identity)
        })
    }

    fn own_keys_units(&self, target: &Value) -> Option<Vec<StringUnits>> {
        let identity = intrinsic_key(target)?;
        let entries = self.entries.borrow();
        let data = &entries.iter().find(|(key, _)| *key == identity)?.1;
        Some(
            data.keys()
                .filter(|key| !is_reserved_units(key))
                .cloned()
                .collect(),
        )
    }

    fn enumerable_entries_units(&self, target: &Value) -> Vec<(StringUnits, Property)> {
        let Some(identity) = intrinsic_key(target) else {
            return Vec::new();
        };
        self.materialize(target);
        let entries = self.entries.borrow();
        let Some((_, data)) = entries.iter().find(|(held, _)| *held == identity) else {
            return Vec::new();
        };
        data.entries()
            .filter(|(key, _)| !is_reserved_units(key))
            .map(|(key, property)| (key.clone(), property.clone()))
            .collect()
    }

    fn data(
        entries: &mut Vec<(IntrinsicKey, ObjectData)>,
        identity: IntrinsicKey,
    ) -> &mut ObjectData {
        let position = entries.iter().position(|(key, _)| *key == identity);
        let position = position.unwrap_or_else(|| {
            entries.push((identity, ObjectData::default()));
            entries.len() - 1
        });
        &mut entries[position].1
    }

    fn materialize(&self, target: &Value) {
        let Some(identity) = intrinsic_key(target) else {
            return;
        };
        if self
            .entries
            .borrow()
            .iter()
            .any(|(key, _)| *key == identity)
        {
            return;
        }
        let realm = value_realm(target);
        if let Value::Native(
            Native::PrototypeOf(
                table @ (PrototypeTable::Symbol
                | PrototypeTable::Array
                | PrototypeTable::Number
                | PrototypeTable::Boolean
                | PrototypeTable::BigInt
                | PrototypeTable::Promise
                | PrototypeTable::Object),
            ),
            _,
        ) = target
        {
            let proto_id = match table {
                PrototypeTable::Symbol => kiln_builtin_surface::PrototypeId::Symbol,
                PrototypeTable::Array => kiln_builtin_surface::PrototypeId::Array,
                PrototypeTable::Number => kiln_builtin_surface::PrototypeId::Number,
                PrototypeTable::Boolean => kiln_builtin_surface::PrototypeId::Boolean,
                PrototypeTable::BigInt => kiln_builtin_surface::PrototypeId::BigInt,
                PrototypeTable::Promise => kiln_builtin_surface::PrototypeId::Promise,
                PrototypeTable::Object => kiln_builtin_surface::PrototypeId::Object,
                _ => unreachable!(),
            };
            let mut data = ObjectData::default();
            for member in kiln_builtin_surface::prototype_members(proto_id) {
                let key_str = match member.key {
                    kiln_builtin_surface::MemberKey::Named(name) => name,
                    kiln_builtin_surface::MemberKey::Symbol(sym) => sym.property_key(),
                };
                let prop = match member.binding {
                    kiln_builtin_surface::SemanticBinding::PrimitiveToString => {
                        Property::Value(Value::Native(Native::PrimitiveToString, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::PrimitiveValueOf => {
                        Property::Value(Value::Native(Native::PrimitiveValueOf, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::SymbolDescription => {
                        Property::Accessor {
                            get: Some(Value::Native(
                                Native::BuiltinAccessor(BuiltinAccessor::SymbolDescription),
                                realm,
                            )),
                            set: None,
                        }
                    }
                    kiln_builtin_surface::SemanticBinding::StringTag(tag) => {
                        Property::Value(Value::String(tag.to_owned().into()))
                    }
                    kiln_builtin_surface::SemanticBinding::SymbolToPrimitive => {
                        Property::Value(Value::Native(Native::SymbolToPrimitive, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::Constructor => {
                        let ctor = match table {
                            PrototypeTable::Symbol => Native::SymbolConstructor,
                            PrototypeTable::Array => Native::ArrayConstructor,
                            PrototypeTable::Number => Native::NumberConstructor,
                            PrototypeTable::Boolean => Native::BooleanConstructor,
                            PrototypeTable::BigInt => Native::BigIntConstructor,
                            PrototypeTable::Promise => Native::PromiseConstructor,
                            PrototypeTable::Object => Native::ObjectConstructor,
                            _ => unreachable!(),
                        };
                        Property::Value(Value::Native(ctor, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::ArrayLength => {
                        Property::Value(Value::Number(0.0))
                    }
                    kiln_builtin_surface::SemanticBinding::ArrayUnscopables => {
                        Property::Value(self.array_unscopables(realm))
                    }
                    kiln_builtin_surface::SemanticBinding::ArrayMethod(method) => {
                        Property::Value(array_method_value(method, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::NumberMethod(method) => {
                        Property::Value(number_method_value(method, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::BooleanMethod(
                        kiln_builtin_surface::BooleanMethod::ToString,
                    ) => Property::Value(Value::Native(Native::BooleanToString, realm)),
                    kiln_builtin_surface::SemanticBinding::BooleanMethod(
                        kiln_builtin_surface::BooleanMethod::ValueOf,
                    ) => Property::Value(Value::Native(Native::BooleanValueOf, realm)),
                    kiln_builtin_surface::SemanticBinding::BigIntMethod(
                        kiln_builtin_surface::BigIntMethod::ToString
                        | kiln_builtin_surface::BigIntMethod::ToLocaleString,
                    ) => Property::Value(Value::Native(Native::BigIntToString, realm)),
                    kiln_builtin_surface::SemanticBinding::BigIntMethod(
                        kiln_builtin_surface::BigIntMethod::ValueOf,
                    ) => Property::Value(Value::Native(Native::PrimitiveValueOf, realm)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Then,
                    ) => Property::Value(Value::Native(Native::PromiseThen, realm)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Catch,
                    ) => Property::Value(Value::Native(Native::PromiseCatch, realm)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Finally,
                    ) => Property::Value(Value::Native(Native::PromiseFinally, realm)),
                    kiln_builtin_surface::SemanticBinding::ObjectMethod(method) => {
                        Property::Value(object_method_value(method, realm))
                    }
                    kiln_builtin_surface::SemanticBinding::ObjectProto => Property::Accessor {
                        get: Some(Value::Native(Native::ProtoGetter, realm)),
                        set: Some(Value::Native(Native::ProtoSetter, realm)),
                    },
                };
                let attrs = Attributes {
                    writable: member.attributes.writable,
                    enumerable: member.attributes.enumerable,
                    configurable: member.attributes.configurable,
                };
                data.install_key(PropertyKeyRef::Utf8(key_str), prop, attrs);
            }
            data.set_prototype(prototype_of(target));
            let mut entries = self.entries.borrow_mut();
            if let Some((_, slot)) = entries.iter_mut().find(|(key, _)| *key == identity) {
                *slot = data;
            } else {
                entries.push((identity, data));
            }
            return;
        }
        let mut keys: Vec<String> = match target {
            Value::Native(Native::PrototypeOf(table), _) => intrinsic_prototype_entries(*table)
                .into_iter()
                .map(|(key, _)| key)
                .collect(),
            _ => Vec::new(),
        };
        if !matches!(target, Value::Native(Native::PrototypeOf(_), _)) {
            if intrinsic_identity(target).is_some() {
                keys.extend(["length".into(), "name".into()]);
            }
            if intrinsic_prototype_in(self, target).is_some() {
                keys.push("prototype".into());
            }
            keys.extend(intrinsic_extra_property_names(target));
            keys.extend(
                intrinsic_static_property_names(target)
                    .iter()
                    .map(|key| (*key).to_owned()),
            );
        }
        for symbol in WellKnown::ALL {
            let key = if matches!(target, Value::Native(Native::SymbolConstructor, _)) {
                symbol.js_name()
            } else {
                symbol.property_key()
            };
            if !keys.iter().any(|existing| existing == key) {
                keys.push(key.to_owned());
            }
        }
        let mut data = ObjectData::default();
        for key in keys {
            if let Some(attributes) = tabulated_attributes(self, target, &key)
                && let Some(property) = tabulated_property(self, target, &key)
            {
                data.install_key(
                    PropertyKeyRef::Utf8(&key),
                    retag_intrinsic_property(property, realm),
                    attributes,
                );
            }
        }
        data.set_prototype(prototype_of(target));
        let mut entries = self.entries.borrow_mut();
        if let Some((_, slot)) = entries.iter_mut().find(|(key, _)| *key == identity) {
            *slot = data;
        } else {
            entries.push((identity, data));
        }
    }
}

/// What a built-in inherits, for a read that has got past its own properties.
///
/// A namespace and a method table are ordinary objects and reach `Object.prototype`; everything
/// else here is callable and reaches `Function.prototype` first. The distinction matters only
/// after a deletion -- a program that removed `Function.prototype.call` must not find it again
/// one link up -- which is why a table goes straight to the object methods.
fn native_inherited_property(intrinsics: &Intrinsics, target: &Value, name: &str) -> Value {
    let realm = value_realm(target);
    match target {
        // NativeError constructors inherit static properties from Error. Keep this separate from
        // the own-property table: `TypeError.isError` is inherited, so it must not appear in
        // TypeError's own property names or descriptor.
        Value::Native(Native::Error(kind), _) if *kind != ErrorKind::Error => {
            match intrinsics.overridden(
                &Value::Native(Native::Error(ErrorKind::Error), realm),
                name,
            ) {
                Overridden::Held(Property::Value(value), _) => value,
                Overridden::Held(Property::Accessor { .. }, _) | Overridden::Absent => {
                    function_property(intrinsics, name, realm)
                }
                Overridden::Untouched => Native::Error(ErrorKind::Error)
                    .property(name)
                    .unwrap_or_else(|| function_property(intrinsics, name, realm)),
            }
        }
        Value::Native(Native::PrototypeOf(PrototypeTable::TypedArrayFor(_)), _) => match table_step(
            intrinsics,
            PrototypeTable::TypedArray,
            name,
            Native::PrototypeOf(PrototypeTable::TypedArray)
                .property(name)
                .unwrap_or(Value::Undefined),
        realm) {
            Value::Undefined => inherited_object_property(intrinsics, name, realm),
            found => found,
        },
        Value::Native(Native::PrototypeOf(_) | Native::Math | Native::Json | Native::Reflect, _)
        // The `Intl` namespace and the six prototypes are ordinary objects, so they inherit
        // from `Object.prototype` rather than from `Function.prototype`. An `Intl` instance
        // does too: its own methods are found first, and everything else comes from there.
        | Value::Native(Native::Intl(intl::Op::Namespace | intl::Op::Prototype(_)), _)
        | Value::Intl(_) => inherited_object_property(intrinsics, name, realm),
        _ => function_property(intrinsics, name, realm),
    }
}

/// One step of an implicit prototype chain, with the realm's store consulted first.
///
/// A value whose chain reaches a built-in's method table has no object to walk into: the table
/// is a `match`, and the step is a call to it. That is where a property the program put on
/// `Object.prototype` or `Array.prototype` has to be found, or the write would land somewhere no
/// read could reach. `Undefined` continues down the chain, which is what makes a *deleted* table
/// entry fall through to the next table rather than shadowing it with nothing.
fn table_step(
    intrinsics: &Intrinsics,
    table: PrototypeTable,
    name: &str,
    tabulated: Value,
    realm: RealmId,
) -> Value {
    intrinsics
        .read(&Value::Native(Native::PrototypeOf(table), realm), name)
        .unwrap_or_else(|| {
            if matches!(table, PrototypeTable::Array)
                && name == WellKnown::Unscopables.property_key()
            {
                intrinsics.array_unscopables(realm)
            } else {
                in_realm(tabulated, realm)
            }
        })
}

