/// The string-keyed members each built-in prototype lists.
///
/// Each list is a `const` built through [`intrinsic_members::NamedMembers`], which refuses a
/// symbol's internal `@@` spelling *while the compiler is building it*. That is not decoration:
/// putting `"@@hasInstance"` in one of these lists once leaked the internal spelling of
/// `Symbol.hasInstance` into every property listing in the realm, and nothing about the change
/// looked wrong. Now it does not build.
fn intrinsic_prototype_method_names(table: PrototypeTable) -> &'static [&'static str] {
    match table {
        // A concrete view's prototype carries only what differs between the views: its element
        // width, and -- for the byte view alone -- the four conversions to and from text.
        PrototypeTable::TypedArrayFor(kind) => match kind {
            TypedKind::Uint8 => UINT8_MEMBERS.names(),
            _ => TYPED_ARRAY_VIEW_MEMBERS.names(),
        },
        PrototypeTable::Array | PrototypeTable::TypedArray => ARRAY_MEMBERS.names(),
        PrototypeTable::String => STRING_MEMBERS.names(),
        PrototypeTable::Object
        | PrototypeTable::Number
        | PrototypeTable::Boolean
        | PrototypeTable::BigInt
        | PrototypeTable::Promise
        | PrototypeTable::Symbol => &[],
        // `caller` and `arguments` are the restricted accessor pair
        // `AddRestrictedFunctionProperties` installs here, and they are own properties of this
        // object -- which is what makes every function that inherits from it throw on a read.
        PrototypeTable::Function => FUNCTION_MEMBERS.names(),
        PrototypeTable::RegExp => REG_EXP_MEMBERS.names(),
        PrototypeTable::Date => DATE_MEMBERS.names(),
        PrototypeTable::ArrayBuffer => ARRAY_BUFFER_MEMBERS.names(),
        PrototypeTable::SharedArrayBuffer => SHARED_ARRAY_BUFFER_MEMBERS.names(),
        PrototypeTable::DataView => DATA_VIEW_MEMBERS.names(),
        PrototypeTable::Iterator => ITERATOR_MEMBERS.names(),
        PrototypeTable::Generator | PrototypeTable::AsyncGenerator => GENERATOR_MEMBERS.names(),
        PrototypeTable::IteratorFor(_) => BUILT_IN_ITERATOR_MEMBERS.names(),
        PrototypeTable::Map => MAP_MEMBERS.names(),
        PrototypeTable::Set => SET_MEMBERS.names(),
        PrototypeTable::WeakMap => WEAK_MAP_MEMBERS.names(),
        PrototypeTable::WeakSet => WEAK_SET_MEMBERS.names(),
        PrototypeTable::WeakRef => WEAK_REF_MEMBERS.names(),
        PrototypeTable::ShadowRealm => SHADOW_REALM_MEMBERS.names(),
        PrototypeTable::DisposableStack => DISPOSABLE_STACK_MEMBERS.names(),
        PrototypeTable::AsyncDisposableStack => ASYNC_DISPOSABLE_STACK_MEMBERS.names(),
        PrototypeTable::FinalizationRegistry => FINALIZATION_REGISTRY_MEMBERS.names(),
        PrototypeTable::EventEmitter => EVENT_EMITTER_MEMBERS.names(),
        PrototypeTable::Readable => stream::readable_prototype_member_names(),
        PrototypeTable::Writable => WRITABLE_MEMBERS.names(),
        PrototypeTable::Console => CONSOLE_MEMBERS.names(),
        PrototypeTable::AsyncIterator => &[],
    }
}

fn intrinsic_prototype_entries(table: PrototypeTable) -> Vec<(String, Property)> {
    if let Some(proto_id) = match table {
        PrototypeTable::Symbol => Some(kiln_builtin_surface::PrototypeId::Symbol),
        PrototypeTable::Array => Some(kiln_builtin_surface::PrototypeId::Array),
        PrototypeTable::Number => Some(kiln_builtin_surface::PrototypeId::Number),
        PrototypeTable::Boolean => Some(kiln_builtin_surface::PrototypeId::Boolean),
        PrototypeTable::BigInt => Some(kiln_builtin_surface::PrototypeId::BigInt),
        PrototypeTable::Promise => Some(kiln_builtin_surface::PrototypeId::Promise),
        PrototypeTable::Object => Some(kiln_builtin_surface::PrototypeId::Object),
        _ => None,
    } {
        return kiln_builtin_surface::prototype_members(proto_id)
            .filter_map(|member| {
                let name = match member.key {
                    kiln_builtin_surface::MemberKey::Named(name) => name,
                    kiln_builtin_surface::MemberKey::Symbol(_) => return None,
                };
                let prop = match member.binding {
                    kiln_builtin_surface::SemanticBinding::PrimitiveToString => {
                        Property::Value(Value::Native(Native::PrimitiveToString, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::PrimitiveValueOf => {
                        Property::Value(Value::Native(Native::PrimitiveValueOf, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::SymbolDescription => {
                        Property::Accessor {
                            get: Some(Value::Native(
                                Native::BuiltinAccessor(BuiltinAccessor::SymbolDescription),
                                RealmId::PRIMARY,
                            )),
                            set: None,
                        }
                    }
                    kiln_builtin_surface::SemanticBinding::Constructor => {
                        let ctor = match table {
                            PrototypeTable::Symbol => Native::SymbolConstructor,
                            PrototypeTable::Array => Native::ArrayConstructor,
                            PrototypeTable::Number => Native::NumberConstructor,
                            PrototypeTable::Boolean => Native::BooleanConstructor,
                            PrototypeTable::BigInt => Native::BigIntConstructor,
                            PrototypeTable::Promise => Native::PromiseConstructor,
                            PrototypeTable::Object => Native::ObjectConstructor,
                            _ => unreachable!(),
                        };
                        Property::Value(Value::Native(ctor, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::ArrayLength => {
                        Property::Value(Value::Number(0.0))
                    }
                    kiln_builtin_surface::SemanticBinding::ArrayMethod(method) => {
                        Property::Value(array_method_value(method, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::NumberMethod(method) => {
                        Property::Value(number_method_value(method, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::BooleanMethod(
                        kiln_builtin_surface::BooleanMethod::ToString,
                    ) => Property::Value(Value::Native(Native::BooleanToString, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::BooleanMethod(
                        kiln_builtin_surface::BooleanMethod::ValueOf,
                    ) => Property::Value(Value::Native(Native::BooleanValueOf, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::BigIntMethod(
                        kiln_builtin_surface::BigIntMethod::ToString
                        | kiln_builtin_surface::BigIntMethod::ToLocaleString,
                    ) => Property::Value(Value::Native(Native::BigIntToString, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::BigIntMethod(
                        kiln_builtin_surface::BigIntMethod::ValueOf,
                    ) => Property::Value(Value::Native(Native::PrimitiveValueOf, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Then,
                    ) => Property::Value(Value::Native(Native::PromiseThen, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Catch,
                    ) => Property::Value(Value::Native(Native::PromiseCatch, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::PromiseMethod(
                        kiln_builtin_surface::PromiseMethod::Finally,
                    ) => Property::Value(Value::Native(Native::PromiseFinally, RealmId::PRIMARY)),
                    kiln_builtin_surface::SemanticBinding::ObjectMethod(method) => {
                        Property::Value(object_method_value(method, RealmId::PRIMARY))
                    }
                    kiln_builtin_surface::SemanticBinding::ObjectProto => Property::Accessor {
                        get: Some(Value::Native(Native::ProtoGetter, RealmId::PRIMARY)),
                        set: Some(Value::Native(Native::ProtoSetter, RealmId::PRIMARY)),
                    },
                    _ => return None,
                };
                Some((name.to_owned(), prop))
            })
            .collect();
    }
    let target = Value::Native(Native::PrototypeOf(table), RealmId::PRIMARY);
    let mut names = vec!["constructor"];
    if matches!(table, PrototypeTable::String) {
        names.push("length");
    }
    names
        .into_iter()
        .chain(intrinsic_prototype_method_names(table).iter().copied())
        .chain(intrinsic_members::accessor_keys(table))
        .filter_map(|name| {
            if let Some(value) = string_exotic(&target, name) {
                return Some((name.to_owned(), Property::Value(value)));
            }
            if let Some(accessor) = intrinsic_accessor(&target, name) {
                return Some((name.to_owned(), accessor));
            }
            match Native::PrototypeOf(table).property(name) {
                Some(Value::Undefined) | None => None,
                Some(value) => Some((name.to_owned(), Property::Value(value))),
            }
        })
        .collect()
}

/// The getter a built-in publishes under one name, or `None` for a name that is not an accessor.
///
/// One place, so that reading the property, describing it and listing it cannot disagree about
/// which of the two shapes it is -- a disagreement `verifyProperty` sees immediately.
fn intrinsic_accessor(target: &Value, key: &str) -> Option<Property> {
    let realm = value_realm(target);
    match target {
        Value::Native(Native::PrototypeOf(PrototypeTable::RegExp), _) => {
            RegExpAccessor::named(key).map(|accessor| Property::Accessor {
                get: Some(Value::Native(Native::RegExpAccessor(accessor), realm)),
                // No setter half at all, which is what makes `re.global = true` silently do
                // nothing rather than store a shadowing property.
                set: None,
            })
        }
        // Everything a built-in prototype publishes about its instances: `byteLength`, `size`,
        // and their eleven siblings. One table, so that reading the property, describing it and
        // listing it cannot disagree.
        Value::Native(Native::PrototypeOf(table), _)
            if prototype_accessor(*table, key).is_some() =>
        {
            prototype_accessor(*table, key).map(|accessor| Property::Accessor {
                get: Some(Value::Native(Native::BuiltinAccessor(accessor), realm)),
                set: None,
            })
        }
        // Every field one of the eight `Temporal` types publishes -- `blank`, `dayOfWeek`,
        // `epochNanoseconds` and their thirty-seven siblings. The language spells all of them as
        // getters on the prototype rather than as data properties on the instance, and the
        // difference is what a program sees: `Temporal.Duration.prototype.blank` is not a flag no
        // duration has, it is a getter whose brand check refuses the prototype.
        Value::Native(Native::Temporal(temporal::Op::Prototype(kind)), _) => {
            temporal::prototype_accessor(*kind, key).map(|field| Property::Accessor {
                get: Some(Value::Native(
                    Native::Temporal(temporal::Op::Accessor(*kind, field)),
                    realm,
                )),
                // No setter half: `duration.blank = true` writes nothing, exactly as
                // `re.global = true` does.
                set: None,
            })
        }
        // `Symbol.species` is one accessor defined eight times over, always the same: it
        // answers its own receiver.
        Value::Native(native, _)
            if defines_species(*native) && key == WellKnown::Species.property_key() =>
        {
            Some(Property::Accessor {
                get: Some(Value::Native(
                    Native::BuiltinAccessor(BuiltinAccessor::Species),
                    realm,
                )),
                set: None,
            })
        }
        // The restricted pair. Both halves are the *same* function, and a program can compare
        // them, so both spell it the same way.
        Value::Native(Native::PrototypeOf(PrototypeTable::Function), _)
            if matches!(key, "caller" | "arguments") =>
        {
            Some(Property::Accessor {
                get: Some(Value::Native(Native::ThrowTypeError, realm)),
                set: Some(Value::Native(Native::ThrowTypeError, realm)),
            })
        }
        Value::Native(Native::PrototypeOf(PrototypeTable::Object), _) if key == "__proto__" => {
            Some(Property::Accessor {
                get: Some(Value::Native(Native::ProtoGetter, realm)),
                set: Some(Value::Native(Native::ProtoSetter, realm)),
            })
        }
        // `%TypedArray%.prototype[Symbol.toStringTag]` is an accessor: it reports the concrete
        // view name from its receiver and returns undefined for an incompatible receiver. Real
        // serializers capture this getter once and call it as their typed-array brand check.
        Value::Native(Native::PrototypeOf(PrototypeTable::TypedArray), _)
            if key == WellKnown::ToStringTag.property_key() =>
        {
            Some(Property::Accessor {
                get: Some(Value::Native(Native::TypedArrayToStringTag, realm)),
                set: None,
            })
        }
        _ => None,
    }
}

/// The own, program-visible keys of a value, in insertion order.
fn own_property_names_units(intrinsics: &Intrinsics, target: &Value) -> Vec<StringUnits> {
    let from_store = |data: &ObjectData| {
        data.keys()
            .filter(|key| !is_reserved_units(key))
            .cloned()
            .collect::<Vec<_>>()
    };
    match target {
        Value::Object(object) => {
            let mut keys = match wrapped_primitive(target) {
                Some(Value::String(text)) => (0..text.unit_len())
                    .map(|index| StringUnits::from(index.to_string()))
                    .collect(),
                _ => Vec::new(),
            };
            keys.extend(from_store(&object.borrow()));
            if matches!(wrapped_primitive(target), Some(Value::String(_))) {
                keys.push(StringUnits::from("length"));
            }
            keys
        }
        Value::Function(closure) => {
            let mut keys = from_store(&closure.properties.borrow());
            if has_prototype_property(closure) {
                let statics = keys.split_off(2.min(keys.len()));
                keys.push(StringUnits::from("prototype"));
                keys.extend(statics);
            }
            keys
        }
        Value::Bound(bound) => [StringUnits::from("length"), StringUnits::from("name")]
            .into_iter()
            .chain(from_store(&bound.properties.borrow()))
            .collect(),
        Value::Array(items) => {
            let mut keys = items
                .borrow()
                .iter()
                .enumerate()
                .filter(|(_, item)| !matches!(item, Value::Native(Native::Hole, _)))
                .map(|(index, _)| StringUnits::from(index.to_string()))
                .collect::<Vec<_>>();
            keys.push(StringUnits::from("length"));
            keys.extend(from_store(&items.properties.borrow()));
            keys
        }
        Value::TypedArray(view) => (0..view.len())
            .map(|index| StringUnits::from(index.to_string()))
            .chain(from_store(&view.properties.borrow()))
            .collect(),
        other if exotic_properties(other).is_some() => exotic_properties(target)
            .map(|store| from_store(&store.borrow()))
            .unwrap_or_default(),
        _ => own_property_keys_units(intrinsics, target),
    }
}

fn own_property_keys(intrinsics: &Intrinsics, target: &Value) -> Vec<String> {
    own_property_keys_units(intrinsics, target)
        .into_iter()
        .map(|key| key.to_lossy_string())
        .collect()
}

/// `[[OwnPropertyKeys]]` in the exact UTF-16 key representation.
///
/// The scalar wrapper above exists only for display-oriented helpers. VM reflection, proxy
/// invariants, and descriptor walks use this function so a lone surrogate remains the same
/// property from the store through the trap and back into the operation.
fn own_property_keys_units(intrinsics: &Intrinsics, target: &Value) -> Vec<StringUnits> {
    if matches!(target, Value::Native(_, _) | Value::Callback(_, _)) {
        intrinsics.materialize(target);
    }
    let from_object = |data: &ObjectData| -> Vec<StringUnits> {
        data.keys()
            .filter(|key| !is_reserved_units(key))
            .cloned()
            .collect()
    };
    match target {
        // A String wrapper lists its characters first, in index order, and then whatever the
        // program put on the box -- the order the specification's `OrdinaryOwnPropertyKeys`
        // gives, where integer indices always precede the rest.
        Value::Object(object) if matches!(wrapped_primitive(target), Some(Value::String(_))) => {
            let Some(Value::String(text)) = wrapped_primitive(target) else {
                unreachable!("checked by the guard");
            };
            let mut keys: Vec<StringUnits> = (0..text.unit_len())
                .map(|index| StringUnits::from(index.to_string()))
                .collect();
            keys.extend(from_object(&object.borrow()));
            keys.push(StringUnits::from("length"));
            keys
        }
        Value::Bound(bound) => {
            let mut keys = vec![StringUnits::from("length"), StringUnits::from("name")];
            keys.extend(from_object(&bound.properties.borrow()));
            keys
        }
        Value::Object(object) => from_object(&object.borrow()),
        Value::Function(closure) => {
            let mut keys = from_object(&closure.properties.borrow());
            // After `length` and `name`, which the closure stores, and before whatever the
            // program hung on the function itself -- the order the specification lists them in.
            if has_prototype_property(closure) {
                let statics = keys.split_off(2.min(keys.len()));
                keys.push(StringUnits::from("prototype"));
                keys.extend(statics);
            }
            keys
        }
        Value::Native(Native::PrototypeOf(_table), _) => {
            intrinsics.own_keys_units(target).unwrap_or_default()
        }
        Value::Native(_, _)
        | Value::Callback(_, _)
        | Value::Settler(..)
        | Value::Capability(..)
        | Value::Element(_) => {
            let mut keys = intrinsics.own_keys_units(target).unwrap_or_default();
            // Promise combinators and capability machinery create these runtime callables rather
            // than intrinsics, so they have no materialized store. Their identity slots are still
            // own properties, and CreateBuiltinFunction installs them in length/name order. Keep
            // that order visible to OrdinaryOwnPropertyKeys.
            if matches!(
                target,
                Value::Settler(..) | Value::Capability(..) | Value::Element(_)
            ) && intrinsic_identity(target).is_some()
            {
                keys.splice(
                    0..0,
                    [StringUnits::from("length"), StringUnits::from("name")],
                );
            }
            keys
        }
        Value::Array(items) => {
            // An accessor leaves a hole in the dense storage, so the indices that are really
            // there are the union of the two: the walk below would otherwise list an array's
            // getters as absent.
            let mut indices: Vec<usize> = items
                .borrow()
                .iter()
                .enumerate()
                .filter(|(_, item)| !matches!(item, Value::Native(Native::Hole, _)))
                .map(|(index, _)| index)
                .collect();
            let defined: Vec<usize> = items
                .elements
                .borrow()
                .iter()
                .map(|entry| entry.index)
                .collect();
            for index in defined {
                if !indices.contains(&index) {
                    indices.push(index);
                }
            }
            indices.sort_unstable();
            let mut keys: Vec<StringUnits> = indices
                .iter()
                .map(|index| StringUnits::from(index.to_string()))
                .collect();
            // After the indices and before whatever the program hung on the array: `length` is
            // an own property created with the array, and the specification lists integer
            // indices first and everything else in creation order.
            keys.push(StringUnits::from("length"));
            keys.extend(from_object(&items.properties.borrow()));
            keys
        }
        // The elements first, in index order, and then whatever the program hung on the view --
        // the order `OrdinaryOwnPropertyKeys` gives, where integer indices always precede the
        // rest.
        Value::TypedArray(view) => {
            let mut keys: Vec<StringUnits> = (0..view.len())
                .map(|index| StringUnits::from(index.to_string()))
                .collect();
            keys.extend(from_object(&view.properties.borrow()));
            keys
        }
        other if exotic_properties(other).is_some() => exotic_properties(target)
            .map(|store| from_object(&store.borrow()))
            .unwrap_or_default(),
        _ => Vec::new(),
    }
}

/// Names supplied by a native constructor/namespace's compact property table.
///
/// Native values do not carry an `ObjectData`, so `own_property_keys` cannot discover these by
/// walking a store. Keep this candidate list next to the own-key walk and filter it through
/// `own_attributes`: a name is included only when the same property machinery can describe it.
fn intrinsic_extra_property_names(target: &Value) -> Vec<String> {
    match target {
        Value::Native(Native::Temporal(op), _) => match op {
            temporal::Op::Prototype(kind) => temporal::property_names(*op)
                .iter()
                .chain(temporal::prototype_accessor_names(*kind).iter())
                .map(|name| (*name).to_owned())
                .collect(),
            _ => temporal::property_names(*op)
                .iter()
                .map(|name| (*name).to_owned())
                .collect(),
        },
        Value::Native(Native::Intl(op), _) => intl::property_names(*op)
            .iter()
            .map(|name| (*name).to_owned())
            .collect(),
        Value::Native(native, _) => native
            .own_property_rows()
            .iter()
            .map(|(name, _)| (*name).to_owned())
            .collect(),
        _ => Vec::new(),
    }
}

fn intrinsic_static_property_names(target: &Value) -> &'static [&'static str] {
    let tabulated = intrinsic_tabulated_property_names(target);
    if !tabulated.is_empty() {
        return tabulated;
    }
    // A Node builtin namespace publishes what the shared ABI table says it publishes, which is
    // the same list the ESM projection binds. Without it the namespace had *no* own keys at all:
    // `Object.keys(require("path"))` was 0 against node's 17, so every `{ ...require("path") }`
    // re-export shim a bundler emits produced an empty object while every individual member
    // still read correctly -- a silent hole rather than a failure.
    //
    // Consulted only where the tables above say nothing, because `node:buffer` is *both* the
    // module and the `Buffer` constructor here, and the constructor's statics are the answer
    // that arm was written to give.
    if let Value::Native(native, _) = target
        && let Some(specifier) = node_builtin_specifier(*native)
        && let Some(exports) = kiln_builtins::builtin_exports_for_specifier(specifier)
    {
        return exports;
    }
    &[]
}

/// The static members a built-in carries, out of the table both engines read.
///
/// ONE TABLE, TWO EMITTERS (ADR 0043). The member names used to be written out here and again as
/// `kiln_c99_same_name` chains in `kiln-backend-c`'s emitted C, and nothing compared the two. They
/// drifted, silently, until an npm bundle read a member one of them lacked: `Number` had fifteen
/// statics here and five there, and `Number.MAX_VALUE` is the first property a bundled `zod`
/// reads, so its absence refused the whole module.
///
/// Every arm below binds a `const`, so [`kiln_builtin_surface::members`] runs at compile time and
/// a global this interpreter names but the shared table does not declare fails to build. What the
/// arm still chooses is which built-in it *is* -- that is this interpreter's own knowledge of its
/// `Native` values, and the shared table has no business holding it.
fn intrinsic_tabulated_property_names(target: &Value) -> &'static [&'static str] {
    match target {
        Value::Native(Native::ArrayConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Array");
            MEMBERS
        }
        Value::Native(Native::ObjectConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Object");
            MEMBERS
        }
        Value::Native(Native::StringConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("String");
            MEMBERS
        }
        Value::Native(Native::NumberConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Number");
            MEMBERS
        }
        Value::Native(Native::DateConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Date");
            MEMBERS
        }
        Value::Native(Native::PromiseConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Promise");
            MEMBERS
        }
        Value::Native(Native::Json, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("JSON");
            MEMBERS
        }
        Value::Native(Native::Reflect, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Reflect");
            MEMBERS
        }
        Value::Native(Native::ProxyConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Proxy");
            MEMBERS
        }
        Value::Native(Native::ArrayBufferConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("ArrayBuffer");
            MEMBERS
        }
        Value::Native(Native::RegExpConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("RegExp");
            MEMBERS
        }
        Value::Native(Native::Error(ErrorKind::Error), _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Error");
            MEMBERS
        }
        Value::Native(Native::BigIntConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("BigInt");
            MEMBERS
        }
        Value::Native(Native::MapConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Map");
            MEMBERS
        }
        Value::Native(Native::SymbolConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Symbol");
            MEMBERS
        }
        Value::Native(Native::IteratorConstructor, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Iterator");
            MEMBERS
        }
        // The *global* `Buffer` alone. `node:buffer` is both this module and that constructor
        // here, and answering the constructor's list for it published eight names where the
        // shared ABI declares ten -- so the two engines disagreed about what
        // `Object.keys(require("node:buffer"))` is, and `Buffer` and `default` were names the
        // native projection published and this one did not. The namespace falls through to the
        // Node ABI arm below, which is the list both engines bind.
        Value::Native(Native::NodeBufferGlobal, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Buffer");
            MEMBERS
        }
        Value::Native(Native::Atomics, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Atomics");
            MEMBERS
        }
        Value::Native(Native::Math, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("Math");
            MEMBERS
        }
        Value::Native(Native::TypedArrayIntrinsic, _) => {
            const MEMBERS: &[&str] = kiln_builtin_surface::members("%TypedArray%");
            MEMBERS
        }
        Value::Native(Native::TypedArrayConstructor(kind), _) => match kind {
            // A view's elements are bytes only here, which is why these two are `Uint8Array`'s
            // alone and not `%TypedArray%`'s.
            TypedKind::Uint8 => {
                const MEMBERS: &[&str] = kiln_builtin_surface::members("Uint8Array");
                MEMBERS
            }
            _ => {
                const MEMBERS: &[&str] = kiln_builtin_surface::members("%TypedArrayConstructor%");
                MEMBERS
            }
        },
        _ => &[],
    }
}

/// The own-key walk used by operations whose specification includes symbol keys.
///
/// Most reflection helpers in this interpreter intentionally return only names because the
/// current compact symbol representation cannot reconstruct a `Symbol` value from its reserved
/// slot. Internal algorithms do not need that reconstruction: preserving the slot is enough to
/// read and define the same symbol-keyed property without losing its identity.
/// Whether a reserved store key names a symbol-keyed property rather than an internal slot.
///
/// The two share the `@@` prefix, which is what made reflection unable to tell them apart and so
/// report neither. A key is a symbol's exactly when a well-known symbol claims it or it carries
/// a `Symbol()` serial; everything else -- `@@entries`, `@@trace`, `@@disposeEntries`,
/// `@@private:x` -- is the machine's own bookkeeping and is not a property of the object at all.
fn is_symbol_key(key: &str) -> bool {
    WellKnown::from_property_key(key).is_some() || Symbol::serial_in_key(key).is_some()
}

/// The exact-key counterpart to [`symbol::is_reserved`]. Internal slots and symbol keys are
/// ASCII by construction, so a malformed UTF-16 key cannot become one through replacement.
fn is_reserved_units(key: &StringUnits) -> bool {
    if key.unit_len() < 2
        || key.unit_at(0) != Some(b'@' as u16)
        || key.unit_at(1) != Some(b'@' as u16)
    {
        return false;
    }
    PropertyKeyRef::Units(key)
        .known_ascii()
        .is_some_and(|name| symbol::is_reserved(name.as_ref()))
}

fn is_symbol_key_units(key: &StringUnits) -> bool {
    PropertyKeyRef::Units(key)
        .known_ascii()
        .is_some_and(|name| is_symbol_key(name.as_ref()))
}

/// `OrdinaryOwnPropertyKeys`: the string keys, then the symbol keys, each in insertion order.
///
/// Distinct from [`own_property_keys_including_symbols`], which hands back every reserved slot
/// and is what an internal algorithm wants; this is the list a *program* is allowed to see.
#[cfg(test)]
fn own_property_keys_with_symbols(intrinsics: &Intrinsics, target: &Value) -> Vec<String> {
    own_property_keys_with_symbols_units(intrinsics, target)
        .into_iter()
        .map(|key| key.to_lossy_string())
        .collect()
}

#[cfg(test)]
fn own_property_keys_including_symbols(intrinsics: &Intrinsics, target: &Value) -> Vec<String> {
    own_property_keys_including_symbols_units(intrinsics, target)
        .into_iter()
        .map(|key| key.to_lossy_string())
        .collect()
}

fn own_property_keys_with_symbols_units(
    intrinsics: &Intrinsics,
    target: &Value,
) -> Vec<StringUnits> {
    own_property_keys_including_symbols_units(intrinsics, target)
        .into_iter()
        .filter(|key| !is_reserved_units(key) || is_symbol_key_units(key))
        .collect()
}

fn own_property_keys_including_symbols_units(
    intrinsics: &Intrinsics,
    target: &Value,
) -> Vec<StringUnits> {
    let mut keys = own_property_keys_units(intrinsics, target);
    // Ordinary reflection intentionally hides symbol slots, but internal operations such as
    // proxy invariants and `Object.defineProperties` consume the full own-key list. Append the
    // reserved slots after the ordinary names, preserving each store's insertion order.
    let stored = match target {
        Value::Object(object) => object.borrow().keys().cloned().collect(),
        Value::Function(closure) => closure.properties.borrow().keys().cloned().collect(),
        Value::Bound(bound) => bound.properties.borrow().keys().cloned().collect(),
        Value::Array(items) => items.properties.borrow().keys().cloned().collect(),

        other if exotic_properties(other).is_some() => exotic_properties(target)
            .map(|store| store.borrow().keys().cloned().collect())
            .unwrap_or_default(),
        Value::Native(_, _)
        | Value::Callback(_, _)
        | Value::Settler(..)
        | Value::Capability(..)
        | Value::Element(_) => intrinsic_key(target)
            .and_then(|identity| {
                intrinsics.entries.borrow().iter().find_map(|(held, data)| {
                    (*held == identity).then(|| data.keys().cloned().collect())
                })
            })
            .unwrap_or_default(),
        _ => Vec::new(),
    };
    keys.extend(stored);
    // A built-in's symbol-keyed members. They are answered by the value tables and listed by
    // nothing, so `Object.getOwnPropertySymbols(Date.prototype)` was `[]` where every other
    // engine reports `Symbol.toPrimitive` -- the property read correctly, described correctly,
    // and did not exist as far as reflection was concerned.
    //
    // Derived by asking the table for each well-known symbol rather than from a list of which
    // ones each built-in has: such a list is a second place to describe a member, and the whole
    // point here is that there is one. `WellKnown::ALL` is itself compiler-checked, so a new
    // symbol cannot be missed. This is deliberately *not* in `own_property_keys`, which
    // `Object.getOwnPropertyNames` reads unfiltered -- putting a reserved spelling there is
    // exactly the leak that cost 838 rows.
    if matches!(target, Value::Native(_, _)) && !intrinsics.is_materialized(target) {
        let Value::Native(native, _) = target else {
            unreachable!("checked by the guard");
        };
        for symbol in WellKnown::ALL {
            let key = symbol.property_key();
            // An accessor as well as a value: `%TypedArray%.prototype[@@toStringTag]` is a
            // getter, so asking the value tables alone left it readable, describable, and
            // absent from `getOwnPropertySymbols`.
            let published = !matches!(native.property(key), None | Some(Value::Undefined))
                || intrinsic_accessor(target, key).is_some()
                || machine_accessor(target, key).is_some()
                || (matches!(native, Native::PrototypeOf(PrototypeTable::Array))
                    && key == WellKnown::Unscopables.property_key());
            if published {
                keys.push(StringUnits::from(key));
            }
        }
    }
    // A derived key such as an array's `length` may also be present in its store. The target's
    // own-key operation cannot return duplicates, so preserve the first occurrence from the
    // specification order and discard later copies.
    let mut stable = Vec::with_capacity(keys.len());
    for key in keys {
        if !stable.iter().any(|listed| listed == &key) {
            stable.push(key);
        }
    }
    stable
}

/// The three flags an own property carries, or `None` when there is no such own property.
///
/// The one shape without a slot of its own is an array element: it lives in the dense storage,
/// which has room for a value and nothing else, so the only thing that can lock one down is
/// freezing the array it belongs to.
fn own_attributes(intrinsics: &Intrinsics, target: &Value, key: &str) -> Option<Attributes> {
    own_attributes_key(intrinsics, target, PropertyKeyRef::Utf8(key))
}

fn own_attributes_key(
    intrinsics: &Intrinsics,
    target: &Value,
    key: PropertyKeyRef<'_>,
) -> Option<Attributes> {
    match target {
        Value::Object(object) => object.borrow().get_own_attributes_key(key).or_else(|| {
            // A String wrapper's own characters, which no store holds: they are derived from the
            // boxed string and are locked, exactly as a string primitive's are.
            string_exotic_key(target, key).is_some().then(|| {
                if key.matches_ascii("length") {
                    Attributes::NONE
                } else {
                    Attributes {
                        writable: false,
                        enumerable: true,
                        configurable: false,
                    }
                }
            })
        }),
        Value::Function(closure) => closure
            .properties
            .borrow()
            .get_own_attributes_key(key)
            // `prototype` is the one own property a function keeps outside its property store:
            // it lives in a slot of its own so that `new` and a read of `f.prototype` cannot
            // disagree about which object instances link to. It is still an own property, and a
            // locked one -- a program may replace the object, never remove the slot.
            .or_else(|| {
                (key.matches_ascii("prototype") && has_prototype_property(closure)).then_some(
                    Attributes {
                        writable: true,
                        enumerable: false,
                        configurable: false,
                    },
                )
            }),
        Value::Bound(bound) => bound
            .properties
            .borrow()
            .get_own_attributes_key(key)
            .or_else(|| tabulated_attributes_key(intrinsics, target, key)),
        Value::Array(items) if key.matches_ascii("length") => Some(Attributes {
            writable: items.length_writable.get(),
            enumerable: false,
            configurable: false,
        }),
        Value::Array(items) => match array_index_key(key) {
            Some(index) => {
                let frozen = items.properties.borrow().is_frozen();
                // A definition the program made wins over the ordinary flags, and freezing wins
                // over both: a frozen array's elements are locked whatever they were defined as.
                if let Some(entry) = array_exotic_element(items, index) {
                    return Some(if frozen {
                        Attributes {
                            writable: false,
                            enumerable: entry.attributes.enumerable,
                            configurable: false,
                        }
                    } else {
                        entry.attributes
                    });
                }
                let present = matches!(
                    items.borrow().get(index),
                    Some(item) if !matches!(item, Value::Native(Native::Hole, _))
                );
                if !present {
                    return None;
                }
                Some(if frozen {
                    Attributes {
                        writable: false,
                        enumerable: true,
                        configurable: false,
                    }
                } else {
                    Attributes::DEFAULT
                })
            }
            None => items.properties.borrow().get_own_attributes_key(key),
        },
        // An integer-indexed property's flags are fixed by the specification rather than
        // stored: every live element is writable, enumerable and configurable, and every other
        // element key is simply absent.
        Value::TypedArray(view) => match canonical_numeric_index_key(key) {
            Some(index) => valid_integer_index(view, index).map(|_| Attributes::DEFAULT),
            None => view.properties.borrow().get_own_attributes_key(key),
        },
        other if exotic_properties(other).is_some() => exotic_properties(target)
            .filter(|_| !exotic_reserved_name_key(target, key))
            .and_then(|store| store.borrow().get_own_attributes_key(key)),
        // A string's characters are own properties, and immovable ones: nothing can rewrite or
        // delete `"abc"[1]`, which is why they are the one shape here with no writable slot.
        Value::String(text) => string_index_attributes_key(text, key),
        // A built-in owns its `name` and `length` the same way a compiled function does, and a
        // namespace or a method table owns whatever the tables answer for. None of it is stored
        // per value -- two reads of `Array.prototype.push` produce the same `Copy` marker, so
        // there is no per-value store to put it in -- so the realm's store answers first, and
        // the tables answer for everything it has nothing to say about.
        Value::Native(_, _)
        | Value::Callback(_, _)
        | Value::Settler(..)
        | Value::Capability(..)
        | Value::Element(_) => {
            if matches!(target, Value::Native(_, _) | Value::Callback(_, _)) {
                intrinsics.materialize(target);
            }
            match intrinsics.overridden_key(target, key) {
                Overridden::Held(_, attributes) => Some(attributes),
                Overridden::Absent => None,
                Overridden::Untouched => tabulated_attributes_key(intrinsics, target, key),
            }
        }
        _ => None,
    }
}

/// The flags a built-in's own property was *created* with, before any program touched it.
fn tabulated_attributes(intrinsics: &Intrinsics, target: &Value, key: &str) -> Option<Attributes> {
    tabulated_attributes_key(intrinsics, target, PropertyKeyRef::Utf8(key))
}

fn tabulated_attributes_key(
    intrinsics: &Intrinsics,
    target: &Value,
    key: PropertyKeyRef<'_>,
) -> Option<Attributes> {
    let key = key.known_ascii()?;
    let key = key.as_ref();
    match key {
        "name" | "length" if intrinsic_identity(target).is_some() => Some(FUNCTION_IDENTITY),
        "length"
            if matches!(
                target,
                Value::Native(Native::PrototypeOf(PrototypeTable::Array), _)
            ) =>
        {
            Some(Attributes {
                writable: true,
                enumerable: false,
                configurable: false,
            })
        }
        // A built-in constructor's `prototype` is locked on every axis: the realm's intrinsics
        // are reachable through it, and letting a program move one would leave every instance
        // already made pointing at the old object.
        "prototype" if intrinsic_prototype_in(intrinsics, target).is_some() => {
            Some(Attributes::NONE)
        }
        _ => intrinsic_own_attributes(target, key),
    }
}

/// The flags on a built-in's own named property -- `Number.MAX_VALUE`, `Object.keys`,
/// `Array.prototype.push` -- or `None` when the built-in does not answer to that name.
///
/// The split is the specification's own convention and it falls out of what the property holds:
/// a method is replaceable and removable, while a *value* an intrinsic publishes -- a limit, a
/// well-known symbol, an element width -- is a constant, and locked on every axis.
/// The flags the own member `key` of a built-in carries, or `None` if there is no such member.
///
/// The existence test happens **once, here, before any rule can run**, and the rules themselves
/// live in [`published_attributes`], which returns `Attributes` rather than `Option<Attributes>`
/// and so cannot describe something that is not there.
///
/// That split is not tidiness. This function used to be a run of early returns, each deciding
/// flags from the *name* alone, and attributes are asked before the value is -- so a rule that
/// fired for a name the table does not publish did not merely mis-describe a property, it invented
/// one. Generalising a single rule from `Date` to every prototype gave every prototype in the
/// realm a phantom own `@@toPrimitive`; the fix at the time was to remember to add an existence
/// check to that rule and to the one beside it. Remembering is what failed in the first place.
fn intrinsic_own_attributes(target: &Value, key: &str) -> Option<Attributes> {
    let Value::Native(native, _) = target else {
        return None;
    };
    if let Native::PrototypeOf(
        table @ (PrototypeTable::Symbol
        | PrototypeTable::Array
        | PrototypeTable::Number
        | PrototypeTable::Boolean
        | PrototypeTable::BigInt
        | PrototypeTable::Promise
        | PrototypeTable::Object),
    ) = native
    {
        let proto_id = match table {
            PrototypeTable::Symbol => kiln_builtin_surface::PrototypeId::Symbol,
            PrototypeTable::Array => kiln_builtin_surface::PrototypeId::Array,
            PrototypeTable::Number => kiln_builtin_surface::PrototypeId::Number,
            PrototypeTable::Boolean => kiln_builtin_surface::PrototypeId::Boolean,
            PrototypeTable::BigInt => kiln_builtin_surface::PrototypeId::BigInt,
            PrototypeTable::Promise => kiln_builtin_surface::PrototypeId::Promise,
            PrototypeTable::Object => kiln_builtin_surface::PrototypeId::Object,
            _ => unreachable!(),
        };
        return kiln_builtin_surface::find_prototype_member(proto_id, key).map(|member| {
            Attributes {
                writable: member.attributes.writable,
                enumerable: member.attributes.enumerable,
                configurable: member.attributes.configurable,
            }
        });
    }
    if string_exotic(target, key).is_some() {
        return Some(Attributes::NONE);
    }
    // Accessors are the one kind with no slot to look up -- the "value" is a getter -- so they
    // are settled before the value lookup rather than by it. Both of these answer only for names
    // that genuinely are accessors on this target, so neither can invent one.
    //
    // An accessor carries no `writable` at all: the flag is not part of its descriptor, so the
    // `false` is the absence of one rather than a claim about assignment.
    if intrinsic_accessor(target, key).is_some() || machine_accessor(target, key).is_some() {
        return Some(Attributes {
            writable: false,
            enumerable: false,
            configurable: true,
        });
    }
    // The single existence test, and it asks about *ownership* rather than about what a read
    // would find. `Native::property` carries a prototype table its last step up to
    // `Object.prototype`, which is right for a read and wrong here: asking it made every built-in
    // prototype in the realm claim `hasOwnProperty`, `valueOf` and the other nine as its own,
    // which `getOwnPropertyNames` denied in the same breath.
    let found = match intrinsic_owns(*native, key) {
        None | Some(Value::Undefined) => return None,
        Some(value) => value,
    };
    Some(published_attributes(target, *native, key, &found))
}

/// The flags a built-in member carries, given the member.
///
/// Total by design: every path answers, because the caller has already established that there is
/// something to answer about. There is no way to spell "and also this name does not exist" here,
/// which is the point -- that question has exactly one asker.
fn published_attributes(target: &Value, native: Native, key: &str, found: &Value) -> Attributes {
    // A Node builtin module's exports are *enumerable*, which is how `{ ...require("path") }`
    // and every `export * from "path"` re-export shim a bundler emits copies them.
    // `Object.keys(require("path"))` was 0 against node's 17 while every individual member read
    // correctly, so those shims produced empty objects and said nothing about it. This used to
    // name `node:buffer` alone, because that is the one module somebody had needed it for.
    //
    // The global `Buffer` is here for the same reason and was not: node builds its statics by
    // assignment, so `for (key in Buffer)` yields `isBuffer` and the rest, and `safer-buffer`
    // rebuilds its export by copying exactly what that loop finds. Ours were own, readable and
    // reported by `getOwnPropertyNames` -- but not enumerable, so the loop found nothing and
    // `safer.Buffer.isBuffer` came out undefined. `iconv-lite` takes its Buffer from there, and
    // express's body reader took the resulting TypeError, having already served a correct 200.
    if (node_builtin_specifier(native).is_some() || matches!(native, Native::NodeBufferGlobal))
        && intrinsic_static_property_names(target).contains(&key)
    {
        return Attributes::DEFAULT;
    }
    // `Function.prototype[Symbol.hasInstance]` is the one built-in the specification locks on
    // *both* axes. It decides `instanceof` for every ordinary function in the realm, so a program
    // that could assign over it or delete it could change what every one of them answers.
    if matches!(native, Native::PrototypeOf(PrototypeTable::Function))
        && key == WellKnown::HasInstance.property_key()
    {
        return Attributes {
            writable: false,
            enumerable: false,
            configurable: false,
        };
    }
    // An `@@toPrimitive` a prototype publishes is read-only wherever it appears -- `Date` and
    // `Symbol` both have one. It is what `ToPrimitive` finds before anything else, so a program
    // that could assign over it could change what every value of that type coerces to.
    if matches!(native, Native::PrototypeOf(_)) && key == WellKnown::ToPrimitive.property_key() {
        return Attributes {
            writable: false,
            enumerable: false,
            configurable: true,
        };
    }
    if matches!(native, Native::PrototypeOf(PrototypeTable::Array)) && key == "length" {
        return Attributes {
            writable: true,
            enumerable: false,
            configurable: false,
        };
    }
    if found.type_of() == "function" {
        return Attributes::BUILT_IN;
    }
    // `Array.prototype[@@unscopables]` is a data property the specification locks against
    // assignment and leaves configurable, exactly as it does the tag below.
    if key == WellKnown::Unscopables.property_key() {
        return Attributes {
            writable: false,
            enumerable: false,
            configurable: true,
        };
    }
    // `@@toStringTag` is the one built-in *value* the specification leaves configurable, and it
    // has to be: the tag is what `Object.prototype.toString` reads, and a program that wants the
    // plain `[object Object]` back has no way to get it except by deleting the tag. Locked on
    // every axis, `delete Map.prototype[Symbol.toStringTag]` answered false and recorded nothing.
    // Below the callable test, as it has always been: the tag is a string, so the two cannot both
    // match, and keeping the order means this reshuffle changes nothing.
    if key == WellKnown::ToStringTag.property_key() {
        return Attributes {
            writable: false,
            enumerable: false,
            configurable: true,
        };
    }
    Attributes::NONE
}

/// The `prototype` a built-in constructor owns, or `None` for a built-in that is not one.
fn intrinsic_prototype(target: &Value) -> Option<Value> {
    let Value::Native(native, _) = target else {
        return None;
    };
    // `Function.prototype` is itself callable, and it is the one intrinsic function that has no
    // `prototype` of its own -- asking it for one would otherwise loop straight back to itself.
    if matches!(native, Native::PrototypeOf(_)) {
        return None;
    }
    match native.property("prototype") {
        Some(Value::Undefined) | None => None,
        Some(prototype) => Some(prototype),
    }
}

/// [`intrinsic_prototype`], and the nine error constructors it cannot answer for.
///
/// Their prototypes are per-realm objects the store builds on demand rather than table entries,
/// so a `&Value` alone cannot reach one -- which is exactly why `Error` reported no own
/// `prototype` at all until this existed. Every caller here already holds the store.
fn intrinsic_prototype_in(intrinsics: &Intrinsics, target: &Value) -> Option<Value> {
    if let Value::Native(Native::Error(kind), realm) = target {
        return Some(intrinsics.error_prototype(*kind, *realm));
    }
    intrinsic_prototype(target)
}

fn string_index_attributes_key(text: &StringUnits, key: PropertyKeyRef<'_>) -> Option<Attributes> {
    if key.matches_ascii("length") {
        return Some(Attributes::NONE);
    }
    let index = array_index_key(key)?;
    (index < text.unit_len()).then_some(Attributes {
        writable: false,
        enumerable: true,
        configurable: false,
    })
}

/// One own property described as the object `Object.getOwnPropertyDescriptor` returns.
///
/// The shape and the flags both come from [`own_property_state`], which is what
/// `Object.defineProperty` validates against: a descriptor a program reads and a definition it
/// then makes have to be talking about the same property, and two walks of the same shapes would
/// be two chances to disagree.
fn own_descriptor_key(
    intrinsics: &Intrinsics,
    target: &Value,
    key: PropertyKeyRef<'_>,
) -> Option<Value> {
    let (property, attributes) = own_property_state_key(intrinsics, target, key)?;
    let mut data = ObjectData::default();
    match property {
        Property::Value(value) => {
            data.set("value", value);
            data.set("writable", Value::Boolean(attributes.writable));
        }
        Property::Accessor { get, set } => {
            data.set("get", get.unwrap_or(Value::Undefined));
            data.set("set", set.unwrap_or(Value::Undefined));
        }
    }
    data.set("enumerable", Value::Boolean(attributes.enumerable));
    data.set("configurable", Value::Boolean(attributes.configurable));
    Some(Value::Object(Rc::new(RefCell::new(data))))
}

/// `flat`: splice nested arrays into the result, down to `depth` levels.
fn flatten(items: &[Value], depth: usize) -> Vec<Value> {
    let mut out = Vec::new();
    for item in items {
        match item {
            // A hole vanishes rather than becoming undefined, which is the one place `flat`
            // differs from copying.
            Value::Native(Native::Hole, _) => {}
            Value::Array(nested) if depth > 0 => {
                out.extend(flatten(&nested.borrow(), depth - 1));
            }
            other => out.push(other.clone()),
        }
    }
    out
}

/// An array's elements with every hole replaced by `undefined`.
///
/// Whatever *reads* an element gets undefined, so anything that copies elements out in bulk --
/// spread, `Array.from`, an iterator -- has to do the same replacement a single read does, or
/// the marker escapes into a value.
fn dense_items(items: &[Value]) -> Vec<Value> {
    items
        .iter()
        .map(|item| {
            if matches!(item, Value::Native(Native::Hole, _)) {
                Value::Undefined
            } else {
                item.clone()
            }
        })
        .collect()
}

/// How a console reports a run of holes: `<1 empty item>` or `<3 empty items>`.
fn empty_items(count: usize) -> String {
    if count == 1 {
        "<1 empty item>".to_owned()
    } else {
        format!("<{count} empty items>")
    }
}

/// A property name as a console writes it: bare when it is a plain identifier, quoted otherwise.
///
/// `$` is not in the set, which looks like an oversight and is not: node's own rule is
/// `/^[a-zA-Z_][a-zA-Z_0-9]*$/`, so `{ a$b: 1 }` prints with its key quoted and so does `{ 3: 1 }`.
/// Matching node exactly is what lets `scripts/differential.sh` diff console output at all.
/// The name a console shows for a function the runtime supplies rather than the program.
///
/// Derived from the variant rather than tabulated. A table of two hundred names would be two
/// hundred chances to disagree with the property table that actually resolves the name, and it
/// would go stale one variant at a time. The variants are spelled `<Type><Method>`, so removing
/// the type and lowering the first letter recovers the JavaScript name --
/// `conformance/differential/builtin-names.js` checks that against node for every builtin the
/// corpus can reach.
/// The name a console shows for a runtime-supplied callable.
///
/// `Error(Type)` is the one variant whose payload names the function rather than its
/// implementation, and the payload is spelled `Type` where the language spells it `TypeError` --
/// so it is answered from the same table that binds the global, not from the variant. Every other
/// name is derived, for the reason [`builtin_js_name`] gives.
/// The `NativeFunction` form: what `Function.prototype.toString` must answer for a built-in.
///
/// The specification allows an implementation-defined string here but requires this *shape*, and
/// the shape is what programs read. Feature detection across the ecosystem is written as
/// `/\{\s*\[native code\]/.test(String(fn))` to tell a real built-in from a polyfill that
/// replaced it, so this is not decoration -- it is the answer to a question real code asks.
fn native_code_source(name: &str) -> String {
    // A symbol-keyed built-in carries the reserved key internally -- `get @@species` -- and that
    // is not a PropertyName any source could write, so the grammar rejects the whole string and
    // `assertNativeFunction` reports the *function* as not native. Spelled as the computed key a
    // program would actually write, which is node's answer too:
    // `function get [Symbol.species]() { [native code] }`.
    let name = match name.find(symbol::RESERVED_KEY_PREFIX) {
        Some(at) => format!(
            "{}[Symbol.{}]",
            &name[..at],
            &name[at + symbol::RESERVED_KEY_PREFIX.len()..]
        ),
        None => name.to_owned(),
    };
    format!("function {name}() {{ [native code] }}")
}

fn native_js_name(native: &Native) -> String {
    if let Some(name) = crypto::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = zlib::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = os::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = path::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = querystring::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = url::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = string_decoder::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = util::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = diagnostics_channel::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = assert::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = tty::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = dns::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = perf_hooks::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = events::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = stream::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = net::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = http::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = fs::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = async_hooks::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = buffer::js_name(*native) {
        return name.to_owned();
    }
    if let Some(name) = console::js_name(*native) {
        return name.to_owned();
    }
    match native {
        Native::ProcessStartRaw => "__kilnHostProcessStart".to_owned(),
        Native::ProcessCancelRaw => "__kilnHostProcessCancel".to_owned(),
        Native::NodeModuleCreateRequire => "__kilnHostModuleCreateRequire".to_owned(),
        // A symbol-keyed method is named for the symbol in brackets, which is what the
        // specification's `SetFunctionName` does with a symbol key. Derivation would spell it
        // `functionHasInstance`, the name of a Rust variant rather than of anything a program
        // can see.
        Native::FunctionHasInstance => "[Symbol.hasInstance]".to_owned(),
        Native::SymbolToPrimitive => "[Symbol.toPrimitive]".to_owned(),
        // An accessor is named for what it reads, prefixed with the half it is.
        Native::TypedArrayToStringTag => "get [Symbol.toStringTag]".to_owned(),
        Native::StringToStringMethod => "toString".to_owned(),
        // A `DataView` accessor is named for the member it is published under, not for the Rust
        // variant behind it. Sixteen of them share four variants, so derivation gave all eight
        // getters the name `dataViewGet` -- which test262 checks by descriptor, and which any
        // program printing a stack or a method table shows.
        Native::DataViewGet(kind) => format!("get{}", kind.element_name()),
        Native::DataViewSet(kind) => format!("set{}", kind.element_name()),
        Native::DataViewGetBig { signed: true } => "getBigInt64".to_owned(),
        Native::DataViewGetBig { signed: false } => "getBigUint64".to_owned(),
        Native::DataViewSetBig { signed: true } => "setBigInt64".to_owned(),
        Native::DataViewSetBig { signed: false } => "setBigUint64".to_owned(),
        // `Array.prototype.toString` is `join` with no separator, which is what the variant is
        // named after -- but the member is `toString`.
        Native::ArrayJoinDefault => "toString".to_owned(),
        // Derivation cannot reach these: the payload is the whole of the name.
        Native::Intl(op) => intl::js_name(*op),
        Native::Temporal(op) => temporal::js_name(*op),
        Native::Error(kind) => kind.name().to_owned(),
        Native::Date(method) => method.js_name().to_owned(),
        // An accessor is named for what it reads, prefixed with the half it is -- which is what
        // a stack trace through `Object.getOwnPropertyDescriptor(...).get` prints.
        Native::RegExpAccessor(accessor) => format!("get {}", accessor.property_key()),
        Native::BuiltinAccessor(accessor) => format!("get {}", accessor.property_key()),
        Native::SetOperation(operation) => operation.property_key().to_owned(),
        Native::Uint8Text(conversion) => conversion.key().to_owned(),
        Native::ArrayCopy(method) => method.property_key().to_owned(),
        Native::StringHtml(wrapper) => wrapper.property_key().to_owned(),
        Native::RegExpSymbol(method) => method.js_name(),
        // The derivation works from the variant's `Debug` spelling, and for these the payload is
        // the whole of the name: `IteratorLazy(Map)` would otherwise be `iteratorLazy`.
        Native::IteratorLazy(kind) => kind.property_key().to_owned(),
        Native::IteratorTerminal(kind) => kind.property_key().to_owned(),
        Native::IteratorDispose => "[Symbol.dispose]".to_owned(),
        // The derivation has no `Iterator` in its table of type prefixes, so these three would
        // keep it. Only the first is a name a program can read; the other two are the helper's
        // own methods, named for what they are.
        Native::IteratorConcat => "concat".to_owned(),
        Native::IteratorConcatNext => "next".to_owned(),
        Native::IteratorConcatReturn => "return".to_owned(),
        Native::IteratorZip { keyed: false } => "zip".to_owned(),
        Native::IteratorZip { keyed: true } => "zipKeyed".to_owned(),
        Native::IteratorZipNext => "next".to_owned(),
        Native::IteratorZipReturn => "return".to_owned(),
        // The derivation strips a leading type name, which for these three takes a word that is
        // part of the method rather than part of the type: `WeakRefDeref` lowers to `refDeref`.
        Native::AtomicsOp(op) => op.property_key().to_owned(),
        Native::CollectionGetOrInsert {
            computed: false, ..
        } => "getOrInsert".to_owned(),
        Native::CollectionGetOrInsert { computed: true, .. } => "getOrInsertComputed".to_owned(),
        Native::WeakRefDeref => "deref".to_owned(),
        Native::DisposableStackUse => "use".to_owned(),
        Native::DisposableStackAdopt => "adopt".to_owned(),
        Native::DisposableStackDefer => "defer".to_owned(),
        Native::DisposableStackMove => "move".to_owned(),
        Native::DisposableStackDispose => "dispose".to_owned(),
        Native::AsyncDisposableStackUse => "use".to_owned(),
        Native::AsyncDisposableStackAdopt => "adopt".to_owned(),
        Native::AsyncDisposableStackDefer => "defer".to_owned(),
        Native::AsyncDisposableStackMove => "move".to_owned(),
        Native::AsyncDisposableStackDisposeAsync => "disposeAsync".to_owned(),
        // The derivation lowers a trailing acronym as an ordinary word: `JsonRawJson` becomes
        // `rawJson`, and the language spells the second half in capitals.
        Native::JsonRawJson => "rawJSON".to_owned(),
        Native::JsonIsRawJson => "isRawJSON".to_owned(),
        Native::FinalizationRegistryRegister => "register".to_owned(),
        Native::FinalizationRegistryUnregister => "unregister".to_owned(),
        // The derivation has no `Iterator` in its table of type prefixes, so it spells this
        // `iteratorFrom` rather than `from`.
        Native::IteratorFrom => "from".to_owned(),
        // The payload is the whole of the name; the derivation would spell this
        // `typedArrayGeneric`.
        Native::TypedArrayGeneric(method) => (*method).to_owned(),
        Native::ShadowRealmConstructor => "ShadowRealm".to_owned(),
        Native::ShadowRealmEvaluate => "evaluate".to_owned(),
        Native::ShadowRealmImportValue => "importValue".to_owned(),
        Native::ThrowTypeError => String::new(),
        Native::ProtoGetter => "get __proto__".to_owned(),
        Native::ProtoSetter => "set __proto__".to_owned(),
        Native::LegacyAccessor { defines, setter } => match (defines, setter) {
            (true, false) => "__defineGetter__".to_owned(),
            (true, true) => "__defineSetter__".to_owned(),
            (false, false) => "__lookupGetter__".to_owned(),
            (false, true) => "__lookupSetter__".to_owned(),
        },
        // The derivation strips the type and lowers what is left, which spells this `utc`. A
        // case distinction the variant does not carry cannot be recovered from it.
        Native::DateUtc => "UTC".to_owned(),
        // A view constructor is named for its element type -- `Uint8Array`, `BigInt64Array` --
        // and the derivation cannot reach it: the payload it discards as "not part of the name"
        // is the only place the type is written, so what is left spells the family instead.
        Native::TypedArrayConstructor(kind) => kind.name().to_owned(),
        // The URI four are an acronym the variant spelling flattens: `DecodeUri` lowers to
        // `decodeUri`, and the language spells it `decodeURI`. A derivation cannot recover a case
        // distinction that the input does not carry, so these are named outright.
        // `SetTimeout` starts with a type name that is not its type: the derivation strips `Set`
        // -- the collection -- and answers `timeout`. A prefix that is a word in its own right is
        // the one thing a name derived from a variant cannot get right on its own.
        // THE SHARED SURFACE'S OWN NAMES.
        //
        // `kiln_builtin_surface::SURFACE` says which members each built-in has, and the key it
        // says it under *is* the name that member reports -- node makes that true for every
        // static on every built-in, measured. The native backend now reads the name out of the
        // row; this derivation cannot, because the table is keyed by `(global, member)` and
        // nothing here maps a `Native` back to one without inverting the crate dependency.
        //
        // So these are spelled out, and `every_surface_member_is_named_for_its_key` holds them to
        // the table by reading each member through the real property path. Thirteen of them were
        // wrong when that guard was written: the derivation strips a known type prefix and
        // lowercases what is left, and it has no prefix for `NodeBuffer`, `AbortSignal`,
        // `Performance` or `Error` -- so `Buffer.concat.name` was `"nodeBufferConcat"`, which is
        // this file's spelling of a variant handed to a program that asked what a function is
        // called. `ObjectOwnNames` is the other shape: a variant named for neither its type nor
        // its member, which no prefix rule could have recovered.
        //
        // Adding a prefix to the derivation's table would have fixed some of these and is the
        // wrong move: a longest-prefix strip over a growing list is what produced them, and
        // "Error" as a prefix would rename every error variant that follows it.
        Native::ObjectOwnNames => "getOwnPropertyNames".to_owned(),
        Native::ErrorCaptureStackTrace => "captureStackTrace".to_owned(),
        Native::ErrorIsError => "isError".to_owned(),
        // The derivation lowercases only the first character, so a name whose own spelling is
        // lower-case past a digit comes back with a capital in it: `f16Round` for `f16round`.
        Native::MathF16Round => "f16round".to_owned(),
        Native::PerformanceNow => "now".to_owned(),
        Native::AbortSignalAbort => "abort".to_owned(),
        Native::AbortSignalTimeout => "timeout".to_owned(),
        Native::AbortSignalAny => "any".to_owned(),
        // FOUR NAMES THE DERIVATION SPELLED OUT OF THE RUST VARIANT.
        //
        // These are not near-misses of capitalisation: each one handed a program the identifier
        // this implementation happens to use. `Buffer.name` read "nodeBufferGlobal" and `URL.name`
        // read "Url" -- node answers "Buffer" and "URL" -- and the two `node:` modules whose
        // default export is callable answered "nodeAssertOk" and "nodeEventEmitter" where node
        // answers "assert" and "EventEmitter". A name is what a program reads to tell one
        // function from another, so an internal spelling in it is a wrong answer and not a
        // cosmetic one; the native backend already gave three of the four the node answer, so
        // this was also the two engines disagreeing.
        Native::NodeEventEmitter => "EventEmitter".to_owned(),
        Native::SetTimeout => "setTimeout".to_owned(),
        Native::SetInterval => "setInterval".to_owned(),
        Native::SetImmediate => "setImmediate".to_owned(),
        Native::ClearImmediate => "clearImmediate".to_owned(),
        Native::EncodeUri => "encodeURI".to_owned(),
        Native::EncodeUriComponent => "encodeURIComponent".to_owned(),
        Native::DecodeUri => "decodeURI".to_owned(),
        Native::DecodeUriComponent => "decodeURIComponent".to_owned(),
        // The derivation works from the variant's `Debug` spelling, and a variant with a named
        // field prints the field too -- so these two would be named `transfer { preserve
        // resizability: true }`. The flag is which method this is, not part of what it is called.
        Native::ArrayBufferTransfer {
            preserve_resizability: true,
        } => "transfer".to_owned(),
        Native::ArrayBufferTransfer {
            preserve_resizability: false,
        } => "transferToFixedLength".to_owned(),
        other => builtin_js_name(&format!("{other:?}")),
    }
}

/// The name a namespace shows, or `None` for a callable.
///
/// `Json` is spelled `JSON` in the language, which is the one place the variant's spelling and
/// the program's disagree -- and the reason this is a table of three rather than a derivation.
const fn namespace_name(native: &Native) -> Option<&'static str> {
    match native {
        Native::Math => Some("Math"),
        Native::Json => Some("JSON"),
        Native::Intl(op) => intl::namespace_name(*op),
        Native::Temporal(op) => temporal::namespace_name(*op),
        Native::Reflect => Some("Reflect"),
        Native::Atomics => Some("Atomics"),
        // Lower-case because that is what the language calls it: `performance` is an object a
        // program reads `now` from, not a constructor it names. Being here rather than in the
        // callable arm is what makes `String(performance)` an object tag and stops
        // `Object.getPrototypeOf(performance)` claiming `Function.prototype` -- the same two
        // consequences `typeof` has, reaching the other two conversions.
        Native::Performance => Some("performance"),
        _ => None,
    }
}

fn builtin_js_name(variant: &str) -> String {
    // A payload is not part of the name: `DateField(Time)` is `getTime`'s implementation, not a
    // function called `DateField(Time)`.
    let variant = variant.split('(').next().unwrap_or(variant);
    // A constructor is named for its type, not for the word "Constructor".
    if let Some(type_name) = variant.strip_suffix("Constructor")
        && !type_name.is_empty()
    {
        return type_name.to_owned();
    }
    // `Object.prototype.toString` is spelled for what it reads, not for what it is called.
    if variant == "ObjectToStringTag" {
        return "toString".to_owned();
    }
    // Longest first, so `ArrayBuffer` is not read as `Array` followed by `Buffer`.
    const TYPES: [&str; 29] = [
        "AsyncGenerator",
        // Before the bare `Weak`, which is what the ordering rule above is for: `WeakMapGet`
        // lost only its first word and came out as `mapGet`, so every weak collection method
        // was named after a Rust variant rather than after itself.
        "WeakMap",
        "WeakSet",
        "ArrayBuffer",
        "TypedArray",
        "Collection",
        "Generator",
        "Primitive",
        // `Function.prototype.toString` is called `toString`, not `functionToString` -- and it is
        // the one whose name a program is most likely to read, because it is the one whose own
        // answer now names it. `FunctionConstructor` is not caught here: the suffix rule above
        // has already turned it into `Function`.
        "Function",
        "Promise",
        "Boolean",
        "Reflect",
        "Console",
        "Process",
        "RegExp",
        "String",
        "Symbol",
        "Object",
        "Number",
        "BigInt",
        "Global",
        "Array",
        "Proxy",
        "Date",
        "Json",
        "Math",
        "Weak",
        "Map",
        "Set",
    ];
    let method = TYPES
        .iter()
        .find_map(|type_name| {
            variant
                .strip_prefix(type_name)
                .filter(|rest| !rest.is_empty())
        })
        .unwrap_or(variant);
    let mut characters = method.chars();
    match characters.next() {
        Some(first) => first.to_lowercase().collect::<String>() + characters.as_str(),
        None => String::new(),
    }
}

fn inspect_key(key: &str) -> String {
    let mut characters = key.chars();
    let identifier = characters
        .next()
        .is_some_and(|first| first.is_ascii_alphabetic() || first == '_')
        && characters.all(|rest| rest.is_ascii_alphanumeric() || rest == '_');
    if identifier {
        key.to_owned()
    } else {
        quote_for_console(key)
    }
}

/// A string as a console shows it.
///
/// The quote character is whichever one the string does not already contain, so the common case
/// needs no escaping at all: `"it's"` rather than `'it\'s'`. Single, then double, then backtick,
/// which is node's order of preference.
fn quote_for_console(text: &str) -> String {
    let quote = if !text.contains('\'') {
        '\''
    } else if !text.contains('"') {
        '"'
    } else if !text.contains('`') && !text.contains("${") {
        '`'
    } else {
        '\''
    };

    let mut quoted = String::with_capacity(text.len() + 2);
    quoted.push(quote);
    for character in text.chars() {
        match character {
            other if other == quote => {
                quoted.push('\\');
                quoted.push(other);
            }
            '\\' => quoted.push_str("\\\\"),
            '\n' => quoted.push_str("\\n"),
            '\r' => quoted.push_str("\\r"),
            '\t' => quoted.push_str("\\t"),
            '\u{8}' => quoted.push_str("\\b"),
            '\u{c}' => quoted.push_str("\\f"),
            control if control < ' ' => quoted.push_str(&format!("\\x{:02X}", control as u32)),
            other => quoted.push(other),
        }
    }
    quoted.push(quote);
    quoted
}

/// Marks the containers on the path from the root, so a cycle prints once instead of forever.
struct InspectGuard<'a> {
    seen: &'a mut Vec<usize>,
}

impl<'a> InspectGuard<'a> {
    fn enter(seen: &'a mut Vec<usize>, container: *const ()) -> Option<Self> {
        let identity = container as usize;
        if seen.contains(&identity) {
            return None;
        }
        seen.push(identity);
        Some(Self { seen })
    }
}

impl Drop for InspectGuard<'_> {
    fn drop(&mut self) {
        self.seen.pop();
    }
}

/// The numeric value of a property key that is an array index.
///
/// An index is a canonical decimal in `0 ..= 2^32 - 2`; `"01"`, `"1.0"`, `"-1"` and `"4294967295"`
/// are ordinary string keys. Checking the round trip rather than just parsing is what draws that
/// line, and the line is observable: only an index enumerates early.
#[cfg(test)]
fn index_key(key: &str) -> Option<u32> {
    let index: u32 = key.parse().ok()?;
    (index != u32::MAX && index.to_string() == key).then_some(index)
}

#[deny(clippy::wildcard_enum_match_arm)]
fn strict_equal(left: &Value, right: &Value) -> bool {
    // Exhaustive on `left` deliberately. A wildcard here made every new representation compile
    // as "unequal to everything", including itself. Adding a `Value` variant must keep failing to
    // compile until its JavaScript equality semantics are chosen explicitly.
    match left {
        Value::Undefined => matches!(right, Value::Undefined),
        Value::Null => matches!(right, Value::Null),
        Value::Boolean(a) => matches!(right, Value::Boolean(b) if a == b),
        Value::Number(a) => matches!(right, Value::Number(b) if a == b),
        Value::String(a) => matches!(right, Value::String(b) if a == b),
        // A cell is compiler bookkeeping and never observable as a JavaScript value. Identity is
        // still the least surprising answer if malformed bytecode lets one reach this boundary.
        Value::Cell(a) => matches!(right, Value::Cell(b) if Rc::ptr_eq(a, b)),
        // One instance of each runtime-provided callable exists per realm.
        // The realm is part of the identity, not decoration on it. `other.Array` and `Array`
        // name the same built-in and are two different functions, which is the single fact every
        // cross-realm test in the suite turns on.
        Value::Native(a, left_realm) => {
            matches!(right, Value::Native(b, right_realm) if a == b && left_realm == right_realm)
        }
        Value::Callback(a, left_realm) => {
            matches!(right, Value::Callback(b, right_realm) if a == b && left_realm == right_realm)
        }
        // Every object/function representation compares by identity: `===` asks whether two
        // references name the same object, not whether their payloads happen to be equal.
        Value::Generator(a) => matches!(right, Value::Generator(b) if Rc::ptr_eq(a, b)),
        Value::Promise(a) => matches!(right, Value::Promise(b) if Rc::ptr_eq(a, b)),
        Value::RegExp(a) => matches!(right, Value::RegExp(b) if Rc::ptr_eq(a, b)),
        Value::Date(a) => matches!(right, Value::Date(b) if Rc::ptr_eq(a, b)),
        Value::Temporal(a) => matches!(right, Value::Temporal(b) if Rc::ptr_eq(a, b)),
        Value::Intl(a) => matches!(right, Value::Intl(b) if Rc::ptr_eq(a, b)),
        // A BigInt is a primitive: two of them are equal when the numbers are, however they were
        // built. This is deliberately value equality rather than `Rc` identity.
        Value::BigInt(a) => matches!(right, Value::BigInt(b) if a == b),
        // Two capability executors are the same function only when they hold the same record:
        // each `NewPromiseCapability` makes its own, and a program can compare the one it was
        // handed with the one it kept.
        Value::Capability(a) => {
            matches!(right, Value::Capability(b) if Rc::ptr_eq(a, b))
        }
        Value::Settler(a, one) => matches!(
            right,
            Value::Settler(b, other) if Rc::ptr_eq(a, b) && one == other
        ),
        // Identity, like every other function: a program may hold one and compare it later.
        Value::Element(a) => matches!(right, Value::Element(b) if Rc::ptr_eq(a, b)),
        Value::Array(a) => matches!(right, Value::Array(b) if Rc::ptr_eq(a, b)),
        Value::TypedArray(a) => matches!(right, Value::TypedArray(b) if Rc::ptr_eq(a, b)),
        Value::ArrayBuffer(a) => matches!(right, Value::ArrayBuffer(b) if Rc::ptr_eq(a, b)),
        Value::DataView(a) => matches!(right, Value::DataView(b) if Rc::ptr_eq(a, b)),
        Value::Proxy(a) => matches!(right, Value::Proxy(b) if Rc::ptr_eq(a, b)),
        Value::Bound(a) => matches!(right, Value::Bound(b) if Rc::ptr_eq(a, b)),
        Value::Wrapped(a) => matches!(right, Value::Wrapped(b) if Rc::ptr_eq(a, b)),
        // `require` and `require.resolve` share lookup state but are distinct function objects.
        Value::CommonJsRequire(a) => {
            matches!(right, Value::CommonJsRequire(b) if Rc::ptr_eq(a, b))
        }
        Value::CommonJsResolve(a) => {
            matches!(right, Value::CommonJsResolve(b) if Rc::ptr_eq(a, b))
        }
        Value::Symbol(a) => matches!(right, Value::Symbol(b) if a == b),
        Value::Object(a) => matches!(right, Value::Object(b) if Rc::ptr_eq(a, b)),
        Value::Function(a) => matches!(right, Value::Function(b) if Rc::ptr_eq(a, b)),
    }
}

/// `==`, the abstract equality comparison.
///
/// Not `strict_equal` with a coercion in front of it. The rules are their own algorithm and two
/// of them are not conversions at all: `null == undefined` is true while neither converts to the
/// other, and every comparison with NaN is false however it is spelled.
fn loose_equal_checked(left: &Value, right: &Value) -> Result<bool, ExecutionError> {
    Ok(match (left, right) {
        // Same type: `==` is `===`, including NaN being unequal to itself.
        (Value::Undefined | Value::Null, Value::Undefined | Value::Null) => true,
        (Value::Number(_), Value::Number(_))
        | (Value::String(_), Value::String(_))
        | (Value::Boolean(_), Value::Boolean(_))
        | (Value::Symbol(_), Value::Symbol(_)) => strict_equal(left, right),
        // Nullish compares equal to itself and to nothing else -- not even to 0 or "".
        (Value::Undefined | Value::Null, _) | (_, Value::Undefined | Value::Null) => false,
        // A boolean converts to a number *first*, so `[] == false` is true by way of "" and 0.
        (Value::Boolean(value), other) => {
            loose_equal_checked(&Value::Number(f64::from(*value)), other)?
        }
        (other, Value::Boolean(value)) => {
            loose_equal_checked(other, &Value::Number(f64::from(*value)))?
        }
        // A symbol converts to nothing, so it is equal only to itself and that case is above.
        (Value::Symbol(_), _) | (_, Value::Symbol(_)) => false,
        // `==` is the one place the two numeric types meet: it compares mathematical values, so
        // `1n == 1` is true where `1n === 1` is false. A non-integral number can never equal a
        // BigInt, and neither can a string that is not an integer.
        (Value::BigInt(big), Value::Number(number))
        | (Value::Number(number), Value::BigInt(big)) => {
            number.is_finite()
                && number.fract() == 0.0
                && num_bigint::BigInt::parse_bytes(format!("{number:.0}").as_bytes(), 10)
                    .is_some_and(|other| other == **big)
        }
        (Value::BigInt(big), Value::String(text)) | (Value::String(text), Value::BigInt(big)) => {
            text.to_scalar_string()
                .ok()
                .as_deref()
                .unwrap_or("")
                .trim()
                .parse::<num_bigint::BigInt>()
                .is_ok_and(|other| other == **big)
        }
        (Value::Number(number), Value::String(text))
        | (Value::String(text), Value::Number(number)) => {
            Value::String(text.clone()).as_number() == *number
        }
        // An object compares by identity against another object, and by its primitive form
        // against anything else -- which is what makes `[1] == 1` true.
        (Value::Object(_) | Value::Array(_), Value::Object(_) | Value::Array(_)) => {
            strict_equal(left, right)
        }
        (object @ (Value::Object(_) | Value::Array(_)), primitive) => {
            loose_equal_checked(&to_primitive(object)?, primitive)?
        }
        (primitive, object @ (Value::Object(_) | Value::Array(_))) => {
            loose_equal_checked(primitive, &to_primitive(object)?)?
        }
        _ => strict_equal(left, right),
    })
}

#[cfg(test)]
fn loose_equal(left: &Value, right: &Value) -> bool {
    loose_equal_checked(left, right).expect("test string coercion")
}

/// `ToPrimitive` with no hint, which for everything here means `toString`.
///
/// `valueOf` comes first in the specification and is skipped because nothing yet returns a
/// primitive from it; when a user-defined `valueOf` can exist, this needs the interpreter and
/// moves onto it.
fn to_primitive(value: &Value) -> Result<Value, ExecutionError> {
    Ok(Value::String(value.to_string_units_checked()?))
}

fn compare(left: &Value, right: &Value, predicate: OrderingPredicate) -> bool {
    if let (Value::String(left), Value::String(right)) = (left, right) {
        // ECMAScript compares strings by UTF-16 code units, rather than Unicode scalar values.
        let ordering = left.encode_utf16().cmp(right.encode_utf16());
        return match predicate {
            OrderingPredicate::Less => ordering.is_lt(),
            OrderingPredicate::LessEqual => ordering.is_le(),
            OrderingPredicate::Greater => ordering.is_gt(),
            OrderingPredicate::GreaterEqual => ordering.is_ge(),
        };
    }
    match predicate {
        OrderingPredicate::Less => left.as_number() < right.as_number(),
        OrderingPredicate::LessEqual => left.as_number() <= right.as_number(),
        OrderingPredicate::Greater => left.as_number() > right.as_number(),
        OrderingPredicate::GreaterEqual => left.as_number() >= right.as_number(),
    }
}

#[derive(Clone, Copy)]
enum OrderingPredicate {
    Less,
    LessEqual,
    Greater,
    GreaterEqual,
}

fn parse_number(value: &str) -> f64 {
    kiln_host_abi::string_to_number(value)
}

fn parse_number_units(value: &StringUnits) -> f64 {
    value
        .to_scalar_string()
        .map_or(f64::NAN, |text| parse_number(&text))
}

/// A number as `String(value)` renders it.
///
/// Delegates to the ABI crate rather than repeating the rules: both halves must agree about what
/// `String(1e21)` is, and the surest way for two copies to agree is for there to be one.
pub(crate) fn number_string(value: f64) -> String {
    kiln_host_abi::number_to_js_string(value)
}

